package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.PvPLeaderboardPlugin;
import com.pvp.leaderboard.config.PvPLeaderboardConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;

/**
 * In-game popup notification for incoming PvP lobby invites. Painted
 * to mimic the OSRS Collection-Log "New item:" popup 1:1 — same
 * stone-brown frame, four L-bracket corner ornaments, top title bar
 * with an orange centred title and a darker separator line, white
 * centred body text underneath.
 *
 * <p>Visual reference: the in-game Collection-Log popup that fires
 * when a new item is logged. All colours / proportions tuned by
 * eyedropper against a screenshot of that widget so the two
 * notifications visually rhyme.
 *
 * <p>Lifecycle is single-shot: {@link #showInvite} stamps the active
 * notification + start time and the overlay's
 * {@link #render(Graphics2D)} handles the fade-in / hold / fade-out
 * animation and self-clears when the duration elapses. A second
 * invite while one is still on screen replaces the old one.
 *
 * <p><b>Body copy (2026-05-29 spec):</b> the body is a single
 * instruction sentence — "Click the [icon] on the right to accept a
 * fight from {sender}" — where {@code [icon]} is the plugin's RuneLite
 * sidebar nav icon drawn inline and {sender} is tinted with the
 * sender's rank-tier colour. The earlier "{sender} wants to fight:" +
 * style/build/location sub-line was dropped per the same spec, so the
 * overlay no longer carries any sub-text state.
 *
 * <p><b>Threading:</b> {@link #showInvite} is callable from any
 * thread; the overlay's render runs on the RuneLite game thread.
 * Active-state fields are {@code volatile} so the render path sees
 * the latest stamp without taking a lock.
 *
 * <p><b>Config gate:</b> the overlay short-circuits when
 * {@link PvPLeaderboardConfig#enableLobbyInviteNotification()} is
 * false, so users who find it noisy can disable it without
 * unregistering the overlay.
 */
@Slf4j
@Singleton
public final class LobbyInviteNotificationOverlay extends Overlay
{
    /** Fade-in duration at the start of each popup. Independent of
     *  the user-configurable hold duration — small enough that even
     *  the minimum 1-s total still has a visible hold segment. */
    private static final long FADE_IN_MS = 200L;
    /** Fade-out duration at the end of each popup. */
    private static final long FADE_OUT_MS = 400L;
    /** Floor for the total visible window so the fade-in + fade-out
     *  always fit with at least 200 ms of full-opacity hold. The
     *  config slider's {@code min=1} already enforces 1 s but this
     *  is the source-of-truth safety floor (defends against a
     *  hand-edited runelite.properties slipping a lower value past
     *  the {@code @Range} guard). */
    private static final long MIN_TOTAL_VISIBLE_MS = FADE_IN_MS + FADE_OUT_MS + 200L;

    // ---- Collection-Log popup palette (eyedropper from the widget) ----
    /** Frame stone-brown fill — main interior + title bar share this
     *  colour, the title bar is differentiated by the separator line
     *  alone (matches the vanilla widget). */
    private static final Color FRAME_FILL = new Color(0x4D, 0x46, 0x39);
    /** Outer 1-px hard outline that bounds the whole popup. */
    private static final Color OUTER_OUTLINE = new Color(0x12, 0x0F, 0x0A);
    /** Bevel highlight running just inside the outer outline — gives
     *  the frame its faint 3-D edge against the game viewport. */
    private static final Color FRAME_BEVEL = new Color(0x74, 0x69, 0x52);
    /** Horizontal separator under the title — same dark tone as the
     *  outer outline so the title visually detaches from the body. */
    private static final Color TITLE_SEPARATOR = new Color(0x1C, 0x18, 0x10);
    /** Bevel highlight running just below the title separator. */
    private static final Color TITLE_SEPARATOR_HI = new Color(0x6E, 0x63, 0x4D);
    /** Title text — RuneScape orange. */
    private static final Color TITLE_FG = new Color(0xFF, 0x98, 0x1F);
    /** Body text — slight cream off-white so it rhymes with OSRS UI. */
    private static final Color BODY_FG = new Color(0xFF, 0xFF, 0xFF);

    // ---- Popup geometry (eyedropper-tuned to mirror the vanilla widget) ----
    private static final int POPUP_W = 310;
    private static final int POPUP_H = 132;
    /** Title bar height (top section above the separator). */
    private static final int TITLE_BAR_H = 38;
    /** Distance from the top of the viewport. Sits below the OSRS
     *  XP-drop / wintertodt slot so it doesn't overlap vanilla
     *  notifications. */
    private static final int POPUP_TOP_OFFSET = 22;

    /** Body text size for the instruction sentence. */
    private static final float BODY_FONT_PT = 16f;

    /** Horizontal inset applied to each side of the body text block so
     *  the wrapped instruction never runs into the frame bevel. */
    private static final int BODY_SIDE_PAD = 12;

    /** The plugin's RuneLite sidebar nav icon, drawn inline in the
     *  body so "Click the [icon] on the right …" points the user at
     *  the exact toolbar button they need to press. Loaded once from
     *  the same resource the plugin's {@code NavigationButton} uses
     *  (anchored on {@link PvPLeaderboardPlugin} so the classpath
     *  lookup matches). {@code null} if the resource can't be read —
     *  the body still renders, just without the inline glyph. */
    private static final BufferedImage PANEL_ICON = loadPanelIcon();

    private static BufferedImage loadPanelIcon()
    {
        try
        {
            return ImageUtil.loadImageResource(PvPLeaderboardPlugin.class, "panel-icon.png");
        }
        catch (Throwable t)
        {
            log.warn("[LobbyInviteNotificationOverlay] failed to load panel-icon.png for inline popup glyph", t);
            return null;
        }
    }

    private final Client client;
    private final PvPLeaderboardConfig config;

    /** Wired post-construction by {@link com.pvp.leaderboard.PvPLeaderboardPlugin#startUp()}
     *  to {@code FightMonitor::isInCombat}. {@code null} until that
     *  wiring lands (and forever if the plugin runs without
     *  FightMonitor in some test harness) — the render path treats
     *  null as "not in combat" so a missing wiring never
     *  inadvertently suppresses every popup. */
    private volatile BooleanSupplier inCombatProvider;

    /** {@code invite_id} of the most-recently-shown invite. Sticky for
     *  the lifetime of the singleton (i.e. the lifetime of the
     *  plugin instance) so a re-push of the same invite — server-side
     *  replay on reconnect, a panel-side double-fire from racy
     *  bus events, etc. — does NOT pop the same popup twice. Cleared
     *  by {@link #clear()} which is only called on plugin shutdown,
     *  so the dedupe span is "until plugin off". */
    private volatile String lastShownInviteId;

    private volatile String activeSenderName;
    /** Tint for {@link #activeSenderName} in the body line. By spec
     *  the panel passes the same rank-tier colour the lobby row uses
     *  for this player, or {@link Color#WHITE} when the shard hasn't
     *  resolved their rank yet (the "Waiting" state). Falls back to
     *  white if the panel passes null (defensive, never happens in
     *  production). */
    private volatile Color activeSenderColor;
    private volatile long activeStartMs;

    /** Diagnostic state for the in-combat suppression DEBUG log. We
     *  emit at most THREE log lines per popup lifecycle:
     *  <ol>
     *    <li>{@code showInvite} call (always, when not deduped) —
     *        captures the in-combat / config / wiring state at the
     *        moment the invite enters the overlay.</li>
     *    <li>First decision in {@code renderInner} for THIS lifecycle
     *        — either "first paint" or "first defer".</li>
     *    <li>Transition from defer → paint (combat ended, popup
     *        finally surfaces).</li>
     *  </ol>
     *  Keyed off {@link #activeStartMs} (which is the per-lifecycle
     *  identifier — pinned forward each suppressed frame, so we
     *  compare against the FIRST stamp captured at {@code showInvite}
     *  time and stored in {@link #lifecycleId}). Reset each fresh
     *  {@code showInvite} call. Emitting at DEBUG (not INFO) so the
     *  default log level stays quiet — user must run with the
     *  {@code logback-debug.xml} profile to surface them. */
    private volatile long lifecycleId;
    /** True once we've emitted the first-decision (paint OR defer)
     *  log for {@link #lifecycleId}. Defends against 60 FPS log
     *  spam. */
    private volatile boolean firstDecisionLogged;
    /** True once we've started deferring this lifecycle. Used to
     *  detect the defer→paint transition for the third log line.
     *  Independent of {@link #firstDecisionLogged} so a popup that
     *  defers→paints emits both "first decision: defer" and
     *  "transitioned to paint" lines (full timeline visibility). */
    private volatile boolean wasDeferred;

    @Inject
    public LobbyInviteNotificationOverlay(Client client, PvPLeaderboardConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
    }

    /** Plugin wires {@code FightMonitor::isInCombat} here on
     *  startup. Pass {@code null} (or never call) to disable the
     *  combat-suppression branch entirely; pass a const-true / const-
     *  false supplier in tests. */
    public void setInCombatProvider(BooleanSupplier provider)
    {
        this.inCombatProvider = provider;
    }

    /**
     * Triggers a fresh popup for an incoming fight invite from
     * {@code senderName}. The body renders the fixed instruction
     * "Click the [icon] on the right to accept a fight from
     * {senderName}", with {@code senderName} tinted in
     * {@code senderColor}. Safe to call from any thread.
     *
     * <p><b>De-duplication:</b> if {@code inviteId} matches the last
     * invite this overlay rendered, the call is silently dropped —
     * the user has already seen the popup for this invite and a
     * second pop (server replay on reconnect, late bus delivery,
     * etc.) would just be visual noise. This is the source-of-truth
     * dedupe; the panel side does not need to guard.
     *
     * <p><b>Config gate:</b> when the popup is disabled in config we
     * still update {@link #lastShownInviteId} so re-enabling the
     * popup later doesn't suddenly surface a stale invite the user
     * "missed" while it was off.
     */
    public void showInvite(String inviteId, String senderName, Color senderColor)
    {
        if (senderName == null || senderName.isEmpty()) return;
        // Dedupe by invite id — once per id, ever (within this
        // plugin session). A null inviteId is treated as "no
        // dedupe info available" and always shows; in practice the
        // panel always passes a real id.
        if (inviteId != null && inviteId.equals(this.lastShownInviteId))
        {
            log.debug("[LobbyInvitePopup] showInvite SKIPPED (dedupe) inviteId={} sender={}",
                inviteId, senderName);
            return;
        }
        this.lastShownInviteId = inviteId;
        boolean enabled = config.enableLobbyInviteNotification();
        boolean suppressInCombat = config.suppressNotificationsInCombat();
        BooleanSupplier provider = this.inCombatProvider;
        boolean providerWired = provider != null;
        boolean inCombatNow = isInCombatSafe();
        log.debug("[LobbyInvitePopup] showInvite ACCEPTED inviteId={} sender={} popupEnabled={}"
                + " suppressInCombat={} inCombatProviderWired={} inCombatNow={}",
            inviteId, senderName, enabled, suppressInCombat, providerWired, inCombatNow);
        if (!enabled)
        {
            // Stamped as seen so a later toggle-on doesn't replay it,
            // but no on-screen state mutated.
            return;
        }
        this.activeSenderName = senderName;
        this.activeSenderColor = (senderColor != null) ? senderColor : Color.WHITE;
        long stamp = System.currentTimeMillis();
        this.activeStartMs = stamp;
        this.lifecycleId = stamp;
        this.firstDecisionLogged = false;
        this.wasDeferred = false;
    }

    /** Clears any pending popup AND the dedupe state. Called on
     *  plugin shutdown so the next plugin start can pop fresh
     *  invites without remembering ids from a prior session.
     *  Idempotent. */
    public void clear()
    {
        this.activeSenderName = null;
        this.activeSenderColor = null;
        this.activeStartMs = 0L;
        this.lastShownInviteId = null;
        this.lifecycleId = 0L;
        this.firstDecisionLogged = false;
        this.wasDeferred = false;
    }

    /** Effective total-visible window, in ms, derived from the
     *  user-configurable duration with the {@link #MIN_TOTAL_VISIBLE_MS}
     *  safety floor applied. Read each render so a mid-popup config
     *  change takes effect immediately. */
    private long totalVisibleMs()
    {
        long fromConfig = config.lobbyInviteNotificationDurationSeconds() * 1000L;
        return Math.max(MIN_TOTAL_VISIBLE_MS, fromConfig);
    }

    /** Null-safe wrapper around {@link #inCombatProvider}. Returns
     *  {@code false} (out-of-combat) when the provider hasn't been
     *  wired yet — defends against a startup-order race where the
     *  overlay registers with OverlayManager before
     *  {@code PvPLeaderboardPlugin.startUp} sets the provider. */
    private boolean isInCombatSafe()
    {
        BooleanSupplier provider = this.inCombatProvider;
        if (provider == null) return false;
        try
        {
            return provider.getAsBoolean();
        }
        catch (Throwable t)
        {
            // The render-path catch-all above would catch this too,
            // but failing a popup gate due to FightMonitor weirdness
            // shouldn't take out the whole render — log + treat as
            // out-of-combat (safer side: at worst the user sees a
            // popup during combat, never the reverse).
            log.warn("[LobbyInviteNotificationOverlay] inCombatProvider threw - treating as out-of-combat", t);
            return false;
        }
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        // Catch-all guard: any throwable from the inner body is logged
        // once with the overlay class name + a real stack (the first
        // allocation happens here, before HotSpot's
        // OmitStackTraceInFastThrow strips the trace from repeat
        // throws) and swallowed so OverlayRenderer doesn't WARN-spam
        // every frame at 60 FPS. See {@code RankOverlayRenderSafetyTest}
        // and the companion test in this class for the contract.
        try
        {
            return renderInner(g);
        }
        catch (Throwable t)
        {
            log.warn("[LobbyInviteNotificationOverlay] render threw - swallowing", t);
            return null;
        }
    }

    private Dimension renderInner(Graphics2D g)
    {
        if (!config.enableLobbyInviteNotification())
        {
            // Disabled mid-popup: drop active state so re-enabling
            // doesn't resume a partially-faded render.
            if (activeStartMs != 0L)
            {
                this.activeSenderName = null;
                this.activeSenderColor = null;
                this.activeStartMs = 0L;
            }
            return null;
        }
        // In-combat suppression — DEFER the popup instead of
        // dropping it (user-spec refinement 2026-05-25: "still show
        // the notification after the combat has ended"). Active
        // state (sender/subtext/colour) is preserved so the next
        // out-of-combat frame paints normally; activeStartMs is
        // pinned forward to "now" each suppressed frame so the
        // visible-window timer effectively freezes during combat —
        // otherwise an invite arriving at t=0 of a long combat
        // would burn its full N-second TTL before combat ends and
        // never render. {@code lastShownInviteId} stays intact so
        // a server replay of the same invite still dedupes.
        if (config.suppressNotificationsInCombat() && isInCombatSafe())
        {
            if (activeStartMs != 0L)
            {
                if (!firstDecisionLogged)
                {
                    log.debug("[LobbyInvitePopup] DEFER (in combat) lifecycleId={} sender={}",
                        lifecycleId, activeSenderName);
                    this.firstDecisionLogged = true;
                }
                this.wasDeferred = true;
                this.activeStartMs = System.currentTimeMillis();
            }
            return null;
        }
        String sender = activeSenderName;
        long start = activeStartMs;
        if (sender == null || start == 0L) return null;
        long totalMs = totalVisibleMs();
        long elapsed = System.currentTimeMillis() - start;
        if (elapsed >= totalMs)
        {
            // End-of-life: drop active state but DO NOT clear
            // lastShownInviteId — that's the dedupe key and must
            // outlive the visual window so a later re-push of the
            // same invite stays suppressed.
            this.activeSenderName = null;
            this.activeSenderColor = null;
            this.activeStartMs = 0L;
            return null;
        }
        // First-paint diagnostic: emits exactly once per lifecycle when
        // the popup actually paints (TTL not expired, sender stamped).
        // If it follows a "DEFER" line it's the defer→paint transition
        // (combat ended); if it's the first line for this lifecycleId
        // it's an immediate paint (no suppression engaged). This pair
        // of cases answers the critical user-facing question: "did
        // suppression engage at all for this invite, and if so when
        // did it release?"
        if (!firstDecisionLogged || wasDeferred)
        {
            log.debug("[LobbyInvitePopup] PAINT lifecycleId={} sender={} afterDefer={}",
                lifecycleId, sender, wasDeferred);
            this.firstDecisionLogged = true;
            this.wasDeferred = false;
        }

        // Three-segment alpha curve: 0 → 1 over FADE_IN_MS, 1.0 hold,
        // 1 → 0 over FADE_OUT_MS at the end. The hold segment
        // shrinks as the configured duration drops; the MIN guard in
        // totalVisibleMs() keeps it positive.
        float alpha;
        if (elapsed < FADE_IN_MS)
        {
            alpha = (float) elapsed / (float) FADE_IN_MS;
        }
        else if (elapsed > (totalMs - FADE_OUT_MS))
        {
            long fadeStart = totalMs - FADE_OUT_MS;
            alpha = 1f - ((float) (elapsed - fadeStart) / (float) FADE_OUT_MS);
        }
        else
        {
            alpha = 1f;
        }
        if (alpha < 0f) alpha = 0f;
        if (alpha > 1f) alpha = 1f;

        Dimension canvas = client.getRealDimensions();
        if (canvas == null) return null;
        int canvasW = canvas.width;
        int x = Math.max(0, (canvasW - POPUP_W) / 2);
        int y = POPUP_TOP_OFFSET;

        Composite prevComposite = g.getComposite();
        Stroke prevStroke = g.getStroke();
        Font prevFont = g.getFont();
        Object prevAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Object prevTAA = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
        try
        {
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

            paintFrame(g, x, y);
            paintTitleSeparator(g, x, y);
            paintText(g, x, y, sender);
        }
        finally
        {
            g.setComposite(prevComposite);
            g.setStroke(prevStroke);
            g.setFont(prevFont);
            if (prevAA != null) g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, prevAA);
            if (prevTAA != null) g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, prevTAA);
        }

        return new Dimension(POPUP_W, POPUP_H);
    }

    /** Paints the stone-brown rectangle + outer outline + inner bevel
     *  highlight. Anti-aliasing is forced OFF for the frame strokes
     *  so the 1-px outline lands on whole pixels (matches the crisp
     *  pixel-art aesthetic of vanilla OSRS UI; AA strokes would
     *  smear the outline to 2 px and look out-of-place). */
    private void paintFrame(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        // Main fill
        g.setColor(FRAME_FILL);
        g.fillRect(x, y, POPUP_W, POPUP_H);
        // Inner bevel highlight (drawn first so the outer outline
        // overdraws it at the very edge — pixel-perfect 1-px gap
        // between bevel and outer outline).
        g.setStroke(new BasicStroke(1f));
        g.setColor(FRAME_BEVEL);
        g.drawRect(x + 1, y + 1, POPUP_W - 3, POPUP_H - 3);
        // Outer outline
        g.setColor(OUTER_OUTLINE);
        g.drawRect(x, y, POPUP_W - 1, POPUP_H - 1);
    }

    /** Paints the dark separator strip (outline + bevel highlight
     *  pair) between the title bar and the body — same recipe as
     *  the outer frame's outline + bevel. */
    private void paintTitleSeparator(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setStroke(new BasicStroke(1f));
        int sepY = y + TITLE_BAR_H;
        // Dark separator
        g.setColor(TITLE_SEPARATOR);
        g.drawLine(x + 2, sepY, x + POPUP_W - 3, sepY);
        // Light bevel just below
        g.setColor(TITLE_SEPARATOR_HI);
        g.drawLine(x + 2, sepY + 1, x + POPUP_W - 3, sepY + 1);
    }

    /** Sentinel token marking where the inline sidebar icon is drawn
     *  inside the wrapped instruction sentence. Identity-compared in
     *  the layout loop (never rendered as text). */
    private static final Object ICON_TOKEN = new Object();

    /** Wrapper marking the rank-tier-coloured sender-name token so the
     *  layout loop can tint it differently from the plain body words. */
    private static final class NameToken
    {
        final String text;
        NameToken(String text) { this.text = text; }
    }

    /** Paints the title (orange, centred in the title bar) and the
     *  body instruction: "Click the [icon] on the right to accept a
     *  fight from {sender}". The sentence is word-wrapped to the body
     *  width with the sidebar icon drawn inline and the sender name
     *  tinted in its rank-tier colour. Text is rendered with AA on
     *  (smoother glyphs) while the frame paint above forced AA off for
     *  crisp 1-px strokes. */
    private void paintText(Graphics2D g, int x, int y, String sender)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        // Title — centred in the title bar
        Font titleFont = FontManager.getRunescapeBoldFont().deriveFont(20f);
        g.setFont(titleFont);
        FontMetrics tfm = g.getFontMetrics();
        String title = "PvP Invite";
        int titleX = x + (POPUP_W - tfm.stringWidth(title)) / 2;
        // Vertical centre of the title bar (inside the outer outline).
        int titleCenterY = y + 1 + TITLE_BAR_H / 2;
        int titleY = titleCenterY + (tfm.getAscent() - tfm.getDescent()) / 2;
        g.setColor(TITLE_FG);
        g.drawString(title, titleX, titleY);

        // Body — the single instruction sentence, word-wrapped.
        Font bodyFont = FontManager.getRunescapeBoldFont().deriveFont(BODY_FONT_PT);
        g.setFont(bodyFont);
        FontMetrics fm = g.getFontMetrics();
        int lineH = fm.getHeight();
        int spaceW = fm.stringWidth(" ");
        // Inline glyph sized to the text cap-height so it sits in the
        // run of words rather than towering over them.
        int iconSize = fm.getAscent();
        int maxW = POPUP_W - 2 * BODY_SIDE_PAD;

        // "Click the [icon] on the right to accept a fight from {name}"
        List<Object> tokens = new ArrayList<>();
        for (String w : new String[]{"Click", "the"}) tokens.add(w);
        tokens.add(ICON_TOKEN);
        for (String w : new String[]{"on", "the", "right", "to", "accept", "a", "fight", "from"}) tokens.add(w);
        tokens.add(new NameToken(sender));

        // Greedy word-wrap into lines that fit within maxW.
        List<List<Object>> lines = new ArrayList<>();
        List<Object> cur = new ArrayList<>();
        int curW = 0;
        for (Object t : tokens)
        {
            int tw = tokenWidth(t, fm, iconSize);
            int add = cur.isEmpty() ? tw : spaceW + tw;
            if (!cur.isEmpty() && curW + add > maxW)
            {
                lines.add(cur);
                cur = new ArrayList<>();
                curW = 0;
                add = tw;
            }
            cur.add(t);
            curW += add;
        }
        if (!cur.isEmpty()) lines.add(cur);

        // Vertically centre the wrapped block in the body region.
        int bodyTop = y + TITLE_BAR_H + 2;
        int bodyBottom = y + POPUP_H;
        int blockH = lines.size() * lineH;
        int blockTop = bodyTop + Math.max(0, ((bodyBottom - bodyTop) - blockH) / 2);

        // Sender colour set at showInvite from the panel's RankUtils
        // resolution; guard defensively against a clear/render race.
        Color senderColor = activeSenderColor != null ? activeSenderColor : BODY_FG;

        for (int i = 0; i < lines.size(); i++)
        {
            List<Object> line = lines.get(i);
            int lineW = lineWidth(line, fm, iconSize, spaceW);
            int cx = x + (POPUP_W - lineW) / 2;
            int baseline = blockTop + i * lineH + fm.getAscent();
            for (Object t : line)
            {
                int tw = tokenWidth(t, fm, iconSize);
                if (t == ICON_TOKEN)
                {
                    if (PANEL_ICON != null)
                    {
                        // Vertically centre the glyph on the text run.
                        int iconY = baseline - fm.getAscent()
                            + ((fm.getAscent() + fm.getDescent()) - iconSize) / 2;
                        g.drawImage(PANEL_ICON, cx, iconY, iconSize, iconSize, null);
                    }
                }
                else if (t instanceof NameToken)
                {
                    g.setColor(senderColor);
                    g.drawString(((NameToken) t).text, cx, baseline);
                }
                else
                {
                    g.setColor(BODY_FG);
                    g.drawString((String) t, cx, baseline);
                }
                cx += tw + spaceW;
            }
        }
    }

    /** Pixel width of a single layout token under {@code fm}. The icon
     *  token is a fixed {@code iconSize} square; name + word tokens
     *  measure their glyph run. */
    private static int tokenWidth(Object t, FontMetrics fm, int iconSize)
    {
        if (t == ICON_TOKEN) return iconSize;
        if (t instanceof NameToken) return fm.stringWidth(((NameToken) t).text);
        return fm.stringWidth((String) t);
    }

    /** Total pixel width of one wrapped line: the sum of its token
     *  widths plus a single space between adjacent tokens. */
    private static int lineWidth(List<Object> line, FontMetrics fm, int iconSize, int spaceW)
    {
        int w = 0;
        for (int i = 0; i < line.size(); i++)
        {
            if (i > 0) w += spaceW;
            w += tokenWidth(line.get(i), fm, iconSize);
        }
        return w;
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.config.PvPLeaderboardConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.util.function.BooleanSupplier;

/**
 * In-game popup notification for the "fight locked in" wire moment —
 * fires on {@code lobby/fight_proposed} (both perspectives: the inviter
 * just had their invite accepted, the invitee just clicked Accept on an
 * incoming invite). Painted with the same OSRS Collection-Log palette
 * and proportions as {@link LobbyInviteNotificationOverlay} so the two
 * popups visually rhyme.
 *
 * <p>Body content branches on who started the fight:
 * <ul>
 *   <li><b>Inviter perspective</b> (you sent the invite, they accepted):
 *       caption is {@code "<opponent> accepted your invite"} with the
 *       opponent's name tinted by their rank colour, and the sub-line
 *       is the style / build / location summary.</li>
 *   <li><b>Invitee perspective</b> (you accepted their invite):
 *       caption is just the opponent's name (rank-tinted, no trailing
 *       phrase — you already saw a "PvP Invite" popup a moment ago,
 *       this one confirms the match locked in). Sub-line is the same
 *       style / build / location summary.</li>
 * </ul>
 *
 * <p>Lifecycle is single-shot: {@link #showMatch} stamps the active
 * notification + start time and {@link #render(Graphics2D)} handles the
 * fade-in / hold / fade-out animation and self-clears when the
 * hardcoded {@link #TOTAL_VISIBLE_MS} window elapses. A second match
 * while one is still on screen replaces the old one.
 *
 * <p><b>Threading:</b> {@link #showMatch} is callable from any thread;
 * the overlay's render runs on the RuneLite game thread. Active-state
 * fields are {@code volatile} so the render path sees the latest stamp
 * without taking a lock.
 *
 * <p><b>Config gate:</b> the overlay short-circuits when
 * {@link PvPLeaderboardConfig#enableMatchFoundNotification()} is false,
 * so users who find it noisy can disable it without unregistering the
 * overlay.
 *
 * <p><b>Duration:</b> hardcoded at 5 s. The user-facing config exposes
 * only an on/off toggle (per the 2026-05-24 product spec — "match
 * found is more important than an invite, fewer knobs, longer hold").
 */
@Slf4j
@Singleton
public final class MatchFoundNotificationOverlay extends Overlay
{
    /** Fade-in duration at the start of each popup. */
    private static final long FADE_IN_MS = 200L;
    /** Fade-out duration at the end of each popup. */
    private static final long FADE_OUT_MS = 400L;
    /** Total on-screen window (includes fade in + fade out). Hardcoded
     *  per the product spec — no config slider exposed for this one. */
    private static final long TOTAL_VISIBLE_MS = 5_000L;

    // ---- Collection-Log popup palette (eyedropper from the widget) ----
    /** Frame stone-brown fill — main interior + title bar share this
     *  colour, the title bar is differentiated by the separator line
     *  alone (matches the vanilla widget). */
    private static final Color FRAME_FILL = new Color(0x4D, 0x46, 0x39);
    /** Outer 1-px hard outline that bounds the whole popup. */
    private static final Color OUTER_OUTLINE = new Color(0x12, 0x0F, 0x0A);
    /** Bevel highlight running just inside the outer outline. */
    private static final Color FRAME_BEVEL = new Color(0x74, 0x69, 0x52);
    /** Horizontal separator under the title. */
    private static final Color TITLE_SEPARATOR = new Color(0x1C, 0x18, 0x10);
    /** Bevel highlight running just below the title separator. */
    private static final Color TITLE_SEPARATOR_HI = new Color(0x6E, 0x63, 0x4D);
    /** Title text — RuneScape orange. */
    private static final Color TITLE_FG = new Color(0xFF, 0x98, 0x1F);
    /** Body text — slight cream off-white so it rhymes with OSRS UI. */
    private static final Color BODY_FG = new Color(0xFF, 0xFF, 0xFF);

    // ---- Popup geometry (eyedropper-tuned to mirror the vanilla widget) ----
    private static final int POPUP_W = 310;
    private static final int POPUP_H = 132;
    /** Title bar height (top section above the separator). */
    private static final int TITLE_BAR_H = 38;
    /** Distance from the top of the viewport. */
    private static final int POPUP_TOP_OFFSET = 22;

    /** Body text size — caption + sub-line share one bold font. */
    private static final float BODY_FONT_PT = 16f;

    private final Client client;
    private final PvPLeaderboardConfig config;

    /** Wired post-construction by {@link com.pvp.leaderboard.PvPLeaderboardPlugin#startUp()}
     *  to {@code FightMonitor::isInCombat}. {@code null} until that
     *  wiring lands; the render path treats null as "not in combat"
     *  so a missing wiring never inadvertently suppresses every popup. */
    private volatile BooleanSupplier inCombatProvider;

    /** {@code fight_session_id} of the most-recently-shown match. Sticky
     *  for the lifetime of the singleton so a re-push of the same
     *  fight_proposed event (server replay, bus double-fire) does NOT
     *  pop the same popup twice. Cleared by {@link #clear()} on
     *  plugin shutdown. */
    private volatile String lastShownFightSessionId;

    private volatile String activeOpponentName;
    private volatile String activeSubtext;
    /** When true, the caption is {@code "<opponent> accepted your invite"}
     *  (inviter perspective); when false, the caption is just the
     *  opponent name (invitee perspective). */
    private volatile boolean activeIsInviter;
    /** Rank-tier colour for the opponent name in the caption. Null is
     *  coerced to {@link Color#WHITE} at intake. */
    private volatile Color activeOpponentColor;
    private volatile long activeStartMs;

    /** Diagnostic state for the in-combat suppression DEBUG log —
     *  mirrors {@link LobbyInviteNotificationOverlay}. See its
     *  comments for the contract. */
    private volatile long lifecycleId;
    private volatile boolean firstDecisionLogged;
    private volatile boolean wasDeferred;

    @Inject
    public MatchFoundNotificationOverlay(Client client, PvPLeaderboardConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
    }

    /** Plugin wires {@code FightMonitor::isInCombat} here on
     *  startup. Pass {@code null} to disable the combat-suppression
     *  branch entirely; pass a const supplier in tests. */
    public void setInCombatProvider(BooleanSupplier provider)
    {
        this.inCombatProvider = provider;
    }

    /**
     * Triggers a fresh popup for a locked-in match against
     * {@code opponentName}. {@code subtext} is a short summary
     * ({@code "NH (Main) at Arena"}) that becomes the body's second
     * line. {@code isInviter} selects which caption variant the body
     * renders. Safe to call from any thread.
     *
     * <p><b>De-duplication:</b> if {@code fightSessionId} matches the
     * last fight this overlay rendered, the call is silently dropped.
     * This is the source-of-truth dedupe; the panel side does not need
     * to guard.
     *
     * <p><b>Config gate:</b> when the popup is disabled in config we
     * still update {@link #lastShownFightSessionId} so re-enabling the
     * popup later doesn't suddenly surface a stale match the user
     * "missed" while it was off.
     */
    public void showMatch(String fightSessionId,
                          String opponentName,
                          String subtext,
                          Color opponentColor,
                          boolean isInviter)
    {
        if (opponentName == null || opponentName.isEmpty()) return;
        if (fightSessionId != null && fightSessionId.equals(this.lastShownFightSessionId))
        {
            log.debug("[MatchFoundPopup] showMatch SKIPPED (dedupe) fightSessionId={} opponent={}",
                fightSessionId, opponentName);
            return;
        }
        this.lastShownFightSessionId = fightSessionId;
        boolean enabled = config.enableMatchFoundNotification();
        boolean suppressInCombat = config.suppressNotificationsInCombat();
        BooleanSupplier provider = this.inCombatProvider;
        boolean providerWired = provider != null;
        boolean inCombatNow = isInCombatSafe();
        log.debug("[MatchFoundPopup] showMatch ACCEPTED fightSessionId={} opponent={} popupEnabled={}"
                + " suppressInCombat={} inCombatProviderWired={} inCombatNow={}",
            fightSessionId, opponentName, enabled, suppressInCombat, providerWired, inCombatNow);
        if (!enabled)
        {
            // Stamped as seen so a later toggle-on doesn't replay it,
            // but no on-screen state mutated.
            return;
        }
        this.activeOpponentName = opponentName;
        this.activeSubtext = subtext == null ? "" : subtext;
        this.activeIsInviter = isInviter;
        this.activeOpponentColor = (opponentColor != null) ? opponentColor : Color.WHITE;
        long stamp = System.currentTimeMillis();
        this.activeStartMs = stamp;
        this.lifecycleId = stamp;
        this.firstDecisionLogged = false;
        this.wasDeferred = false;
    }

    /** Clears any pending popup AND the dedupe state. Called on
     *  plugin shutdown so the next plugin start can pop fresh matches
     *  without remembering ids from a prior session. Idempotent. */
    public void clear()
    {
        this.activeOpponentName = null;
        this.activeSubtext = null;
        this.activeIsInviter = false;
        this.activeOpponentColor = null;
        this.activeStartMs = 0L;
        this.lastShownFightSessionId = null;
        this.lifecycleId = 0L;
        this.firstDecisionLogged = false;
        this.wasDeferred = false;
    }

    /** Null-safe wrapper around {@link #inCombatProvider}. Returns
     *  {@code false} (out-of-combat) when the provider hasn't been
     *  wired yet — defends against a startup-order race. Mirrors
     *  the LobbyInviteNotificationOverlay companion helper. */
    private boolean isInCombatSafe()
    {
        BooleanSupplier provider = this.inCombatProvider;
        if (provider == null) return false;
        try
        {
            return provider.getAsBoolean();
        }
        catch (Throwable t)
        {
            log.warn("[MatchFoundNotificationOverlay] inCombatProvider threw - treating as out-of-combat", t);
            return false;
        }
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        // Catch-all guard mirrors LobbyInviteNotificationOverlay —
        // any throwable from the inner body is logged once with the
        // overlay class name + a real stack (the first allocation
        // happens here, before HotSpot's OmitStackTraceInFastThrow
        // strips the trace from repeat throws) and swallowed so
        // OverlayRenderer doesn't WARN-spam every frame at 60 FPS.
        try
        {
            return renderInner(g);
        }
        catch (Throwable t)
        {
            log.warn("[MatchFoundNotificationOverlay] render threw - swallowing", t);
            return null;
        }
    }

    private Dimension renderInner(Graphics2D g)
    {
        if (!config.enableMatchFoundNotification())
        {
            // Disabled mid-popup: drop active state so re-enabling
            // doesn't resume a partially-faded render.
            if (activeStartMs != 0L)
            {
                this.activeOpponentName = null;
                this.activeSubtext = null;
                this.activeIsInviter = false;
                this.activeOpponentColor = null;
                this.activeStartMs = 0L;
            }
            return null;
        }
        // In-combat suppression — DEFER the popup instead of
        // dropping it. Active state is preserved + activeStartMs is
        // pinned forward each suppressed frame so the visible-window
        // timer freezes during combat. Mirror of
        // {@link LobbyInviteNotificationOverlay} so both popups
        // share the 2026-05-25 user-spec contract: "still show the
        // notification after the combat has ended". The match-found
        // popup carries the meeting world + place — the user MUST
        // see it eventually, just not while taking hits.
        if (config.suppressNotificationsInCombat() && isInCombatSafe())
        {
            if (activeStartMs != 0L)
            {
                if (!firstDecisionLogged)
                {
                    log.debug("[MatchFoundPopup] DEFER (in combat) lifecycleId={} opponent={}",
                        lifecycleId, activeOpponentName);
                    this.firstDecisionLogged = true;
                }
                this.wasDeferred = true;
                this.activeStartMs = System.currentTimeMillis();
            }
            return null;
        }
        String opponent = activeOpponentName;
        long start = activeStartMs;
        if (opponent == null || start == 0L) return null;
        long elapsed = System.currentTimeMillis() - start;
        if (elapsed >= TOTAL_VISIBLE_MS)
        {
            // End-of-life: drop active state but DO NOT clear
            // lastShownFightSessionId — that's the dedupe key and
            // must outlive the visual window so a later re-push of
            // the same fight_proposed stays suppressed.
            this.activeOpponentName = null;
            this.activeSubtext = null;
            this.activeIsInviter = false;
            this.activeOpponentColor = null;
            this.activeStartMs = 0L;
            return null;
        }
        if (!firstDecisionLogged || wasDeferred)
        {
            log.debug("[MatchFoundPopup] PAINT lifecycleId={} opponent={} afterDefer={}",
                lifecycleId, opponent, wasDeferred);
            this.firstDecisionLogged = true;
            this.wasDeferred = false;
        }

        // Three-segment alpha curve: 0 → 1 over FADE_IN_MS, hold,
        // 1 → 0 over FADE_OUT_MS at the end.
        float alpha;
        if (elapsed < FADE_IN_MS)
        {
            alpha = (float) elapsed / (float) FADE_IN_MS;
        }
        else if (elapsed > (TOTAL_VISIBLE_MS - FADE_OUT_MS))
        {
            long fadeStart = TOTAL_VISIBLE_MS - FADE_OUT_MS;
            alpha = 1f - ((float) (elapsed - fadeStart) / (float) FADE_OUT_MS);
        }
        else
        {
            alpha = 1f;
        }
        if (alpha < 0f) alpha = 0f;
        if (alpha > 1f) alpha = 1f;

        Dimension canvas = client.getRealDimensions();
        if (canvas == null) return null;
        int canvasW = canvas.width;
        int x = Math.max(0, (canvasW - POPUP_W) / 2);
        int y = POPUP_TOP_OFFSET;

        Composite prevComposite = g.getComposite();
        Stroke prevStroke = g.getStroke();
        Font prevFont = g.getFont();
        Object prevAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Object prevTAA = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
        try
        {
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

            paintFrame(g, x, y);
            paintTitleSeparator(g, x, y);
            paintText(g, x, y, opponent);
        }
        finally
        {
            g.setComposite(prevComposite);
            g.setStroke(prevStroke);
            g.setFont(prevFont);
            if (prevAA != null) g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, prevAA);
            if (prevTAA != null) g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, prevTAA);
        }

        return new Dimension(POPUP_W, POPUP_H);
    }

    private void paintFrame(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setColor(FRAME_FILL);
        g.fillRect(x, y, POPUP_W, POPUP_H);
        g.setStroke(new BasicStroke(1f));
        g.setColor(FRAME_BEVEL);
        g.drawRect(x + 1, y + 1, POPUP_W - 3, POPUP_H - 3);
        g.setColor(OUTER_OUTLINE);
        g.drawRect(x, y, POPUP_W - 1, POPUP_H - 1);
    }

    private void paintTitleSeparator(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setStroke(new BasicStroke(1f));
        int sepY = y + TITLE_BAR_H;
        g.setColor(TITLE_SEPARATOR);
        g.drawLine(x + 2, sepY, x + POPUP_W - 3, sepY);
        g.setColor(TITLE_SEPARATOR_HI);
        g.drawLine(x + 2, sepY + 1, x + POPUP_W - 3, sepY + 1);
    }

    /** Paints the title (orange, centred in the title bar) + body's
     *  two centred lines. Caption layout branches on
     *  {@link #activeIsInviter} — sender-perspective glues
     *  {@code " accepted your invite"} onto the opponent name (split
     *  across two drawString calls so the opponent name keeps its
     *  rank-tier tint while the trailing phrase stays body off-white).
     *  Invitee-perspective draws just the rank-tinted opponent name.
     *  Both body lines use {@link #BODY_FONT_PT} Runescape Bold
     *  (matches {@link LobbyInviteNotificationOverlay} body styling). */
    private void paintText(Graphics2D g, int x, int y, String opponent)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        // Title — centred in the title bar.
        Font titleFont = FontManager.getRunescapeBoldFont().deriveFont(20f);
        g.setFont(titleFont);
        FontMetrics tfm = g.getFontMetrics();
        String title = "Match found!";
        int titleX = x + (POPUP_W - tfm.stringWidth(title)) / 2;
        int titleCenterY = y + 1 + TITLE_BAR_H / 2;
        int titleY = titleCenterY + (tfm.getAscent() - tfm.getDescent()) / 2;
        g.setColor(TITLE_FG);
        g.drawString(title, titleX, titleY);

        // Body caption + sub-line — both use the same bold Runescape
        // font at {@link #BODY_FONT_PT} (matches invite popup styling).
        Font bodyFont = FontManager.getRunescapeBoldFont().deriveFont(BODY_FONT_PT);
        g.setFont(bodyFont);
        FontMetrics bodyFm = g.getFontMetrics();
        boolean inviter = activeIsInviter;
        String tail = inviter ? " accepted your invite" : "";
        int opponentW = bodyFm.stringWidth(opponent);
        int tailW = bodyFm.stringWidth(tail);
        int captionX = x + (POPUP_W - (opponentW + tailW)) / 2;
        int bodyTop = y + TITLE_BAR_H + 2;
        int bodyBottom = y + POPUP_H;
        int bodyMidY = (bodyTop + bodyBottom) / 2;
        int captionY = bodyMidY - (bodyFm.getHeight() / 2);
        Color opponentColor = activeOpponentColor;
        g.setColor(opponentColor != null ? opponentColor : BODY_FG);
        g.drawString(opponent, captionX, captionY);
        if (tailW > 0)
        {
            g.setColor(BODY_FG);
            g.drawString(tail, captionX + opponentW, captionY);
        }

        String sub = activeSubtext;
        if (sub == null) sub = "";
        String trimmed = truncateToFit(sub, bodyFm, POPUP_W - 24);
        int subX = x + (POPUP_W - bodyFm.stringWidth(trimmed)) / 2;
        int subY = captionY + bodyFm.getHeight() - 2;
        g.setColor(BODY_FG);
        g.drawString(trimmed, subX, subY);
    }

    /** Truncates {@code text} with a trailing ellipsis so it fits in
     *  {@code maxWidth} pixels under {@code fm}. */
    private static String truncateToFit(String text, FontMetrics fm, int maxWidth)
    {
        if (fm.stringWidth(text) <= maxWidth) return text;
        String ell = "\u2026";
        int ellW = fm.stringWidth(ell);
        if (ellW >= maxWidth) return ell;
        int lo = 0;
        int hi = text.length();
        while (lo < hi)
        {
            int mid = (lo + hi + 1) >>> 1;
            int w = fm.stringWidth(text.substring(0, mid)) + ellW;
            if (w <= maxWidth) lo = mid;
            else hi = mid - 1;
        }
        return text.substring(0, lo) + ell;
    }
}

package com.pvp.leaderboard.overlay;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.event.MouseEvent;

/**
 * In-game warning popup shown after the player disabled the plugin
 * mid-fight in an LMS arena (a {@code plugin_disabled} freeze-log).
 *
 * <p>Painted in the same OSRS Collection-Log palette as
 * {@link MatchFoundNotificationOverlay} so the two popups visually
 * rhyme, but with two deliberate differences dictated by the
 * ban-warning product spec:
 * <ul>
 *   <li>It carries an explicit <b>OK</b> button the user must click to
 *       acknowledge — it does not silently fade away like the
 *       match-found toast. (It still self-dismisses after the 10 s
 *       window as a safety net so it can never wedge on screen.)</li>
 *   <li>It is <b>not</b> config-gated or in-combat-suppressed — the
 *       whole point is that the user sees the ban warning.</li>
 * </ul>
 *
 * <p>The plugin calls {@link #showWarning()} on the next
 * {@code LOGGED_IN} after the pending-warning config marker is found,
 * registers this overlay as a {@link MouseListener} so the OK click is
 * caught, and passes a {@link #setOnDismiss dismiss callback} that
 * clears the config marker. Dismissal (OK click OR 10 s elapse) fires
 * that callback exactly once.
 *
 * <p><b>Threading:</b> {@link #showWarning()} is callable from any
 * thread; render runs on the RuneLite game thread; the mouse callback
 * runs on the AWT thread. Active-state fields are {@code volatile}.
 */
@Slf4j
@Singleton
public final class PluginDisableWarningOverlay extends Overlay implements MouseListener
{
    /** Total on-screen window (safety self-dismiss). */
    static final long TOTAL_VISIBLE_MS = 10_000L;
    private static final long FADE_IN_MS = 200L;
    private static final long FADE_OUT_MS = 400L;

    /** The exact warning copy required by the product spec. */
    static final String[] BODY_LINES = {
        "Turning off a plugin mid fight will",
        "result in you being banned from",
        "the plugin. Do not do it again.",
    };
    private static final String TITLE = "Warning";
    private static final String OK_LABEL = "OK";

    // ---- Collection-Log popup palette (matches MatchFoundNotificationOverlay) ----
    private static final Color FRAME_FILL = new Color(0x4D, 0x46, 0x39);
    private static final Color OUTER_OUTLINE = new Color(0x12, 0x0F, 0x0A);
    private static final Color FRAME_BEVEL = new Color(0x74, 0x69, 0x52);
    private static final Color TITLE_SEPARATOR = new Color(0x1C, 0x18, 0x10);
    private static final Color TITLE_SEPARATOR_HI = new Color(0x6E, 0x63, 0x4D);
    private static final Color TITLE_FG = new Color(0xFF, 0x98, 0x1F);
    private static final Color BODY_FG = new Color(0xFF, 0xFF, 0xFF);
    private static final Color OK_FILL = new Color(0x3A, 0x34, 0x2A);
    private static final Color OK_FG = new Color(0xFF, 0x98, 0x1F);

    // ---- Geometry ----
    private static final int POPUP_W = 340;
    private static final int POPUP_H = 168;
    private static final int TITLE_BAR_H = 38;
    private static final int POPUP_TOP_OFFSET = 22;
    private static final float BODY_FONT_PT = 15f;
    private static final int OK_W = 60;
    private static final int OK_H = 24;
    private static final int OK_BOTTOM_MARGIN = 12;

    private final Client client;

    private volatile long activeStartMs;
    /** OK-button screen bounds from the last paint; consulted by the
     *  mouse handler. Null when not showing / not yet painted. */
    private volatile Rectangle okButtonBounds;
    /** Fired once on dismissal (OK click or timeout) — clears the
     *  config marker. */
    private volatile Runnable onDismiss;

    @Inject
    public PluginDisableWarningOverlay(Client client)
    {
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
    }

    /** Wire the config-marker-clearing callback (plugin start-up). */
    public void setOnDismiss(Runnable onDismiss)
    {
        this.onDismiss = onDismiss;
    }

    /** Show the warning. Safe from any thread; a re-show while one is
     *  already visible simply restarts the 10 s window. */
    public void showWarning()
    {
        this.okButtonBounds = null;
        this.activeStartMs = System.currentTimeMillis();
        log.debug("[LMSWarn] showWarning stamped");
    }

    /** Drop active state without firing the dismiss callback. Called on
     *  plugin shutdown. Idempotent. */
    public void clear()
    {
        this.activeStartMs = 0L;
        this.okButtonBounds = null;
    }

    boolean isShowing()
    {
        return activeStartMs != 0L;
    }

    /** Pure hit-test used by {@link #mousePressed}. */
    boolean isWithinOkButton(int mx, int my)
    {
        Rectangle r = this.okButtonBounds;
        return r != null && r.contains(mx, my);
    }

    /** Dismiss (OK click or timeout): drop state + fire the callback
     *  exactly once. */
    void dismiss()
    {
        boolean wasShowing = this.activeStartMs != 0L;
        this.activeStartMs = 0L;
        this.okButtonBounds = null;
        if (wasShowing)
        {
            Runnable cb = this.onDismiss;
            if (cb != null)
            {
                try
                {
                    cb.run();
                }
                catch (Exception e)
                {
                    log.debug("[LMSWarn] onDismiss callback threw: {}", e.getMessage());
                }
            }
        }
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        try
        {
            return renderInner(g);
        }
        catch (Throwable t)
        {
            log.warn("[PluginDisableWarningOverlay] render threw - swallowing", t);
            return null;
        }
    }

    private Dimension renderInner(Graphics2D g)
    {
        long start = activeStartMs;
        if (start == 0L)
        {
            return null;
        }
        long elapsed = System.currentTimeMillis() - start;
        if (elapsed >= TOTAL_VISIBLE_MS)
        {
            // Safety self-dismiss so the popup can never wedge on screen.
            dismiss();
            return null;
        }

        float alpha;
        if (elapsed < FADE_IN_MS)
        {
            alpha = (float) elapsed / (float) FADE_IN_MS;
        }
        else if (elapsed > (TOTAL_VISIBLE_MS - FADE_OUT_MS))
        {
            long fadeStart = TOTAL_VISIBLE_MS - FADE_OUT_MS;
            alpha = 1f - ((float) (elapsed - fadeStart) / (float) FADE_OUT_MS);
        }
        else
        {
            alpha = 1f;
        }
        if (alpha < 0f) alpha = 0f;
        if (alpha > 1f) alpha = 1f;

        Dimension canvas = client.getRealDimensions();
        if (canvas == null) return null;
        int x = Math.max(0, (canvas.width - POPUP_W) / 2);
        int y = POPUP_TOP_OFFSET;

        Composite prevComposite = g.getComposite();
        Stroke prevStroke = g.getStroke();
        Font prevFont = g.getFont();
        Object prevAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Object prevTAA = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
        try
        {
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
            paintFrame(g, x, y);
            paintTitleSeparator(g, x, y);
            paintText(g, x, y);
            paintOkButton(g, x, y);
        }
        finally
        {
            g.setComposite(prevComposite);
            g.setStroke(prevStroke);
            g.setFont(prevFont);
            if (prevAA != null) g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, prevAA);
            if (prevTAA != null) g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, prevTAA);
        }
        return new Dimension(POPUP_W, POPUP_H);
    }

    private void paintFrame(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setColor(FRAME_FILL);
        g.fillRect(x, y, POPUP_W, POPUP_H);
        g.setStroke(new BasicStroke(1f));
        g.setColor(FRAME_BEVEL);
        g.drawRect(x + 1, y + 1, POPUP_W - 3, POPUP_H - 3);
        g.setColor(OUTER_OUTLINE);
        g.drawRect(x, y, POPUP_W - 1, POPUP_H - 1);
    }

    private void paintTitleSeparator(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setStroke(new BasicStroke(1f));
        int sepY = y + TITLE_BAR_H;
        g.setColor(TITLE_SEPARATOR);
        g.drawLine(x + 2, sepY, x + POPUP_W - 3, sepY);
        g.setColor(TITLE_SEPARATOR_HI);
        g.drawLine(x + 2, sepY + 1, x + POPUP_W - 3, sepY + 1);
    }

    private void paintText(Graphics2D g, int x, int y)
    {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        Font titleFont = FontManager.getRunescapeBoldFont();
        g.setFont(titleFont);
        FontMetrics tfm = g.getFontMetrics();
        int titleW = tfm.stringWidth(TITLE);
        int titleX = x + (POPUP_W - titleW) / 2;
        int titleY = y + (TITLE_BAR_H + tfm.getAscent()) / 2 - 2;
        g.setColor(TITLE_FG);
        g.drawString(TITLE, titleX, titleY);

        Font bodyFont = FontManager.getRunescapeBoldFont().deriveFont(BODY_FONT_PT);
        g.setFont(bodyFont);
        FontMetrics bfm = g.getFontMetrics();
        g.setColor(BODY_FG);
        int lineH = bfm.getHeight();
        int startY = y + TITLE_BAR_H + 8 + bfm.getAscent();
        for (int i = 0; i < BODY_LINES.length; i++)
        {
            String line = BODY_LINES[i];
            int lw = bfm.stringWidth(line);
            int lx = x + (POPUP_W - lw) / 2;
            g.drawString(line, lx, startY + i * lineH);
        }
    }

    private void paintOkButton(Graphics2D g, int x, int y)
    {
        int okX = x + (POPUP_W - OK_W) / 2;
        int okY = y + POPUP_H - OK_H - OK_BOTTOM_MARGIN;
        // Record the screen-space bounds so the mouse handler can hit-test.
        this.okButtonBounds = new Rectangle(okX, okY, OK_W, OK_H);

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setColor(OK_FILL);
        g.fillRect(okX, okY, OK_W, OK_H);
        g.setStroke(new BasicStroke(1f));
        g.setColor(FRAME_BEVEL);
        g.drawRect(okX, okY, OK_W - 1, OK_H - 1);
        g.setColor(OUTER_OUTLINE);
        g.drawRect(okX - 1, okY - 1, OK_W + 1, OK_H + 1);

        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        Font okFont = FontManager.getRunescapeBoldFont();
        g.setFont(okFont);
        FontMetrics fm = g.getFontMetrics();
        int lw = fm.stringWidth(OK_LABEL);
        int lx = okX + (OK_W - lw) / 2;
        int ly = okY + (OK_H + fm.getAscent()) / 2 - 2;
        g.setColor(OK_FG);
        g.drawString(OK_LABEL, lx, ly);
    }

    // ---------------- MouseListener ----------------

    @Override
    public MouseEvent mousePressed(MouseEvent e)
    {
        if (isShowing() && isWithinOkButton(e.getX(), e.getY()))
        {
            log.debug("[LMSWarn] OK clicked - dismissing");
            dismiss();
            e.consume();
        }
        return e;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent e)
    {
        return e;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent e)
    {
        return e;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent e)
    {
        return e;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent e)
    {
        return e;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent e)
    {
        return e;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent e)
    {
        return e;
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.cache.MembershipCache;
import com.pvp.leaderboard.config.PvPLeaderboardConfig;
import com.pvp.leaderboard.game.PlayerRankEvent;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.util.NameUtils;
import com.pvp.leaderboard.util.RankUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Slf4j
@SuppressWarnings("deprecation")
public class RankOverlay extends Overlay
{
    private final Client client;
    private final PvPLeaderboardConfig config;
    private final PvPDataService pvpDataService;
    /** Opt-in membership set from the snapshot/delta feed (names only). The
     *  overlay gates rendering on this; rank itself comes from the name-keyed
     *  shards (see {@link #fetchSceneShardRankIfNeeded}). Replaces the
     *  whitelist.json membership blob (see PLAN_PRESENCE_FRESHNESS.md). */
    private final MembershipCache membershipCache;

    // Resolved rank labels keyed by canonical name — populated by the
    // API-set path (post-fight) and by scene/self shard lookups; read
    // every frame by the overlay render loop.
    private final ConcurrentHashMap<String, String> displayedRanks = new ConcurrentHashMap<>();

    // API-set ranks that should persist until shard cache refreshes with matching data
    private final ConcurrentHashMap<String, String> apiSetRanks = new ConcurrentHashMap<>();

    // Combat tracking for "hide rank out of combat" feature
    // Tracks when self was last in combat (milliseconds)
    private volatile long selfLastCombatMs = 0L;

    // Config change tracking
    private String lastBucketKey = null;

    // Self-rank scheduling
    private volatile long selfRefreshRequestedAtMs = 0L;
    private volatile boolean selfRankAttempted = false;
    private volatile long nextSelfRankAllowedAtMs = 0L;

    /** Scene shard lookup state for opted-in players visible in the
     *  world who don't yet have a rank label above their head. Retry
     *  throttle so render() (~60 fps) issues at most one shard
     *  resolution attempt per player per interval. Uses the passive
     *  ({@code bypassCache=false}) overload of
     *  {@link PvPDataService#getShardRankByName(String, String, boolean)}
     *  so repeat attempts are served from the 6h positive cache (once
     *  resolved) or the missing-player negative cache (when unranked),
     *  keeping CDN cost bounded even in a crowded scene. Bounded by
     *  membership + in-scene visibility + this per-player backoff —
     *  never a whole-world shard poll. */
    private static final long SCENE_SHARD_RETRY_MS = 30_000L;
    private final ConcurrentHashMap<String, Long> sceneShardLastAttemptMs = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Boolean> sceneShardInFlight = new ConcurrentHashMap<>();

    /** Negative backoff for the profile-API fallback used when a scene
     *  player misses the CDN shard (mirrors the lobby's shard→/user
     *  fallback). The shard GET is cheap + CDN/negative-cached, but the
     *  {@code /user} profile fetch is a Lambda+DynamoDB call, so a player
     *  who resolves in NEITHER shard nor profile must not re-hit /user on
     *  every {@link #SCENE_SHARD_RETRY_MS} tick. Positive resolutions are
     *  cached permanently in {@link #displayedRanks}, so this only rate
     *  limits genuinely-unresolvable players. */
    private static final long SCENE_PROFILE_MISS_BACKOFF_MS = 10L * 60L * 1000L;
    private final ConcurrentHashMap<String, Long> sceneProfileMissUntilMs = new ConcurrentHashMap<>();

    // MMR change notification queue (for multi-kill scenarios)
    private final java.util.concurrent.ConcurrentLinkedQueue<MmrNotification> mmrNotificationQueue = new java.util.concurrent.ConcurrentLinkedQueue<>();
    private volatile MmrNotification currentMmrNotification = null;
    private volatile long mmrNotificationStartMs = 0L;
    private volatile int lastNotificationTick = -1; // Track tick for 1-per-tick display

    // Legacy fields kept for backwards compatibility
    private volatile Double previousMmr = null;

    /**
     * Represents a single MMR change notification.
     */
    private static class MmrNotification {
        final double delta;
        final String bucketLabel;

        MmrNotification(double delta, String bucketLabel) {
            this.delta = delta;
            this.bucketLabel = bucketLabel;
        }
    }

    @Inject
    public RankOverlay(Client client, PvPLeaderboardConfig config, PvPDataService pvpDataService, 
                       MembershipCache membershipCache)
    {
        this.client = client;
        this.config = config;
        this.pvpDataService = pvpDataService;
        this.membershipCache = membershipCache;
        // Always use DYNAMIC for snap-to-player rendering
        // Use UNDER_WIDGETS layer (same as player indicators) so it appears above prayers
        // Use PRIORITY_LOW so it renders behind player indicator names
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPriority(Overlay.PRIORITY_LOW);
    }

    // Fixed height constants for consistent rank positioning regardless of equipment
    // Using fixed values prevents "jumping" when players wear different helmets/hats
    private static final int HEAD_HEIGHT = 220;      // At head level (just above player name)
    private static final int ABOVE_HEAD_HEIGHT = 268; // Above head (higher than head position)

    /**
     * Get the height offset for rendering rank based on position setting.
     * Uses fixed height constants instead of player.getLogicalHeight() to ensure
     * consistent positioning regardless of what equipment the player is wearing.
     * 
     * @return The height offset to use with getCanvasTextLocation
     */
    private int getHeightOffsetForPosition()
    {
        PvPLeaderboardConfig.RankPosition pos = config.rankPosition();
        // Defensive: a corrupted/missing persisted setting can return
        // null here. {@code switch (null)} would NPE every render frame
        // (~60 fps) and feed RuneLite's OverlayRenderer a stack-stripped
        // exception via HotSpot's OmitStackTraceInFastThrow. Fall back
        // to the same default the switch's default arm uses so behaviour
        // is identical to a normal {@code ABOVE_HEAD} setting.
        if (pos == null)
        {
            return ABOVE_HEAD_HEIGHT;
        }
        switch (pos)
        {
            case FEET:
                return 0; // At feet level
            case HEAD:
                return HEAD_HEIGHT; // At head level (just above player name)
            case ABOVE_HEAD:
            default:
                return ABOVE_HEAD_HEIGHT; // Above head (higher than head position)
        }
    }

    @Subscribe
    public void onPlayerRankEvent(PlayerRankEvent event)
    {
        if (event == null || event.getPlayerName() == null || event.getTier() == null)
        {
            return;
        }
        log.debug("[Overlay] onPlayerRankEvent: player={} tier={} bucket={}",
            event.getPlayerName(), event.getTier(), event.getBucket());
        setRankFromApi(event.getPlayerName(), event.getTier());
    }

    /**
     * Schedule a self-rank refresh after the given delay.
     */
    public void scheduleSelfRankRefresh(long delayMs)
    {
        long now = System.currentTimeMillis();
        nextSelfRankAllowedAtMs = now + Math.max(0L, delayMs);
        selfRankAttempted = false;
        selfRefreshRequestedAtMs = nextSelfRankAllowedAtMs;
    }

