    /**
     * Loads match history only if this is a new player search or data is stale (>1 hour old).
     * Called from game events - will skip refresh if data is fresh.
     */
    public void loadMatchHistoryIfNeeded(String playerId)
    {
        String normalizedId = normalizePlayerId(playerId);
        boolean isSamePlayer = normalizedId != null && normalizedId.equalsIgnoreCase(currentMatchesPlayerId);
        boolean isDataFresh = (System.currentTimeMillis() - lastRefreshTimestamp) < STALE_DATA_THRESHOLD_MS;

        // Skip if same player and data is fresh
        if (isSamePlayer && isDataFresh) {
            return;
        }

        loadMatchHistory(playerId);
    }

    /**
     * Loads match history only if NO player is currently being viewed.
     * This prevents game events from overwriting a user's active search.
     * Called on login/world hop - will not switch away from user's search.
     */
    public void loadMatchHistoryIfNotViewing(String playerId)
    {
        // If user is already viewing someone (searched for a player), don't overwrite
        if (currentMatchesPlayerId != null && !currentMatchesPlayerId.isEmpty()) {
            return;
        }

        // No one currently viewed - load the requested player (usually self)
        loadMatchHistory(playerId);
    }

    /**
     * Public entry point for the right-click "PvP lookup" menu (and any future
     * caller that wants to surface a specific player). Forces the Player Lookup
     * tab to the foreground BEFORE kicking off the match-history load so the
     * user actually sees the data they asked for.
     *
     * <p>Kept separate from {@link #loadMatchHistory(String)} on purpose:
     * loadMatchHistory is also invoked by auto-paths (login, game events,
     * refresh) where forcibly switching tabs would yank focus away from the
     * Matchmaking Lobby unexpectedly. Right-click menu = explicit intent =
     * tab switch is desired; everything else = silent background load.
     */
    public void openPlayerLookup(String playerId)
    {
        Runnable open = () ->
        {
            foldAltViewsToStats();
            setActiveTab(CARD_LOOKUP);
            loadMatchHistory(playerId);
        };
        if (SwingUtilities.isEventDispatchThread())
        {
            open.run();
        }
        else
        {
            SwingUtilities.invokeLater(open);
        }
    }

    /**
     * Forces a full refresh of match history. Called from explicit user actions (search, refresh button).
     */
    public void loadMatchHistory(String playerId)
    {
        final int gen = ++loadGeneration;
        currentMatchesPlayerId = normalizePlayerId(playerId);
        lastRefreshTimestamp = System.currentTimeMillis();

        Runnable uiReset = () -> {
            playerNameLabel.setText(playerId);
            if (loginPanel != null) loginPanel.setPluginSearchText(playerId);
            refreshButton.setVisible(true);
            matchHistoryBtn.setVisible(false);
            advancedToggle.setVisible(false);
            extraStatsPanel.setPlayerName(currentMatchesPlayerId);
            updateBlockButtonVisibility(currentMatchesPlayerId);
            resetUiForNewSearch();
        };
        if (SwingUtilities.isEventDispatchThread()) {
            uiReset.run();
        } else {
            SwingUtilities.invokeLater(uiReset);
        }

        try {
            String normalizedId = currentMatchesPlayerId;
            loadPlayerStats(normalizedId, gen);

            String selfName = plugin != null ? plugin.getLocalPlayerName() : null;
            String selfNameNormalized = normalizePlayerId(selfName);
            boolean isSelf = selfNameNormalized != null && selfNameNormalized.equalsIgnoreCase(normalizedId);

            if (isSelf) {
                String sha = pvpDataService.getSelfAcctSha();
                extraStatsPanel.setAcctSha(sha);
            } else {
                extraStatsPanel.setAcctSha(null);
            }

            CompletableFuture<JsonObject> matchesFuture;
            if (isSelf) {
                String selfAcctSha = pvpDataService.getSelfAcctSha();
                if (selfAcctSha != null && !selfAcctSha.isEmpty()) {
                    matchesFuture = pvpDataService.getPlayerMatchesByAcct(selfAcctSha, null, MATCHES_PAGE_SIZE, false);
                } else {
                    matchesFuture = pvpDataService.getPlayerMatches(normalizedId, null, MATCHES_PAGE_SIZE);
                }
            } else {
                matchesFuture = pvpDataService.getPlayerMatches(normalizedId, null, MATCHES_PAGE_SIZE);
            }

            matchesFuture.thenAccept(jsonResponse -> {
                if (gen != loadGeneration || jsonResponse == null)
                {
                    return;
                }

                JsonArray matches = jsonResponse.has("matches") && jsonResponse.get("matches").isJsonArray() ? jsonResponse.getAsJsonArray("matches") : new JsonArray();

                SwingUtilities.invokeLater(() -> {
                    if (gen != loadGeneration) return;
                    updateUiWithMatches(matches);
                });
            }).exceptionally(ex -> {
                return null;
            });
        } catch (Exception ex) {
            // ignored
        }
    }

    private void updateUiWithMatches(JsonArray matches) {
        chartPanel.setMatches(matches);
        extraStatsPanel.setMatches(matches);
        allMatches = matches;

        boolean hasData = matches != null && matches.size() > 0;
        matchHistoryBtn.setVisible(hasData);
        advancedToggle.setVisible(hasData);

        updateBucketBarsFromMatches();
    }

    private void resetUiForNewSearch()
            {
        rankProgressPanel.reset();
        performanceStatsPanel.reset();
        chartPanel.setMatches(new JsonArray());
        extraStatsPanel.setMatches(new JsonArray());
        allMatches = null;
    }

    private void loadPlayerStats(String playerId, int gen)
    {
        try {
            String clientUniqueId = (plugin != null) ? plugin.getClientUniqueId() : null;

            pvpDataService.getUserProfile(playerId, clientUniqueId).thenAccept(stats -> {
                if (gen != loadGeneration || stats == null)
                {
                    return;
                }
                // Re-enrich the lobby row once /user is cached — the
                // profile_cache fallback keys off display name while
                // the cache stores canonical lowercase ids.
                lobbyService.refreshRankForPlayer(playerId);
                SwingUtilities.invokeLater(() -> {
                    if (gen != loadGeneration) return;
                    updateProgressBars(stats, gen);
                });
            }).exceptionally(ex -> {
                return null;
            });
        } catch (Exception ex) {
            // ignored
        }
    }

    private void updateProgressBars(JsonObject stats, int gen)
    {
        String playerName = null;
        if (stats.has("player_name")) playerName = stats.get("player_name").getAsString();
        else if (stats.has("player_id")) playerName = stats.get("player_id").getAsString();

        if (playerName != null)
        {
            applyAllBucketStats(stats, playerName, gen);
        }

        if (stats.has("cumulative_stats") && stats.get("cumulative_stats").isJsonObject())
        {
            performanceStatsPanel.setCumulativeStats(stats.getAsJsonObject("cumulative_stats"));
        }

        if (stats.has("opponent_rank_stats_by_bucket") && stats.get("opponent_rank_stats_by_bucket").isJsonObject())
        {
            performanceStatsPanel.setOpponentRankStats(stats.getAsJsonObject("opponent_rank_stats_by_bucket"));
        }
    }

    private void applyAllBucketStats(JsonObject stats, String playerName, int gen)
    {
        applyBucketStatsFromUser(playerName, "overall", stats, gen);

        JsonObject bucketsObj = stats.has("buckets") ? stats.getAsJsonObject("buckets") : null;
        String[] bucketKeys = {"nh", "veng", "multi", "dmm"};
        for (String bucketKey : bucketKeys) {
            JsonObject bucketObj = (bucketsObj != null && bucketsObj.has(bucketKey)) ? bucketsObj.getAsJsonObject(bucketKey) : null;
            applyBucketStatsFromUser(playerName, bucketKey, bucketObj, gen);
        }
    }

    private void applyBucketStatsFromUser(String playerName, String bucketKey, JsonObject bucketObj, int gen)
    {
        if (bucketObj == null) {
            rankProgressPanel.updateBucket(bucketKey, "—", 0, 0, -1);
            return;
        }

        String rankLabel = "—";
        int division = 0;
        double pct = 0.0;
        double mmr = Double.NaN;

        if (bucketObj.has("mmr")) {
            mmr = bucketObj.get("mmr").getAsDouble();
            RankInfo ri = RankUtils.rankLabelAndProgressFromMMR(mmr);
            if (ri != null) { rankLabel = ri.rank; division = ri.division; pct = ri.progress; }
        }
        if (bucketObj.has("rank_progress")) {
             JsonObject rp = bucketObj.getAsJsonObject("rank_progress");
             if (rp.has("progress_to_next_rank_pct")) pct = rp.get("progress_to_next_rank_pct").getAsDouble();
        }
        if (bucketObj.has("rank")) {
             String r = bucketObj.get("rank").getAsString();
             if (!r.isEmpty()) rankLabel = r;
        }
        if (bucketObj.has("division")) division = bucketObj.get("division").getAsInt();

        final String fRank = rankLabel;
        final int fDiv = division;
        final double fPct = pct;
        final double fMmr = mmr;

        rankProgressPanel.updateBucket(bucketKey, fRank, fDiv, fPct, -1);

        if (!"—".equals(fRank)) {
            final String[] topHolder = new String[1];
            new SwingWorker<Integer, Void>() {
                @Override protected Integer doInBackground() {
                    // Background thread: compute the histogram percentile + rank
                    // number together so the rating row updates once with both.
                    topHolder[0] = computeTopPercent(bucketKey, fMmr);
                    return getRankNumberFromLeaderboard(playerName, bucketKey);
                }
                @Override protected void done() {
                     try {
                         if (gen != loadGeneration) return;
                         int rank = get();
                         rankProgressPanel.updateBucket(bucketKey, fRank, fDiv, fPct, rank > 0 ? rank : -1, topHolder[0]);
                    } catch (Exception ignore) {
                    }
                }
            }.execute();
        }
    }

    private void updateBucketBarsFromMatches() {
        if (allMatches == null || allMatches.size() == 0) return;
        String playerName = playerNameLabel.getText();
        if ("Player Name".equals(playerName)) return;

        final int gen = loadGeneration;
        String[] buckets = {"overall", "nh", "veng", "multi", "dmm"};
        for (String bucket : buckets)
        {
            JsonArray items = new JsonArray();
            for (int i = 0; i < allMatches.size(); i++)
            {
                JsonObject match = allMatches.get(i).getAsJsonObject();
                String matchBucket = match.has("bucket") ? match.get("bucket").getAsString().toLowerCase() : "";
                if (matchBucket.equals(bucket)) items.add(match);
            }

            if (items.size() == 0) continue;

            JsonObject latest = null;
            for (int i = 0; i < items.size(); i++)
            {
                JsonObject item = items.get(i).getAsJsonObject();
                if (latest == null ||
                    (item.has("when") && latest.has("when") &&
                     item.get("when").getAsLong() > latest.get("when").getAsLong()))
                {
                    latest = item;
                }
            }

            if (latest != null && latest.has("player_mmr"))
            {
                double mmr = latest.get("player_mmr").getAsDouble();
                RankInfo est = RankUtils.rankLabelAndProgressFromMMR(mmr);

                String finalRank = latest.has("player_rank") ? latest.get("player_rank").getAsString() : (est != null ? est.rank : "—");
                int finalDiv = latest.has("player_division") ? latest.get("player_division").getAsInt() : (est != null ? est.division : 0);
                double pct = (est != null ? est.progress : 0.0);

                final double finalMmr = mmr;
                final String[] topHolder = new String[1];
                new SwingWorker<Integer, Void>()
                {
                    @Override protected Integer doInBackground() {
                        topHolder[0] = computeTopPercent(bucket, finalMmr);
                        return getRankNumberFromLeaderboard(playerName, bucket);
                    }
                    @Override protected void done() {
                        try {
                            if (gen != loadGeneration) return;
                            int rankNumber = get();
                            rankProgressPanel.updateBucket(bucket, finalRank, finalDiv, pct, rankNumber > 0 ? rankNumber : -1, topHolder[0]);
                        } catch (Exception ignore) {
                        }
                    }
                }.execute();
            }
        }
    }

    // --- Helpers ---

    /**
     * The player's "Top X.XX%" for a bucket, derived from the cached rank
     * histogram ({@code rank_hist/<bucket>.json}). Runs on a background
     * thread (it blocks briefly on the cached future), so it must NOT be
     * called from the EDT. Reuses {@link PvPDataService#getRankHistogram}
     * which is backed by the shared 60-minute shard cache — so the histogram
     * for each bucket is fetched at most once per hour and shared with the
     * "What are the ranks" view, never re-fetched per lookup. Returns
     * {@code null} when it can't be determined so the caller omits the suffix.
     */
    private String computeTopPercent(String bucket, double mmr)
    {
        if (pvpDataService == null || !Double.isFinite(mmr)) return null;
        try {
            java.util.concurrent.CompletableFuture<JsonObject> f = pvpDataService.getRankHistogram(bucket);
            if (f == null) return null;
            JsonObject hist = f.get(5, java.util.concurrent.TimeUnit.SECONDS);
            if (hist == null) return null;
            long total = RankUtils.histogramTotal(hist);
            long atOrAbove = RankUtils.cumulativeCountAtOrAbove(hist, mmr);
            return RankUtils.formatTopPercentPrecise(atOrAbove, total);
        } catch (Exception ignore) {
            return null;
        }
    }

    public int getRankNumberFromLeaderboard(String playerName, String bucket)
    {
        try {
            String canonBucket = bucket == null ? "overall" : bucket.toLowerCase();
            // bypassCache=true: this method runs on a SwingWorker
            // background thread spawned from openPlayerLookup —
            // i.e. a user gesture. The 2026-05-24 backend handoff
            // moved shard writes to a DynamoDB-stream-driven path
            // with ≈30 s propagation, so an explicit "look this
            // player up" should pick up post-match rank changes
            // instead of serving the cached payload (which could
            // be up to 60 min stale).
            ShardRank sr = pvpDataService.getShardRankByName(playerName, canonBucket, true)
                .get(5, java.util.concurrent.TimeUnit.SECONDS);
            return sr != null && sr.rank > 0 ? sr.rank : -1;
        } catch (Exception ex) {
            return -1;
        }
    }

    private static String normalizePlayerId(String name) {
        return name != null ? name.trim().replaceAll("\\s+", " ").toLowerCase() : null;
    }

    private static void disableNestedWheelScrolling(Container container)
    {
        installSmartWheelForwarding(container);
    }

    private static void installSmartWheelForwarding(Container container)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JScrollPane)
            {
                addBoundaryForwarding((JScrollPane) child);
            }
            if (child instanceof Container)
            {
                installSmartWheelForwarding((Container) child);
            }
        }
        container.addContainerListener(new java.awt.event.ContainerAdapter()
        {
            @Override
            public void componentAdded(java.awt.event.ContainerEvent e)
            {
                Component c = e.getChild();
                if (c instanceof JScrollPane)
                {
                    addBoundaryForwarding((JScrollPane) c);
                }
                if (c instanceof Container)
                {
                    installSmartWheelForwarding((Container) c);
                }
            }
        });
    }

    private static void addBoundaryForwarding(JScrollPane sp)
    {
        sp.setWheelScrollingEnabled(false);
        sp.addMouseWheelListener(e -> {
            JScrollBar vbar = sp.getVerticalScrollBar();
            if (vbar == null || !vbar.isVisible())
            {
                sp.getParent().dispatchEvent(SwingUtilities.convertMouseEvent(sp, e, sp.getParent()));
                return;
            }
            int val = vbar.getValue();
            int max = vbar.getMaximum() - vbar.getVisibleAmount();
            boolean atTop = val <= vbar.getMinimum();
            boolean atBottom = val >= max;
            boolean scrollingDown = e.getWheelRotation() > 0;
            boolean scrollingUp = e.getWheelRotation() < 0;

            if ((scrollingUp && atTop) || (scrollingDown && atBottom))
            {
                sp.getParent().dispatchEvent(SwingUtilities.convertMouseEvent(sp, e, sp.getParent()));
            }
            else
            {
                int delta = e.getUnitsToScroll() * vbar.getUnitIncrement();
                vbar.setValue(val + delta);
            }
        });
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.util.RankUtils;
import javax.swing.*;
import javax.swing.plaf.basic.BasicProgressBarUI;
import java.awt.*;

public class RankProgressPanel extends JPanel
{
    private static final int SIDEBAR_SCROLLBAR_RESERVE_PX = 16;
    private static final int PROGRESS_BAR_WIDTH = 200;
    private static final int PROGRESS_BAR_HEIGHT = 16;

    private final JProgressBar[] progressBars;
    private final JLabel[] bucketNameLabels;
    private final JLabel[] rankLabels;
    private final String[] buckets = {"Overall Rating", "NH Rating", "Veng Rating", "Multi Rating", "DMM Rating"};

    public RankProgressPanel()
    {
        progressBars = new JProgressBar[5];
        bucketNameLabels = new JLabel[5];
        rankLabels = new JLabel[5];

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        initUI();
    }

    private void initUI()
    {
        for (int i = 0; i < buckets.length; i++)
        {
            JPanel bucketPanel = new JPanel();
            bucketPanel.setLayout(new BoxLayout(bucketPanel, BoxLayout.Y_AXIS));
            bucketPanel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, SIDEBAR_SCROLLBAR_RESERVE_PX));
            bucketPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 70));
            bucketPanel.setAlignmentX(LEFT_ALIGNMENT);

            bucketNameLabels[i] = new JLabel(buckets[i]);
            bucketNameLabels[i].setFont(bucketNameLabels[i].getFont().deriveFont(Font.BOLD));
            bucketNameLabels[i].setAlignmentX(LEFT_ALIGNMENT);
            bucketPanel.add(bucketNameLabels[i]);

            rankLabels[i] = new JLabel(" ");
            rankLabels[i].setFont(rankLabels[i].getFont().deriveFont(Font.BOLD));
            rankLabels[i].setAlignmentX(LEFT_ALIGNMENT);
            bucketPanel.add(rankLabels[i]);

            progressBars[i] = new JProgressBar(0, 100);
            progressBars[i].setValue(0);
            progressBars[i].setStringPainted(true);
            progressBars[i].setString("0%");
            progressBars[i].setPreferredSize(new Dimension(PROGRESS_BAR_WIDTH, PROGRESS_BAR_HEIGHT));
            progressBars[i].setMinimumSize(new Dimension(PROGRESS_BAR_WIDTH, PROGRESS_BAR_HEIGHT));
            progressBars[i].setMaximumSize(new Dimension(PROGRESS_BAR_WIDTH, PROGRESS_BAR_HEIGHT));
            progressBars[i].setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
            progressBars[i].setAlignmentX(LEFT_ALIGNMENT);
            progressBars[i].setUI(new BasicProgressBarUI()
            {
                @Override
                protected Color getSelectionForeground() { return Color.WHITE; }
                @Override
                protected Color getSelectionBackground() { return Color.WHITE; }
            });
            bucketPanel.add(progressBars[i]);

            add(bucketPanel);
            if (i < buckets.length - 1) add(Box.createVerticalStrut(14));
        }
    }

    public void updateBucket(String bucket, String rankLabel, int division, double pct, int rankNumber)
    {
        updateBucket(bucket, rankLabel, division, pct, rankNumber, null);
    }

    /**
     * @param topPercent the player's "Top X.XX%" for this bucket (from the
     *                   rank histogram), or {@code null} to omit the suffix.
     *                   Renders {@code "Adamant 3 #731 Top X.XX%"}.
     */
    public void updateBucket(String bucket, String rankLabel, int division, double pct, int rankNumber, String topPercent)
    {
        int idx = getBucketIndex(bucket);
        if (idx >= 0 && idx < progressBars.length)
        {
            SwingUtilities.invokeLater(() -> {
                Color rankColor = RankUtils.getRankColor(rankLabel);

                if (rankLabels[idx] != null)
                {
                    String displayRank = rankLabel + (division > 0 ? " " + division : "");
                    if (rankNumber > 0)
                    {
                        displayRank += " #" + rankNumber;
                    }
                    if (topPercent != null && !topPercent.isEmpty())
                    {
                        displayRank += " " + topPercent;
                    }
                    rankLabels[idx].setText(displayRank);
                    rankLabels[idx].setForeground(rankColor);
                }
                if (progressBars[idx] != null)
                {
                    progressBars[idx].setValue((int) pct);
                    progressBars[idx].setString(Math.round(pct) + "%");
                    progressBars[idx].setForeground(rankColor);
                }
            });
        }
    }

    public void reset()
    {
        SwingUtilities.invokeLater(() -> {
            for (int i = 0; i < buckets.length; i++)
            {
                if (rankLabels[i] != null)
                {
                    rankLabels[i].setText(" ");
                    rankLabels[i].setForeground(UIManager.getColor("Label.foreground"));
                }
                if (progressBars[i] != null)
                {
                    progressBars[i].setValue(0);
                    progressBars[i].setString("0%");
                    progressBars[i].setForeground(UIManager.getColor("ProgressBar.foreground"));
                }
            }
        });
    }

    private int getBucketIndex(String bucket)
    {
        if (bucket == null) return -1;
        String b = bucket.toLowerCase();
        if ("overall".equals(b)) return 0;
        if ("nh".equals(b)) return 1;
        if ("veng".equals(b)) return 2;
        if ("multi".equals(b)) return 3;
        if ("dmm".equals(b)) return 4;
        return -1;
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.util.RankUtils;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;

/**
 * "Top players" view — a scrollable Top 100 leaderboard mirroring the website,
 * one row per account: <code>#rank &nbsp; Player Name &nbsp; Rank (% to next)</code>.
 *
 * <p>Reads the exact same cached S3 artifact the website uses
 * ({@code /leaderboard[_<bucket>].json}) via
 * {@link PvPDataService#getLeaderboard(String)} — a single CDN call cached
 * ~1 hour. A bucket toggle ([Overall][NH][Veng][Multi][DMM], NH by default)
 * matches the website's leaderboard tabs and the sibling "What are the ranks"
 * view. Unlike the website, only the account's first/primary name is shown.
 */
public class TopPlayersPanel extends JPanel implements Scrollable
{
    private static final String[] BUCKET_LABELS = {"Overall", "NH", "Veng", "Multi", "DMM"};
    private static final String DEFAULT_BUCKET = "nh";
    private static final int TOP_N = 100;

    private static final Color SELECTED_BG = new Color(60, 60, 60);
    private static final Color RANKNUM_COLOR = new Color(0xCF, 0xA8, 0x4A); // muted gold
    private static final Color PCT_COLOR = new Color(0x9A, 0x88, 0x66);     // muted gold for "(xx.x%)"

    /** One leaderboard row, derived purely from the cached JSON. */
    static final class Row
    {
        final int worldRank;
        final String name;
        final String rankFamily; // e.g. "Rune" / "3rd Age" — drives the colour
        final String tierLabel;  // e.g. "Rune 1" / "3rd Age"
        final double progressPct;

        Row(int worldRank, String name, String rankFamily, String tierLabel, double progressPct)
        {
            this.worldRank = worldRank;
            this.name = name;
            this.rankFamily = rankFamily;
            this.tierLabel = tierLabel;
            this.progressPct = progressPct;
        }
    }

    private final PvPDataService pvpDataService;

    private JPanel bucketBar;
    private final JPanel listPanel = new JPanel();
    private final JLabel statusLabel = new JLabel();

    private volatile String selectedBucket = DEFAULT_BUCKET;

    public TopPlayersPanel()
    {
        this(null);
    }

    public TopPlayersPanel(PvPDataService pvpDataService)
    {
        this.pvpDataService = pvpDataService;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

        add(buildBucketBar());

        statusLabel.setName("topPlayersStatus");
        statusLabel.setForeground(Color.GRAY);
        statusLabel.setAlignmentX(LEFT_ALIGNMENT);
        statusLabel.setBorder(BorderFactory.createEmptyBorder(2, 6, 4, 6));
        add(statusLabel);

        listPanel.setName("topPlayersList");
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setAlignmentX(LEFT_ALIGNMENT);
        add(listPanel);

        styleBucketButtons(selectedBucket);
    }

    /** Lazy load entry-point — called when the view is revealed. */
    public void onShown()
    {
        loadBucket(selectedBucket);
    }

    private JPanel buildBucketBar()
    {
        bucketBar = new JPanel(new GridLayout(2, 3, 2, 2));
        bucketBar.setName("topPlayersBucketBar");
        bucketBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
        bucketBar.setAlignmentX(LEFT_ALIGNMENT);

        Font baseFont = UIManager.getFont("Label.font");
        if (baseFont == null) baseFont = new Font("SansSerif", Font.PLAIN, 12);
        Font small = baseFont.deriveFont(Font.PLAIN, Math.max(10f, baseFont.getSize2D() - 1f));

        for (String label : BUCKET_LABELS)
        {
            JButton btn = new JButton(label);
            btn.setName("topPlayersBucketBtn");
            btn.setFont(small);
            btn.setMargin(new Insets(2, 2, 2, 2));
            btn.setFocusPainted(false);
            final String bucketKey = label.toLowerCase();
            btn.addActionListener(e -> loadBucket(bucketKey));
            bucketBar.add(btn);
        }
        return bucketBar;
    }

    private void loadBucket(String bucket)
    {
        final String bucketKey = (bucket == null || bucket.trim().isEmpty())
            ? DEFAULT_BUCKET
            : bucket.trim().toLowerCase();
        selectedBucket = bucketKey;
        styleBucketButtons(bucketKey);

        if (pvpDataService == null)
        {
            showStatus("Unavailable");
            return;
        }

        // Single source of truth for caching: PvPDataService.getLeaderboard
        // is backed by the shared 60-minute shard cache (same hourly refresh
        // the website's CDN object uses). We deliberately keep NO long-lived
        // copy here — a per-panel cache would shadow that TTL and serve stale
        // rows for the whole session. Each tab visit / bucket toggle re-asks;
        // within the hour it's a cache hit (no network), after the hour it
        // refetches.
        CompletableFuture<JsonObject> future = pvpDataService.getLeaderboard(bucketKey);
        if (future == null)
        {
            showStatus("Unavailable");
            return;
        }

        // Already cached (future completed) → render immediately, no flash.
        JsonObject ready = future.getNow(null);
        if (ready != null)
        {
            renderLeaderboard(bucketKey, ready);
            return;
        }

        showStatus("Loading\u2026");
        future.thenAccept(data -> SwingUtilities.invokeLater(() ->
        {
            if (bucketKey.equals(selectedBucket)) renderLeaderboard(bucketKey, data);
        })).exceptionally(ex ->
        {
            SwingUtilities.invokeLater(() ->
            {
                if (bucketKey.equals(selectedBucket)) showStatus("Unavailable");
            });
            return null;
        });
    }

    private void renderLeaderboard(String bucketKey, JsonObject data)
    {
        if (!bucketKey.equals(selectedBucket)) return;
        if (data != null && data.has("players"))
        {
            renderRows(parseTopPlayers(data, TOP_N));
        }
        else
        {
            showStatus("Unavailable");
        }
    }

    private void showStatus(String text)
    {
        listPanel.removeAll();
        statusLabel.setText(text);
        statusLabel.setVisible(true);
        listPanel.revalidate();
        listPanel.repaint();
        revalidateUpChain();
    }

    private void renderRows(List<Row> rows)
    {
        listPanel.removeAll();
        if (rows.isEmpty())
        {
            showStatus("No ranked players yet for this bucket.");
            return;
        }
        statusLabel.setText("Showing top " + rows.size());
        statusLabel.setVisible(true);
        for (Row r : rows)
        {
            listPanel.add(buildRow(r));
        }
        listPanel.revalidate();
        listPanel.repaint();
        revalidateUpChain();
    }

    /**
     * Rows load asynchronously after the view is first shown, but our enclosing
     * {@link JScrollPane} is a Swing "validate root" — so revalidating
     * {@code listPanel} alone re-lays-out the viewport WITHOUT resizing the
     * scroll pane itself within the lookup card (it stays stuck at whatever
     * height it had while empty/"Loading…", showing only a handful of rows).
     * Revalidating the scroll pane's parent forces the surrounding layout to
     * grow the view to the full row count immediately instead of waiting for an
     * unrelated outer resize/scroll event.
     */
    private void revalidateUpChain()
    {
        Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, this);
        Container target = (scrollPane != null) ? scrollPane.getParent() : getParent();
        if (target != null)
        {
            target.revalidate();
            target.repaint();
        }
    }

    private JPanel buildRow(Row r)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setName("topPlayerRow");
        row.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        row.setAlignmentX(LEFT_ALIGNMENT);

        JLabel rankNum = new JLabel("#" + r.worldRank);
        rankNum.setName("topPlayerRankNum");
        rankNum.setFont(rankNum.getFont().deriveFont(Font.BOLD, 12f));
        rankNum.setForeground(RANKNUM_COLOR);
        rankNum.setPreferredSize(new Dimension(36, 20));
        row.add(rankNum, BorderLayout.WEST);

        JLabel name = new JLabel(r.name);
        name.setName("topPlayerName");
        name.setFont(name.getFont().deriveFont(Font.PLAIN, 13f));
        name.setForeground(Color.WHITE);
        row.add(name, BorderLayout.CENTER);

        JLabel tier = new JLabel(tierHtml(r));
        tier.setName("topPlayerTier");
        tier.setFont(tier.getFont().deriveFont(Font.PLAIN, 12f));
        tier.setHorizontalAlignment(SwingConstants.RIGHT);
        row.add(tier, BorderLayout.EAST);

        return row;
    }

    private static String tierHtml(Row r)
    {
        Color c = "3rd Age".equals(r.rankFamily) ? Color.WHITE : RankUtils.getRankColor(r.rankFamily);
        String tierHex = String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
        String pctHex = String.format("#%02x%02x%02x", PCT_COLOR.getRed(), PCT_COLOR.getGreen(), PCT_COLOR.getBlue());
        return "<html><span style='color:" + tierHex + ";'><b>" + escape(r.tierLabel) + "</b></span>"
            + " <span style='color:" + pctHex + ";'>(" + String.format(Locale.US, "%.1f", r.progressPct) + "%)</span></html>";
    }

    private static String escape(String s)
    {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    /** Per-account aggregate built while de-duplicating the raw player rows. */
    private static final class Agg
    {
        final LinkedHashSet<String> names = new LinkedHashSet<>();
        double mmr = Double.NEGATIVE_INFINITY;
        String rank = null;
        int division = 0;
    }

    /**
     * Convert a cached leaderboard payload into the top {@code limit} display
     * rows, mirroring the website's {@code fetchLeaderboard} exactly:
     * <ol>
     *   <li>keep only rows with an account id + finite MMR;</li>
     *   <li>de-duplicate by account ({@code account_hash || account}) — the S3
     *       file can carry more than one row per account — unioning names in
     *       first-seen order and keeping the highest-MMR entry's rank/division;</li>
     *   <li>sort by MMR descending, assign world rank by position;</li>
     *   <li>take the top {@code limit}.</li>
     * </ol>
     * The plugin shows only the account's first/primary name (the website
     * joins them all). In-tier "% to next rank" matches the website's
     * {@code computeProgressToNextRank} via
     * {@link RankUtils#calculateProgressFromMMR(double)}.
     *
     * <p>Pure + null-safe so it's unit-testable without Swing/network.
     */
    static List<Row> parseTopPlayers(JsonObject data, int limit)
    {
        List<Row> rows = new ArrayList<>();
        if (data == null || !data.has("players") || !data.get("players").isJsonArray())
        {
            return rows;
        }
        JsonArray players = data.getAsJsonArray("players");

        Map<String, Agg> byAccount = new LinkedHashMap<>();
        for (JsonElement el : players)
        {
            if (el == null || !el.isJsonObject()) continue;
            JsonObject p = el.getAsJsonObject();
            double mmr = mmrOf(p);
            if (!Double.isFinite(mmr)) continue;
            String account = accountOf(p);
            if (account == null) continue;

            Agg agg = byAccount.computeIfAbsent(account, k -> new Agg());
            addNames(agg.names, p);
            if (mmr > agg.mmr)
            {
                agg.mmr = mmr;
                agg.rank = strOrNull(p, "rank");
                agg.division = intOr(p, "division", 0);
            }
        }

        List<Agg> ranked = new ArrayList<>(byAccount.values());
        ranked.sort((a, b) -> Double.compare(b.mmr, a.mmr));

        int n = Math.min(Math.max(0, limit), ranked.size());
        for (int i = 0; i < n; i++)
        {
            Agg a = ranked.get(i);
            String rankFamily = a.rank;
            int division = a.division;
            if (rankFamily == null)
            {
                com.pvp.leaderboard.service.RankInfo ri = RankUtils.rankLabelAndProgressFromMMR(a.mmr);
                rankFamily = ri.rank;
                division = ri.division;
            }
            String tierLabel = "3rd Age".equals(rankFamily) ? "3rd Age" : rankFamily + " " + division;
            double pct = RankUtils.calculateProgressFromMMR(a.mmr);
            String name = a.names.isEmpty() ? "Unknown" : a.names.iterator().next();

            rows.add(new Row(i + 1, name, rankFamily, tierLabel, pct));
        }
        return rows;
    }

    private static double mmrOf(JsonObject p)
    {
        try
        {
            if (p.has("mmr") && !p.get("mmr").isJsonNull()) return p.get("mmr").getAsDouble();
            if (p.has("MMR") && !p.get("MMR").isJsonNull()) return p.get("MMR").getAsDouble();
        }
        catch (RuntimeException ignore) { }
        return Double.NaN;
    }

    /** Account id, mirroring the website's {@code account_hash || account}. */
    private static String accountOf(JsonObject p)
    {
        String a = strOrNull(p, "account_hash");
        return (a != null) ? a : strOrNull(p, "account");
    }

    private static void addNames(Set<String> out, JsonObject p)
    {
        try
        {
            if (p.has("player_names") && p.get("player_names").isJsonArray())
            {
                for (JsonElement n : p.getAsJsonArray("player_names"))
                {
                    if (n != null && !n.isJsonNull())
                    {
                        String s = n.getAsString();
                        if (s != null && !s.trim().isEmpty()) out.add(s);
                    }
                }
            }
        }
        catch (RuntimeException ignore) { }
    }

    private static String strOrNull(JsonObject p, String key)
    {
        try
        {
            if (p.has(key) && !p.get(key).isJsonNull())
            {
                String s = p.get(key).getAsString();
                return (s == null || s.trim().isEmpty()) ? null : s;
            }
        }
        catch (RuntimeException ignore) { }
        return null;
    }

    private static int intOr(JsonObject p, String key, int fallback)
    {
        try
        {
            if (p.has(key) && !p.get(key).isJsonNull()) return p.get(key).getAsInt();
        }
        catch (RuntimeException ignore) { }
        return fallback;
    }

    private void styleBucketButtons(String activeBucket)
    {
        if (bucketBar == null) return;
        for (Component c : bucketBar.getComponents())
        {
            if (!(c instanceof JButton)) continue;
            JButton btn = (JButton) c;
            boolean selected = btn.getText().equalsIgnoreCase(activeBucket);
            if (selected)
            {
                btn.setForeground(Color.WHITE);
                btn.setBackground(SELECTED_BG);
            }
            else
            {
                btn.setForeground(Color.GRAY);
                btn.setBackground(UIManager.getColor("Button.background"));
            }
        }
    }

    // --- Scrollable: track viewport width (rows never overflow sideways);
    // vertical scrolling handled by the enclosing JScrollPane. ---

    @Override
    public Dimension getPreferredScrollableViewportSize()
    {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
    {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
    {
        return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
    }

    @Override
    public boolean getScrollableTracksViewportWidth()
    {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight()
    {
        return false;
    }
}

