    /** Wrap a fight-setup card in a scrollpane — RuneLite sidepanels can be
     *  short enough that the buttons + summary overflow vertically. */
    private static JComponent wrapInScroll(JPanel card)
    {
        JScrollPane sp = new JScrollPane(card,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        sp.setBorder(BorderFactory.createEmptyBorder());
        sp.getVerticalScrollBar().setUnitIncrement(16);
        return sp;
    }

    /** Compact strip showing the user's currently-selected build + style with
     *  a "Reset Options" affordance that clears all gate picks and returns
     *  to the gate. Lives between the presence bar and the rank filters.
     *  Fonts match {@link #LOBBY_HEADER_PT} so the strip reads at the same
     *  scale as the Lobby title row above.
     *
     *  Stacked vertically so the Build line + (possibly-multi-style) Style
     *  line can wrap across multiple lines instead of getting "..." truncated
     *  when the user has enabled NH+Veng+Multi+DMM in a 225px sidepanel. */
    private JPanel buildCurrentStyleBar()
    {
        JPanel bar = new JPanel();
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        // 108px = ~4 lines of 15pt + button row at its natural height.
        // Build line + style line (which can wrap to 2 lines with all 4
        // styles) + the Reset Options button row. Bumped from 96 to 108
        // so the button row gets its preferred height (~32px at 15pt bold
        // + Substance border insets) instead of being squeezed to 28px,
        // which Substance's ButtonUI was responding to by ellipsifying
        // the label horizontally as well — visible to users as
        // "Reset Opti\u2026" truncation. Real height auto-shrinks when
        // the style line collapses to a single row.
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 108));
        bar.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));

        // "Build: X / Style: Y, Z" rendered as one HTML-wrapped JLabel so the
        // CSV values can wrap when they overflow the sidepanel.
        currentStyleLabel = new JLabel();
        currentStyleLabel.setFont(currentStyleLabel.getFont().deriveFont(Font.BOLD, LOBBY_HEADER_PT));
        currentStyleLabel.setAlignmentX(LEFT_ALIGNMENT);
        bar.add(currentStyleLabel);

        // Reset Options button on its own row, right-aligned so it doesn't
        // compete with the wrapped label for horizontal space. Horizontal-glue
        // pushes the button to the right within a row that stretches across
        // the bar's full width (FlowLayout RIGHT wouldn't work here because
        // BoxLayout sizes the row to its content's preferred width).
        JPanel buttonRow = new JPanel();
        buttonRow.setLayout(new BoxLayout(buttonRow, BoxLayout.X_AXIS));
        buttonRow.setOpaque(false);
        buttonRow.setAlignmentX(LEFT_ALIGNMENT);
        buttonRow.add(Box.createHorizontalGlue());
        JButton reset = new JButton("Leave Lobby");
        reset.setMargin(new Insets(2, 8, 2, 8));
        reset.setFont(reset.getFont().deriveFont(Font.BOLD, LOBBY_HEADER_PT));
        reset.setFocusPainted(false);
        reset.addActionListener(e ->
        {
            // Hard reset: clear styles, clear account type, reset region to
            // default, desync all gate toggle visuals, then return to the
            // gate. Go-to-lobby will be disabled until the user re-picks.
            resetGateOptions();
            rootCards.show(rootCardHost, CARD_GATE);
        });
        // Lock the button to its natural preferred size so neither the
        // outer BoxLayout (which would otherwise shrink it to fit a
        // squeezed cross-axis) nor Substance's ButtonUI (which falls
        // back to ellipsis when allocated less than preferred width)
        // can clip "Reset Options" to "Reset Opti\u2026". Computed
        // AFTER setFont/setMargin so the metrics reflect the bold
        // 15pt run we actually paint with.
        Dimension resetPref = reset.getPreferredSize();
        reset.setMinimumSize(resetPref);
        reset.setMaximumSize(resetPref);
        // Match the row's max height to the button so BoxLayout doesn't
        // squeeze the button vertically — Substance's ButtonUI clips
        // the label horizontally when it's given less than its
        // preferred height (the height squeeze cascades into the text
        // layout's available horizontal run, which is what produces
        // the "Reset Opti\u2026" symptom in narrow sidepanels).
        buttonRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, resetPref.height));
        buttonRow.add(reset);
        bar.add(buttonRow);

        return bar;
    }

    /** {@link Box#createVerticalStrut(int)} returns a {@link Box.Filler} whose
     *  X alignment defaults to {@code CENTER}. Mixed with LEFT-aligned siblings
     *  this breaks BoxLayout's off-axis math. Wrap the strut so we control it. */
    private static Component leftAlignedStrut(int height)
    {
        Box.Filler strut = (Box.Filler) Box.createVerticalStrut(height);
        strut.setAlignmentX(LEFT_ALIGNMENT);
        return strut;
    }

    private JPanel buildPresenceBar()
    {
        // "Lobby" + presence count both use the same font as player names
        // (Font.BOLD, ROW_FONT_PT) so the lobby strip reads as a single
        // typographic unit with the roster below it. Stacked vertically
        // because "Showing X out of Y players online" at 15pt bold is too
        // wide to share a row with the "Lobby" header in a 225px sidepanel.
        JPanel bar = new JPanel();
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        // 80px gives the presence label room to wrap to 2 lines without
        // BoxLayout cropping it. HTML-wrap target width below is 200px;
        // anything narrower than ~190px effective triggers wrap.
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 80));
        bar.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));

        JLabel title = new JLabel("Lobby");
        title.setFont(title.getFont().deriveFont(Font.BOLD, (float) ROW_FONT_PT));
        title.setAlignmentX(LEFT_ALIGNMENT);
        bar.add(title);

        // HTML wrap because the full presence string at 15pt bold overruns the
        // sidepanel's native width and JLabel otherwise truncates with "...".
        presenceLabel = new JLabel();
        presenceLabel.setFont(presenceLabel.getFont().deriveFont(Font.BOLD, (float) ROW_FONT_PT));
        presenceLabel.setForeground(new Color(0x6cd16a));
        presenceLabel.setAlignmentX(LEFT_ALIGNMENT);
        bar.add(presenceLabel);
        return bar;
    }

    private JPanel buildFilterRow()
    {
        JPanel filters = new JPanel();
        filters.setLayout(new BoxLayout(filters, BoxLayout.Y_AXIS));
        filters.setBorder(BorderFactory.createCompoundBorder(
            new MatteBorder(1, 0, 1, 0, new Color(60, 60, 60)),
            BorderFactory.createEmptyBorder(6, 2, 6, 2)));
        // Caption now uses ROW_FONT_PT (15pt bold) to match player names per
        // request, which forces a 2-line wrap at 200px → ~44px tall.
        // Value row (~20) + slider (~28) + container padding (12) → ~104.
        filters.setMaximumSize(new Dimension(Integer.MAX_VALUE, 110));

        // Caption above the slider — explains the range semantics so the user
        // doesn't have to infer "what does this slider do?" from the rank
        // colours alone. Word-wraps when the sidepanel is narrow.
        JLabel caption = new JLabel(
            "<html><div style='width: 200px;'>Receive or give invites within the ratings you choose</div></html>");
        caption.setFont(caption.getFont().deriveFont(Font.BOLD, (float) ROW_FONT_PT));
        caption.setForeground(new Color(0xaa, 0xaa, 0xaa));
        caption.setAlignmentX(LEFT_ALIGNMENT);
        caption.setBorder(BorderFactory.createEmptyBorder(0, 2, 4, 2));

        JLabel minValue = makeRankValueLabel(rankMinIdx);
        JLabel maxValue = makeRankValueLabel(rankMaxIdx);
        // Each value sits flush against its slider end (left / right). No
        // "Rank range:" prefix any more — the caption above explains the
        // widget and the rank-coloured labels speak for themselves.
        minValue.setHorizontalAlignment(SwingConstants.LEFT);
        maxValue.setHorizontalAlignment(SwingConstants.RIGHT);

        // Single-track double-handled range slider (replaces the earlier
        // pair of stacked JSliders). One row instead of two saves ~50px of
        // vertical real estate so the chat panel stays visible without
        // scrolling on the default sidepanel height.
        RangeSlider rankRange = new RangeSlider(0, RANK_LABELS.length - 1, rankMinIdx, rankMaxIdx);
        rankRange.setToolTipText("Drag the handles to set min / max opponent rank");
        rankRange.addChangeListener(e ->
        {
            rankMinIdx = rankRange.getLow();
            rankMaxIdx = rankRange.getHigh();
            updateRankValueLabel(minValue, rankMinIdx);
            updateRankValueLabel(maxValue, rankMaxIdx);
            if (!rankRange.getValueIsAdjusting())
            {
                // Persist on commit (drag-end) rather than every drag
                // tick — avoids hammering the config writer with N writes
                // per drag while still ensuring the final value lands.
                prefs.setMinRankIdx(rankMinIdx);
                prefs.setMaxRankIdx(rankMaxIdx);
                // Push the new range to the server so peers' rosters
                // re-evaluate the "viewer is outside my accept-invite
                // range" greyout for the local user. The service
                // throttles the wire frame (≤ 1 per
                // {@link LobbyService#RANGE_UPDATE_MIN_INTERVAL_MS});
                // we just fire-and-forget and let it coalesce.
                if (service != null) service.updateRankRange(rankMinIdx, rankMaxIdx);
                renderRoster();
                // Slider also gates incoming invite cards — re-evaluate per-card
                // visibility so out-of-range invites disappear (and reappear if
                // the user widens the range later).
                refreshInvitesContainer();
            }
        });

        // Header row: min rank LEFT, max rank RIGHT. No center label.
        JPanel header = new JPanel(new BorderLayout());
        header.setOpaque(false);
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        header.setAlignmentX(LEFT_ALIGNMENT);
        header.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));
        header.add(minValue, BorderLayout.WEST);
        header.add(maxValue, BorderLayout.EAST);

        filters.add(caption);
        filters.add(header);
        rankRange.setAlignmentX(LEFT_ALIGNMENT);
        filters.add(rankRange);

        return filters;
    }

    /** Live "current value" label for a rank-range endpoint — bold,
     *  painted in the rank's own colour so the user can spot which
     *  tier they're on without reading the text. 15pt matches the
     *  lobby's body-text scale (style toggles + presence label).
     *
     *  <p>Backed by {@link ChipLabel} (not vanilla JLabel) because
     *  Substance L&F's LabelUI was reporting an undersized preferred
     *  width for the slider's min / max value labels — visible to
     *  users as "Bronz\u2026" / "3rd A\u2026" ellipsis truncation
     *  even though there's plenty of horizontal slack inside the
     *  225px sidepanel. ChipLabel paints the text directly in
     *  paintComponent so the L&F's clip-and-ellipsify path is
     *  bypassed entirely; the alignment-aware draw inside
     *  ChipLabel honours the LEFT / RIGHT setHorizontalAlignment
     *  set on the min / max labels respectively. */
    private static JLabel makeRankValueLabel(int idx)
    {
        ChipLabel l = new ChipLabel(RANK_LABELS[idx]);
        l.setFont(l.getFont().deriveFont(Font.BOLD, 15f));
        l.setHorizontalAlignment(SwingConstants.RIGHT);
        l.setForeground(RankUtils.getRankColor(RANK_LABELS[idx]));
        l.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        return l;
    }

    private static void updateRankValueLabel(JLabel l, int idx)
    {
        String label = RANK_LABELS[idx];
        l.setText(label);
        l.setForeground(RankUtils.getRankColor(label));
    }

    private JScrollPane buildRosterScroll()
    {
        rosterContainer = new ScrollableRosterPanel();
        rosterContainer.setLayout(new BoxLayout(rosterContainer, BoxLayout.Y_AXIS));
        rosterContainer.setName(ROSTER_NAME);
        rosterContainer.setOpaque(false);

        renderRoster();

        rosterScroll = new JScrollPane(rosterContainer,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        rosterScroll.getViewport().setOpaque(false);
        rosterScroll.setOpaque(false);
        rosterScroll.setBorder(BorderFactory.createEmptyBorder());
        rosterScroll.getVerticalScrollBar().setUnitIncrement(16);
        rosterScroll.setAlignmentX(LEFT_ALIGNMENT);
        // Take all remaining vertical space — the parent uses BoxLayout Y_AXIS.
        rosterScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        return rosterScroll;
    }

    /** Snaps the roster scroll back to the top. Called when entering the
     *  fight-setup flow so the user lands at the top of the roster on
     *  return (Go-back-to-Lobby / both-confirmed / window-expired) rather
     *  than at whatever position they had clicked Fight from.
     *
     *  Implementation note: a direct {@code setValue(0)} on the scrollbar
     *  is unreliable when called mid-EDT before the viewport has been
     *  re-laid out (the bar's model clamps the new value against an
     *  out-of-date {@code max}). Schedule via invokeLater so the snap
     *  runs after the current event handler's layout pass completes, and
     *  drive the viewport directly so we don't depend on the scrollbar
     *  model being in sync. */
    private void scrollRosterToTop()
    {
        if (rosterScroll == null) return;
        // rosterScroll is single-assignment in buildLobbyView() and never
        // re-nulled, so no second guard is needed inside the lambda.
        SwingUtilities.invokeLater(() ->
        {
            JViewport vp = rosterScroll.getViewport();
            if (vp != null) vp.setViewPosition(new Point(0, 0));
        });
    }

    /**
     * JPanel that tells its enclosing JViewport "always size me to the viewport
     * width". Without this, the JScrollPane sizes the view to its <i>preferred</i>
     * width (the widest child's preferred width) which is much narrower than the
     * 215px sidepanel — and child rows then sit centered in the empty space.
     * That was the visible bug in the first beta builds.
     */
    private static class ScrollableRosterPanel extends JPanel implements Scrollable
    {
        @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }

        @Override public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) { return 16; }

        @Override public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return Math.max(visibleRect.height - 16, 16);
        }

        /** KEY: forces the view to be exactly viewport-wide so child rows fill horizontally. */
        @Override public boolean getScrollableTracksViewportWidth() { return true; }

        @Override public boolean getScrollableTracksViewportHeight() { return false; }
    }

    private void renderRoster()
    {
        rosterContainer.removeAll();

        List<LobbyMember> visible = new ArrayList<>();
        for (LobbyMember p : roster)
        {
            // No region filter — lobby shows everyone regardless of region.
            // Style/build overlap only greys the [Fight] chip (see
            // fightAllowed); rank outside the slider hides the row
            // entirely (server also filters, this is defense-in-depth).
            if (!rankInRange(p)) continue;
            // Hide locally-stale rows (last invite to this player_id
            // bounced with PEER_NOT_IN_LOBBY — see onError). The set
            // is cleared on the next authoritative server snapshot.
            if (p.playerId != null && recentlyStalePlayerIds.contains(p.playerId)) continue;
            visible.add(p);
        }
        Collections.sort(visible, (a, b) -> Integer.compare(b.peakRankIdx, a.peakRankIdx));

        // Snapshot the viewer's current rank once per render pass so
        // every row in this pass compares against the same value (no
        // race between rows if the gate refresh fires mid-render).
        final int viewerRankIdx = viewerCurrentRankIdx();
        for (LobbyMember p : visible)
        {
            // Chip precedence: [Blocked Lookup] > [Invited M:SS] > [Lookup] >
            //                  [out-of-their-range Fight] > [Fight].
            //   [Blocked Lookup]            — local user has blocked this player_id, card greyed
            //   [Invited M:SS]              — pending outgoing invite, click cancels
            //   [Lookup]                    — outstanding incoming invite from this player
            //   [out-of-their-range Fight]  — viewer's rank is outside their accept-invite
            //                                 slider, row greyed, chip is a no-op
            //   [Fight]                     — default; opens full-screen fight-setup card
            rosterContainer.add(new PlayerRow(p, ROW_FONT_PT,
                this::isPlayerInvited,
                this::getOutgoingInvite,
                this::routeOpenProfile,
                this::onFightClicked,
                opp -> cancelOutgoingInvite(opp.playerId, true),
                m -> m != null && m.playerId != null && blockedPlayerIds.contains(m.playerId),
                this::fightAllowed,
                m -> viewerOutsideMemberRange(viewerRankIdx, m),
                false));
            rosterContainer.add(Box.createVerticalStrut(2));
        }

        // Always seed at least one row of placeholder space so the scroll pane
        // computes a non-zero preferred size when filters drop everything.
        // Two distinct copies so the user can tell whether the empty
        // state is "the lobby is genuinely empty" vs "you filtered
        // everyone out" without inspecting their own slider:
        //   - roster.isEmpty()                → nobody else online
        //   - roster non-empty but visible==0 → filter rejects all
        // The Reset-Options nudge is only useful in the second case
        // (resetting changes nothing when the roster itself is empty).
        if (visible.isEmpty())
        {
            String message = roster.isEmpty()
                ? "No one else is currently in the lobby, please wait while others join or invite some friends to the plugin"
                : "No players match your filters, click Leave Lobby and re-join with wider filters";
            // HTML wrap forces line breaks inside the ~200px lobby
            // column — JLabel won't wrap plain text inside a
            // BoxLayout.Y_AXIS parent. 15pt BOLD matches the lobby's
            // body-text scale used by the style toggles + presence label.
            JLabel empty = new JLabel("<html><div style='width:200px'>" + message + "</div></html>");
            empty.setFont(empty.getFont().deriveFont(Font.BOLD, 15f));
            empty.setForeground(new Color(0x888888));
            empty.setAlignmentX(LEFT_ALIGNMENT);
            empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 8, 4));
            rosterContainer.add(empty);
        }

        if (presenceLabel != null)
        {
            // Explicit <br> wrap (no <div style='width:Npx'>) so the
            // label adapts to the actual sidepanel width — RuneLite
            // sidepanels can be resized by the user and a fixed 200px
            // wrap target was causing the JLabel to render at 200px
            // wide regardless and get clipped at the panel edge,
            // visible as "...players onlin" with the trailing "e"
            // shaved off. With a hard <br> the line break happens at
            // a stable point and each half ("Showing X out of Y" /
            // "players online") fits comfortably in even a narrow
            // (~180px) sidepanel at 15pt bold.
            presenceLabel.setText("<html>"
                + "Showing " + visible.size() + " out of " + roster.size() + "<br>"
                + "players online"
                + "</html>");
        }

        rosterContainer.revalidate();
        rosterContainer.repaint();
    }

    /** {@code true} when the local user's advertised styles/builds overlap
     *  the opponent's — drives whether [Fight] is clickable vs greyed.
     *  Rows stay visible either way; only rank-out-of-range hides a card. */
    private boolean fightAllowed(LobbyMember p)
    {
        if (p == null) return false;
        boolean styleOverlap = false;
        for (Style s : p.styles)
        {
            if (selectedStyles.contains(s))
            {
                styleOverlap = true;
                break;
            }
        }
        if (!styleOverlap) return false;
        for (BuildType b : p.builds)
        {
            if (selectedBuildTypes.contains(b)) return true;
        }
        return false;
    }

    private boolean rankInRange(LobbyMember p)
    {
        // Matchmaking gate: keys on **current** rank, NOT peak. Peak is
        // display-only (the big rank label on each card). The server's
        // RANK_OUT_OF_RANGE check on lobby/invite reads
        // current_mmr_per_bucket, so the slider must filter on the same
        // signal or invites will be rejected by the server even though
        // the user could see the row.
        int idx = p.currentRankIdx;
        // Unknown / sentinel rank — show the row rather than hiding
        // everyone when the server omits rank_idx on a roster push.
        if (idx < 0 || idx >= RANK_LABELS.length) return true;
        return idx >= rankMinIdx && idx <= rankMaxIdx;
    }

    /** True iff the {@code viewerRankIdx} sits outside {@code m}'s
     *  own accept-invite slider band — i.e. the member would
     *  server-reject any {@code lobby/invite} from us with
     *  {@code RANK_OUT_OF_RANGE}. Pure helper; lifted out so it can
     *  be unit-tested without standing up the panel.
     *
     *  <p>Defaults to {@code false} ("in range") whenever any input is
     *  missing — null member, sentinel viewer rank, or either
     *  {@link LobbyMember#minRankIdx} / {@link LobbyMember#maxRankIdx}
     *  unknown. Reason: on a pre-deploy backend the new slider fields
     *  ship as {@link LobbyMember#UNKNOWN_RANK_IDX}; if we treated
     *  unknown as "out of range" we'd grey every row on the first
     *  push. Keeping unknown as "show normally" means the greyout
     *  silently activates when the backend lands the field and is a
     *  no-op until then. */
    static boolean viewerOutsideMemberRange(int viewerRankIdx, LobbyMember m)
    {
        if (m == null) return false;
        if (viewerRankIdx < 0) return false;
        if (m.minRankIdx == LobbyMember.UNKNOWN_RANK_IDX) return false;
        if (m.maxRankIdx == LobbyMember.UNKNOWN_RANK_IDX) return false;
        return viewerRankIdx < m.minRankIdx || viewerRankIdx > m.maxRankIdx;
    }

    /** Returns the HTML string rendered into the "Accepts fights from
     *  &lt;min&gt; to &lt;max&gt; rating" replacement label that
     *  takes over the bottom row of an out-of-their-range greyed
     *  {@code PlayerRow}. The two rank labels are wrapped in
     *  {@code <font color="#RRGGBB">} spans whose hex matches
     *  {@link RankUtils#getRankColor(String)} for that label — same
     *  palette the panel's own rank-range slider min / max value
     *  labels use, so the row reads as "your rank vs. their
     *  band" without the user having to map tier names → colours
     *  themselves.
     *
     *  <p>Lifted out as a static (rather than building the markup
     *  inline) so it can be pinned by unit tests without standing up
     *  Swing. {@code rankLabels} is parameterised for the same
     *  reason — tests pass the real {@link #RANK_LABELS} but a
     *  fixture could pass a smaller table.
     *
     *  <p>Returns an empty string when either bound is the
     *  {@link LobbyMember#UNKNOWN_RANK_IDX} sentinel or out of the
     *  rank-label table's bounds — the call site guards against
     *  this (the predicate that triggers the swap requires both
     *  bounds known) but the defensive return keeps the helper safe
     *  to call from future call sites. */
    static String buildAcceptsRangeHtml(int minRankIdx, int maxRankIdx, String[] rankLabels)
    {
        if (rankLabels == null || rankLabels.length == 0) return "";
        if (minRankIdx < 0 || minRankIdx >= rankLabels.length) return "";
        if (maxRankIdx < 0 || maxRankIdx >= rankLabels.length) return "";
        String minLabel = rankLabels[minRankIdx];
        String maxLabel = rankLabels[maxRankIdx];
        String minHex = colorToHex(RankUtils.getRankColor(minLabel));
        String maxHex = colorToHex(RankUtils.getRankColor(maxLabel));
        // Width-capped <div> so the JLabel stays inside the row's centre
        // column (the ~200px row content area MINUS the EAST [Fight]
        // action chip, ~55-60px) instead of running under the button or
        // off the right edge on the narrowest RuneLite sidepanel.
        //
        // HARD <br> after the lead-in copy (NOT just relying on the div's
        // auto-wrap): under the panel L&F an auto-wrapped HTML JLabel is
        // wrapped correctly when *painted* but its *preferred height* is
        // mis-measured as a single line, so the row sized one line short
        // and the wrapped tail ("<max> rating") clipped at the card's
        // bottom edge (user report 2026-06-03). A literal <br> gives the
        // HTML view a real second row in BOTH the paint and
        // preferred-height passes, so the row reserves the right height
        // and nothing clips. It also pins the wrap the user wants:
        //   line 1: "Accepts fights from"
        //   line 2: "<min> to <max> rating"  (range kept together)
        // 150px comfortably fits the longest common pair on line 2.
        return "<html><div style='width:150px'>Accepts fights from<br>"
            + "<font color='" + minHex + "'>" + minLabel + "</font>"
            + " to "
            + "<font color='" + maxHex + "'>" + maxLabel + "</font>"
            + " rating</div></html>";
    }

    /** Bounds-checked lookup into the {@link #RANK_LABELS} table.
     *  Returns {@code "?"} for sentinel / out-of-bounds indices so a
     *  tooltip never embeds an array-index-out-of-bounds exception
     *  message. */
    static String safeRankLabel(int idx, String[] rankLabels)
    {
        if (rankLabels == null) return "?";
        if (idx < 0 || idx >= rankLabels.length) return "?";
        return rankLabels[idx];
    }

    /** {@link Color} → CSS-friendly {@code "#RRGGBB"} hex string.
     *  JLabel HTML rendering accepts both {@code #rgb} and
     *  {@code #rrggbb} forms; we always use the 6-digit form so the
     *  string is unambiguous in tests and matches the convention
     *  used elsewhere in the panel. */
    static String colorToHex(Color c)
    {
        if (c == null) return "#666666";
        return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
    }

    /** Local viewer's own current rank index for the active sort
     *  bucket — i.e. the rank the server would compare to each
     *  member's {@code [min_rank_idx, max_rank_idx]} on a
     *  {@code lobby/invite}. Read off {@link LobbyJoinGate#getRankIdxByStyle()}
     *  for the {@link #pickSortBucket()} bucket's matching {@link Style}.
     *  Returns {@code -1} (unknown) when the gate has no rank data
     *  for the active bucket (pre-login, brand-new player, etc.) —
     *  callers treat that as "skip the greyout, show row normally".
     *
     *  <p>"overall" bucket falls back to the highest known rank across
     *  any style (matches {@link #pickSelfPreviewRankIdx()}'s
     *  fallback) so a user who hasn't picked a style still gets a
     *  meaningful comparison value. */
    private int viewerCurrentRankIdx()
    {
        if (joinGate == null) return -1;
        Map<Style, Integer> ranks = joinGate.getRankIdxByStyle();
        if (ranks == null || ranks.isEmpty()) return -1;
        String bucket = pickSortBucket();
        if (!"overall".equals(bucket))
        {
            try
            {
                Style s = Style.valueOf(bucket.toUpperCase());
                Integer idx = ranks.get(s);
                if (idx != null && idx >= 0) return idx;
            }
            catch (IllegalArgumentException ignored) { /* fall through to overall */ }
        }
        int best = -1;
        for (Style s : Style.values())
        {
            Integer idx = ranks.get(s);
            if (idx != null && idx > best) best = idx;
        }
        return best;
    }

    /** True if {@code idx} is a real rank (server returned a value), not
     *  a -1 sentinel or a label-overflow. Used to distinguish "no current
     *  rank yet" (don't filter out) from "current rank known and out of
     *  band" (filter out). */
    private boolean rankIdxKnown(int idx)
    {
        return idx >= 0 && idx < RANK_LABELS.length;
    }

    /** Picks the canonical bucket key the server should compute
     *  per-row {@code rank_idx} / {@code peak_rank_idx} for. Priority
     *  follows the {@link Style} enum declaration order
     *  (NH &gt; Veng &gt; Multi &gt; DMM) — first selected style wins,
     *  with {@code "overall"} as the fallback when nothing is selected
     *  (gate state, mid-toggle race, etc.). The slider matchmaking gate
     *  reads the rank for this bucket, so the bucket must reflect the
     *  user's primary advertised style or the slider hides players
     *  based on the wrong bucket's MMR. */
    private String pickSortBucket()
    {
        for (Style s : Style.values())
        {
            if (selectedStyles.contains(s))
            {
                return s.name().toLowerCase();
            }
        }
        return "overall";
    }

    // -------------------- Player row ([Fight] or [Lookup], no inline picker) --------------------

    /**
     * Roster entry. EAST chip cycles through three states (precedence top-down):
     * <ul>
     *   <li><b>[Invited M:SS]</b> — outgoing invite pending acceptance.
     *       Click cancels the invite (clears the 10-min block).</li>
     *   <li><b>[Lookup]</b> — outstanding incoming invite from this player
     *       (their card is up top). Click opens Player Lookup.</li>
     *   <li><b>[Fight]</b> (default) — opens the full-screen fight-setup card.</li>
     * </ul>
     *
     * <p>Clicking the profile area also opens Player Lookup — matches the
     * legacy right-click "PvP lookup" muscle memory.
     */
    private static class PlayerRow extends JPanel
    {
        /** Single fixed border used in both idle and hover states. The white
         *  hover outline is drawn manually in {@link #paintBorder(Graphics)}
         *  rather than via setBorder-swap so:
         *    1. The component's preferred size never changes on hover (the
         *       bottom matte and the hover outline both occupy the same 1px
         *       gutter at the row edge), so the inner scrollbar doesn't
         *       flicker between hidden/shown when the cursor moves between
         *       rows.
         *    2. We avoid a setBorder() call per hover transition. setBorder
         *       fires a PropertyChangeEvent + repaint per call; mouse-wheel
         *       scrolling can fire dozens of those per second as rows pass
         *       under the cursor, which was the residual scroll stutter. */
        private static final Border ROW_BORDER_FIXED = BorderFactory.createCompoundBorder(
            new MatteBorder(0, 0, 1, 0, new Color(0x40, 0x40, 0x40)),
            BorderFactory.createEmptyBorder(4, 6, 4, 6));

        private static final Color CHIP_BORDER_COLOR = new Color(0x88, 0x88, 0x88);
        /** Yellow for [Invited M:SS] — same family as Confirm-fight emphasis. */
        private static final Color CHIP_INVITED_COLOR = new Color(0xE5, 0xC0, 0x6B);
        /** Muted foreground used everywhere the row is greyed (blocked
         *  state). Matches the JLabel default-disabled tone so it reads
         *  as "inactive" without changing the panel's overall colour
         *  palette. The rank label is recoloured to the same grey so it
         *  doesn't pop against the muted name. */
        private static final Color BLOCKED_FG = new Color(0x70, 0x70, 0x70);
        private static final Color BLOCKED_BORDER = new Color(0x50, 0x50, 0x50);

        final LobbyMember p; // package-private so the lobby's tick refresher can key on it
        private final int fontBase;
        /** Re-queried on every {@link #render()} so the chip stays live. */
        private final Predicate<LobbyMember> isInvited;
        private final Function<LobbyMember, OutgoingInvite> getOutgoing;
        private final Consumer<String> onOpenProfile;
        private final FightStartCallback onFight;
        private final InviteCancelCallback onCancelInvite;
        /** Re-queried at construction so the next renderRoster picks up
         *  block changes immediately (block listener overrides call
         *  renderRoster directly). */
        private final boolean blocked;
        /** Re-queried at construction — true when the viewer's own rank
         *  sits outside this member's accept-invite slider band. The
         *  member would server-reject any {@code lobby/invite} from us
         *  with {@code RANK_OUT_OF_RANGE}, so the row renders with the
         *  whole-row grey treatment (matches Blocking visually) and a
         *  greyed-disabled [Fight] chip. Differs from {@link #blocked}
         *  in chip text + tooltip + click handler; both flags fold
         *  into {@link #greyed} for the body greying. */
        private final boolean outOfTheirRange;
        /** Operator matchmaking-suspend stamp ({@link LobbyMember#isSuspended},
         *  from {@code lobby/roster}'s {@code is_suspended}). When true the
         *  member stays visible but their [Fight] is greyed for every viewer
         *  (the server rejects invite/accept with {@code MATCHMAKING_SUSPENDED}).
         *  Folds into {@link #greyed} like the other two flags but keeps its
         *  own chip tooltip. */
        private final boolean suspended;
        /** Unified "render this row as muted / inactive" flag — the union
         *  of {@link #blocked}, {@link #outOfTheirRange}, and
         *  {@link #suspended} (see {@link #rowGreyed}). Drives the
         *  name colour, rank-chip hue, and every region/style/build
         *  chip's active/inactive palette so the whole row reads as
         *  inactive when any condition holds. The source flags
         *  stay separate for chip text + click semantics. */
        private final boolean greyed;
        /** Re-queried at construction — false when style/build
         *  advertisement doesn't overlap the local user's gate picks;
         *  [Fight] renders greyed and is a no-op. */
        private final boolean fightEnabled;
        /** {@code true} for the "Your profile displayed to others"
         *  row above the slider — suppresses the right-side action
         *  chip (no Fight / no Lookup chip — clicking the row body
         *  still opens the lookup) and any rank-text rendering when
         *  {@link LobbyMember#peakRankIdx} is sentinel-negative. */
        private final boolean selfPreview;

        /** Tracks the cursor across child boundaries so child→child crossings
         *  don't false-trigger an unhover on the leaf JLabel. */
        private boolean hovered;

        PlayerRow(LobbyMember p, int fontBase,
                  Predicate<LobbyMember> isInvited,
                  Function<LobbyMember, OutgoingInvite> getOutgoing,
                  Consumer<String> onOpenProfile,
                  FightStartCallback onFight,
                  InviteCancelCallback onCancelInvite,
                  Predicate<LobbyMember> isBlocked,
                  boolean selfPreview)
        {
            this(p, fontBase, isInvited, getOutgoing, onOpenProfile, onFight,
                onCancelInvite, isBlocked, m -> true, m -> false, selfPreview);
        }

        PlayerRow(LobbyMember p, int fontBase,
                  Predicate<LobbyMember> isInvited,
                  Function<LobbyMember, OutgoingInvite> getOutgoing,
                  Consumer<String> onOpenProfile,
                  FightStartCallback onFight,
                  InviteCancelCallback onCancelInvite,
                  Predicate<LobbyMember> isBlocked,
                  Predicate<LobbyMember> fightEnabled,
                  Predicate<LobbyMember> isOutOfTheirRange,
                  boolean selfPreview)
        {
            this.p = p;
            this.fontBase = fontBase;
            this.isInvited = isInvited;
            this.getOutgoing = getOutgoing;
            this.onOpenProfile = onOpenProfile;
            this.onFight = onFight;
            this.onCancelInvite = onCancelInvite;
            this.blocked = isBlocked != null && isBlocked.test(p);
            this.outOfTheirRange = isOutOfTheirRange != null && isOutOfTheirRange.test(p);
            this.suspended = p != null && p.isSuspended;
            this.greyed = rowGreyed(this.blocked, this.outOfTheirRange, this.suspended);
            this.fightEnabled = fightEnabled == null || fightEnabled.test(p);
            this.selfPreview = selfPreview;
            setLayout(new BorderLayout());
            setBackground(new Color(0x2b, 0x2b, 0x2b));
            setBorder(ROW_BORDER_FIXED);
            setAlignmentX(LEFT_ALIGNMENT);
            render();
        }

        /** Draw the white hover outline manually so swapping it on/off doesn't
         *  fire setBorder()'s PropertyChangeEvent + repaint per row per scroll
         *  tick — that was the residual stutter source. The line is drawn over
         *  the matte's bottom pixel and the row's other 3 edges; total visual
         *  size is unchanged. */
        @Override
        protected void paintBorder(Graphics g)
        {
            super.paintBorder(g);
            if (hovered)
            {
                g.setColor(Color.WHITE);
                g.drawRect(0, 0, getWidth() - 1, getHeight() - 1);
            }
        }

        /** Pin row height to preferred so BoxLayout Y_AXIS doesn't spread
         *  rows to fill the viewport (regression from beta 1). */
        @Override
        public Dimension getMaximumSize()
        {
            Dimension d = super.getPreferredSize();
            return new Dimension(Integer.MAX_VALUE, d.height);
        }

        private void render()
        {
            removeAll();
            JPanel center = new JPanel();
            center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
            center.setOpaque(false);
            center.add(buildHeaderRow());
            center.add(Box.createVerticalStrut(3));
            center.add(buildChipsRow());
            // Bottom row: build chips by default ([MOD]? [Main] [Zerker]
            // [Pure]) OR — when the row is greyed because the viewer's
            // rank is outside this member's accept-invite band — the
            // "Accepts fights from <min> to <max> rating" label with
            // both rank labels rank-colour-coded. The swap matches
            // 2026-05-26 user spec: the build chips carry no
            // actionable info when we can't invite them anyway, so we
            // reclaim that row to explain WHY the row is greyed.
            // Blocking-greyed rows keep the build chips because the
            // [Blocking] chip + tooltip already explain that state.
            // Build chips render on a separate row below so [Pure][Zerker]
            // [Main] don't compete with the longer [Region][NH][Veng][Multi]
            // [DMM] strip — 8 chips on one FlowLayout row wraps unpredictably
            // in the 225px sidepanel.
            center.add(Box.createVerticalStrut(2));
            if (outOfTheirRange && !blocked)
            {
                center.add(buildAcceptsRangeRow());
            }
            else
            {
                center.add(buildBuildsRow());
            }

            add(center, BorderLayout.CENTER);

            // Self-preview suppresses the EAST action chip — there's
            // no Fight option (can't fight yourself) and no Lookup
            // chip either (the whole row body is already clickable
            // and routes to routeOpenProfile). Other rows still get
            // their chip per buildActionChip() rules.
            if (!selfPreview)
            {
                // Wrap the chip so the 6px margin lives on the wrapper, not the
                // chip's own border (chip border tracks its text width).
                JComponent action = buildActionChip();
                JPanel actionWrap = new JPanel(new BorderLayout());
                actionWrap.setOpaque(false);
                actionWrap.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
                actionWrap.add(action, BorderLayout.CENTER);
                add(actionWrap, BorderLayout.EAST);
            }

            // Profile-click handler walks only the CENTER subtree so the
            // action chip can never double-fire as a profile click.
            installProfileInteraction(center);

            revalidate();
            repaint();
        }

        private JComponent buildActionChip()
        {
            // Resolve the LABEL via the source-of-truth helper so the
            // text decision is unit-tested without instantiating the
            // panel; the COLOUR + tooltip + click handler still
            // branch here because they depend on Swing internals.
            OutgoingInvite oi = getOutgoing != null ? getOutgoing.apply(p) : null;
            boolean invited = isInvited != null && isInvited.test(p);
            String label = actionChipLabelFor(blocked, oi, invited);

            if (blocked)
            {
                // Blocked card: chip routes to Player Lookup → Unblock
                // (no dedicated "Unblock" widget on the row). Colour
                // matches the greyed body so the chip reads "muted /
                // inactive". Label is "Blocking" per 2026-05-25 user
                // spec — explicit verb signals the active block state
                // without relying on the tooltip.
                JLabel chip = makeActionChip(label, BLOCKED_FG, BLOCKED_BORDER,
                    () -> { if (onOpenProfile != null) onOpenProfile.accept(p.name); });
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setToolTipText("Blocking " + p.name + " — open their profile to Unblock");
                return chip;
            }
            if (oi != null)
            {
                JLabel chip = makeActionChip(label, CHIP_INVITED_COLOR, CHIP_INVITED_COLOR,
                    () -> { if (onCancelInvite != null) onCancelInvite.cancel(p); });
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setToolTipText("Pending invite to " + p.name + " — click to cancel");
                return chip;
            }
            if (invited)
            {
                JLabel chip = makeActionChip(label, Color.WHITE, CHIP_BORDER_COLOR,
                    () -> { if (onOpenProfile != null) onOpenProfile.accept(p.name); });
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setToolTipText("Open " + p.name + "'s profile in Player Lookup");
                return chip;
            }
            if (outOfTheirRange)
            {
                // Their accept-invite slider excludes the viewer's
                // current rank — server would RANK_OUT_OF_RANGE any
                // lobby/invite we sent, so the chip renders greyed
                // and is a no-op. Body greying is handled separately
                // via the {@link #greyed} flag so the whole row
                // reads as muted (matches the Blocking visual
                // treatment, per 2026-05-26 user spec).
                JLabel chip = makeActionChip(label, BLOCKED_FG, BLOCKED_BORDER, () -> {});
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setCursor(Cursor.getDefaultCursor());
                chip.setToolTipText(p.name + " only accepts invites within their own rank range — your rank is outside it");
                return chip;
            }
            if (suspended)
            {
                // Operator matchmaking-suspend: the server rejects any
                // invite/accept with MATCHMAKING_SUSPENDED, so the chip
                // renders greyed and is a no-op for every viewer. Body
                // greying is handled via the {@link #greyed} flag.
                JLabel chip = makeActionChip(label, BLOCKED_FG, BLOCKED_BORDER, () -> {});
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setCursor(Cursor.getDefaultCursor());
                chip.setToolTipText(p.name + " is temporarily suspended from matchmaking");
                return chip;
            }
            if (!fightEnabled)
            {
                JLabel chip = makeActionChip(label, BLOCKED_FG, BLOCKED_BORDER, () -> {});
                chip.setName(ROW_ACTION_CHIP_NAME);
                chip.setCursor(Cursor.getDefaultCursor());
                chip.setToolTipText("No matching style/build — click Leave Lobby and re-join with wider filters");
                return chip;
            }
            JLabel chip = makeActionChip(label, Color.WHITE, CHIP_BORDER_COLOR,
                () -> { if (onFight != null) onFight.onFight(p); });
            chip.setName(ROW_ACTION_CHIP_NAME);
            chip.setToolTipText("Set up a fight with " + p.name);
            return chip;
        }

        /** Recursively installs the row's hover/click handler on every
         *  component inside {@code root}. We have to walk the tree because
         *  Swing dispatches mouse events to the deepest hit component — a
         *  listener on just the row would never see clicks that land on the
         *  name JLabel or a chip. */
        private void installProfileInteraction(Container root)
        {
            MouseAdapter ma = new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e)
                {
                    if (onOpenProfile != null) onOpenProfile.accept(p.name);
                }
                @Override
                public void mouseEntered(MouseEvent e)
                {
                    setHover(true);
                }
                @Override
                public void mouseExited(MouseEvent e)
                {
                    // Child→child crossings fire exit on the leaf — only
                    // unhover when the cursor really left the row bounds.
                    Point inRow = SwingUtilities.convertPoint(
                        e.getComponent(), e.getPoint(), PlayerRow.this);
                    if (!PlayerRow.this.contains(inRow)) setHover(false);
                }
            };
            addMouseListener(ma);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            attachListenerRecursively(root, ma);
        }

        private static void attachListenerRecursively(Container c, MouseListener ml)
        {
            for (Component child : c.getComponents())
            {
                child.addMouseListener(ml);
                if (child instanceof JComponent)
                {
                    ((JComponent) child).setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                }
                if (child instanceof Container)
                {
                    attachListenerRecursively((Container) child, ml);
                }
            }
        }

        private void setHover(boolean on)
        {
            if (this.hovered == on) return;
            this.hovered = on;
            // repaint() only — no setBorder() means no PropertyChangeEvent and
            // no parent revalidation cascade during mouse-wheel scroll.
            repaint();
        }

        /** name (base, full row width, no ellipsis) + rank (overlay,
         *  right-anchored, opaque on row bg, drawn on top via z-order).
         *  Long names render their full text and visually clip "under"
         *  the rank chip — the rank's opaque background masks the overflow
         *  and a 4px left padding on the rank gives a minimal readable
         *  gap between the last visible name char and the rank text. */
        private JComponent buildHeaderRow()
        {
            // peakRankIdx < 0 is the "unknown" sentinel. Two
            // sources produce it:
            //   1. Self-preview row — {@code selfPreview == true} —
            //      no authoritative self-rank source yet, so skip
            //      the right-side rank chip entirely and render the
            //      name in plain white (rank-coloured hue would be
            //      meaningless without a real rank).
            //   2. Remote roster row whose server-side rating
            //      hasn't been computed yet (first-ever roster push
            //      after signup, partial backend deploy missing
            //      rank_idx, etc) — {@code selfPreview == false} —
            //      render a muted "Waiting" chip in the rank slot
            //      so the row doesn't mis-render as RANK_LABELS[0]
            //      ("Bronze 3") and the user understands the rating
            //      simply hasn't arrived.
            // Bounds-check also defends against any future
            // out-of-range index from a malformed wire payload.
            boolean rankKnown = p.peakRankIdx >= 0 && p.peakRankIdx < RANK_LABELS.length;
            String rankLabel = rankKnown ? RANK_LABELS[p.peakRankIdx] : "";
            // Greyed rows render in a muted grey across the entire
            // header (name + rank chip) so the row reads as inactive.
            // Covers both Blocking (the local user blocked them) and
            // out-of-their-range (their slider excludes the viewer).
            // The rank label's normal hue would otherwise pop against
            // the greyed name.
            Color rankColor = greyed
                ? BLOCKED_FG
                : (rankKnown ? RankUtils.getRankColor(rankLabel) : Color.WHITE);

            String displayName = displayNameOf(p);
            NonEllipsisLabel name = new NonEllipsisLabel(displayName);
            name.setFont(name.getFont().deriveFont(Font.BOLD, (float) fontBase));
            name.setForeground(rankColor);
            // Blocking and out-of-their-range share the muted body but
            // need different hover text so the user knows WHY the row
            // is dim. Blocking wins precedence (it implies a deliberate
            // user action; out-of-their-range is just a slider state).
            String nameTooltip;
            if (blocked) nameTooltip = displayName + " (blocked — click to Unblock from Player Lookup)";
            else if (outOfTheirRange) nameTooltip = displayName + " (your rank is outside their accept-invite range)";
            else if (suspended) nameTooltip = displayName + " (temporarily suspended from matchmaking)";
            else nameTooltip = displayName;
            name.setToolTipText(nameTooltip);

            if (!rankKnown)
            {
                if (selfPreview)
                {
                    // No rank chip on the right — just the name flush-left.
                    // OverlayRightRow expects two children; substitute an
                    // empty placeholder so the layout invariants hold.
                    JLabel placeholder = new JLabel("");
                    placeholder.setOpaque(false);
                    return new OverlayRightRow(name, placeholder);
                }
                // Remote row with unknown rank — render "Waiting" in
                // the same slot a real rank label would occupy. Muted
                // grey (or greyed-row grey) so it's visually subordinate
                // to real rank labels and never gets confused for a
                // real rank tier. Tooltip explains the state.
                Color waitingColor = greyed ? BLOCKED_FG : new Color(0xaa, 0xaa, 0xaa);
                JLabel waiting = new JLabel("Waiting");
                waiting.setFont(waiting.getFont().deriveFont(Font.BOLD, (float) fontBase));
                waiting.setForeground(waitingColor);
                waiting.setHorizontalAlignment(SwingConstants.RIGHT);
                waiting.setOpaque(true);
                waiting.setBackground(new Color(0x2b, 0x2b, 0x2b));
                waiting.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
                waiting.setToolTipText("Rating not yet available");
                return new OverlayRightRow(name, waiting);
            }

            JLabel rank = new JLabel(rankLabel);
            rank.setFont(rank.getFont().deriveFont(Font.BOLD, (float) fontBase));
            rank.setForeground(rankColor);
            rank.setHorizontalAlignment(SwingConstants.RIGHT);
            // Opaque + matching row bg = masks the overflowing name text
            // wherever the two would otherwise visually overlap. The 4px
            // left inset is the "minimal spacing" gap.
            rank.setOpaque(true);
            rank.setBackground(new Color(0x2b, 0x2b, 0x2b));
            rank.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));

            return new OverlayRightRow(name, rank);
        }

        /** [Region] [NH] [Veng] [Multi] [DMM] — style chips dim when not
         *  advertised. The MOD chip lives on the build row below, not here.
         *  When the player advertises <i>every</i> style, the four
         *  per-style chips collapse into a single [Any Style] chip so
         *  the row matches the "Style: Any Style" wording from the
         *  pre-lobby gate's current-style bar. */
        private JPanel buildChipsRow()
        {
            JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
            chips.setOpaque(false);
            chips.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));

            int chipFont = Math.max(10, fontBase - 3);
            // Palette: region=white, style=yellow. Greyed rows
            // (Blocking or out-of-their-range) force all chips to the
            // inactive grey palette so the whole card reads as muted.
            chips.add(makeChip(p.region, !greyed, Color.WHITE, chipFont));
            Color styleColor = new Color(0xff, 0xc1, 0x07);
            if (p.styles.size() == Style.values().length)
            {
                chips.add(makeChip("Any Style", !greyed, styleColor, chipFont));
            }
            else
            {
                for (Style s : Style.values())
                {
                    boolean advertised = !greyed && p.styles.contains(s);
                    chips.add(makeChip(s.label, advertised, styleColor, chipFont));
                }
            }
            return chips;
        }

        /** [MOD]? [Main] [Zerker] [Pure] — build chips dim when the player
         *  doesn't advertise that build. Cyan so they're visually distinct
         *  from the yellow style chips on the row above; MOD stays red.
         *  p.builds is guaranteed ≥1 by LobbyMember's contract, so at least
         *  one build chip is always lit. When the player advertises
         *  <i>every</i> build type, the per-build chips collapse into a
         *  single [Any Build] chip mirroring the {@code buildChipsRow}
         *  [Any Style] collapse. */
        private JPanel buildBuildsRow()
        {
            JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
            chips.setOpaque(false);
            chips.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));

            int chipFont = Math.max(10, fontBase - 3);
            if (p.isMod)
            {
                chips.add(makeChip("MOD", !greyed, new Color(0xff, 0x55, 0x55), chipFont));
            }
            Color buildColor = new Color(0x4f, 0xc3, 0xf7);
            if (p.builds.size() == BuildType.values().length)
            {
                chips.add(makeChip("Any Build", !greyed, buildColor, chipFont));
            }
            else
            {
                for (BuildType a : BuildType.values())
                {
                    boolean advertised = !greyed && p.builds.contains(a);
                    chips.add(makeChip(a.label, advertised, buildColor, chipFont));
                }
            }
            return chips;
        }

        /** Bottom-row swap for out-of-their-range greyed rows:
         *  "Accepts fights from &lt;min&gt; to &lt;max&gt; rating"
         *  with both rank labels coloured per
         *  {@link RankUtils#getRankColor(String)} (same colour
         *  scheme as the panel's own rank-range slider min/max
         *  labels — visual rhyme).
         *
         *  <p>HTML rendering rather than three side-by-side labels
         *  because (a) it keeps the row tight (no internal layout
         *  cascade per render) and (b) the surrounding "Accepts
         *  fights from" / "to" / "rating" text needs to wrap
         *  cleanly inside the ~200 px sidepanel — a FlowLayout of
         *  separately-coloured labels would break to a new line
         *  mid-phrase. */
        private JComponent buildAcceptsRangeRow()
        {
            JPanel wrap = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
            wrap.setOpaque(false);
            wrap.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));

            int textFont = Math.max(10, fontBase - 3);
            JLabel label = new JLabel(buildAcceptsRangeHtml(
                p.minRankIdx, p.maxRankIdx, RANK_LABELS));
            label.setFont(label.getFont().deriveFont(Font.BOLD, (float) textFont));
            // Surrounding copy ("Accepts fights from", "to", "rating")
            // stays in the muted-grey palette used by every greyed-row
            // body element so only the rank labels themselves pop.
            label.setForeground(BLOCKED_FG);
            label.setToolTipText(p.name + "'s accept-invite rank range is "
                + safeRankLabel(p.minRankIdx, RANK_LABELS)
                + " to " + safeRankLabel(p.maxRankIdx, RANK_LABELS));
            wrap.add(label);
            return wrap;
        }

        private static JLabel makeChip(String text, boolean active, Color activeColor, int fontPt)
        {
            // ChipLabel (not a vanilla JLabel) bypasses Substance L&F's
            // LabelUI text painting. Substance treats MouseEntered /
            // MouseExited from the row-level MouseAdapter (installed
            // via attachListenerRecursively, which fans out to every
            // child including these chips) as a label-rollover state
            // change and triggers a delegate repaint that briefly
            // erases the foreground text — visible to the user as the
            // chip's contents disappearing while the cursor is over a
            // row. Painting the text ourselves in paintComponent skips
            // the delegate entirely; the border still paints normally
            // because paintBorder is unaffected by the L&F text path.
            ChipLabel chip = new ChipLabel(text);
            chip.setFont(chip.getFont().deriveFont(active ? Font.BOLD : Font.PLAIN, (float) fontPt));
            chip.setForeground(active ? activeColor : new Color(0x55, 0x55, 0x55));
            Color borderColor = active ? activeColor : new Color(0x3a, 0x3a, 0x3a);
            chip.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(borderColor, 1),
                BorderFactory.createEmptyBorder(1, 5, 1, 5)));
            chip.setOpaque(false);
            return chip;
        }

        /** Tight JLabel chip — much smaller than a JButton under Substance L&F.
         *  textColor / borderColor are split so callers can paint white text
         *  inside a quiet grey outline ([Fight] / [Lookup] convention).
         *
         *  <p>ChipLabel (not vanilla JLabel) so the action text doesn't
         *  flicker / disappear on hover under Substance — same fix as
         *  {@link #makeChip}. Otherwise users can lose track of which
         *  chip says [Fight] vs [Invited 9:42] mid-hover. */
        private JLabel makeActionChip(String text, Color textColor, Color borderColor, Runnable onClick)
        {
            ChipLabel chip = new ChipLabel(text);
            chip.setFont(chip.getFont().deriveFont(Font.BOLD, (float) fontBase));
            chip.setForeground(textColor);
            chip.setHorizontalAlignment(SwingConstants.CENTER);
            chip.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(borderColor, 1),
                BorderFactory.createEmptyBorder(1, 3, 1, 3)));
            chip.setOpaque(false);
            chip.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            chip.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e) { onClick.run(); }
            });
            return chip;
        }
    }

    // -------------------- Incoming invites --------------------

    /**
     * One incoming-invite card. Receiver-side only — the sender has already
     * picked style + location, so the receiver sees the full proposed match
     * upfront and only has to choose Accept or Decline.
     *
     * <p>Layout:
     * <pre>
     * +---------------------------------------------+
     * | Zezima             3rd Age      [Lookup ]  |   header (rank-coloured) + Lookup chip
     * | [NA-W] [NH] [Veng]                         |   region + style chips
     * | [MOD?] [Main] [Zerker] [Pure]              |   MOD? + build chips
     * | NH - Main @ Arena * 9:43                   |   style - build @ place * countdown
     * |   [ Accept Fight ]   [ Decline Fight ]     |   actions (full-width row)
     * +---------------------------------------------+
     * </pre>
     */
    private final class IncomingInvitePanel extends JPanel
    {
        private final LobbyMember sender;

        /** Read-only accessor used by {@link #onIncomingInviteCancelled}
         *  to rebuild {@link #incomingInviteNames} after removing a
         *  card. Package-private would be cleaner but the inner-class
         *  scope already restricts it to this file. */
        LobbyMember getSender() { return sender; }
        private final Style style;
        /** Build the sender picked for this specific invite (one of the
         *  receiver's advertised builds). Drives the info text alongside
         *  style + location. */
        private final BuildType build;
        private final String location;
        private final long expiresAt;
        private final Runnable onAccept;
        private final Runnable onDecline;
        private final Consumer<String> openProfile;
        private Timer countdown;
        private JLabel infoLabel;

        IncomingInvitePanel(LobbyMember sender, Style style, BuildType build,
                            String location, long ttlMs,
                            Runnable onAccept, Runnable onDecline, Consumer<String> openProfile)
        {
            this.sender = sender;
            this.style = style;
            this.build = build;
            this.location = location;
            this.expiresAt = System.currentTimeMillis() + ttlMs;
            this.onAccept = onAccept;
            this.onDecline = onDecline;
            this.openProfile = openProfile;

            setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
            setBackground(new Color(0x33, 0x2a, 0x1e));
            setOpaque(true);
            // Amber LEFT bar + bottom divider — reads as "incoming notification".
            setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createCompoundBorder(
                    new MatteBorder(0, 3, 0, 0, new Color(0xff, 0xc1, 0x07)),
                    new MatteBorder(0, 0, 1, 0, new Color(0x40, 0x40, 0x40))),
                BorderFactory.createEmptyBorder(4, 6, 6, 6)));
            setAlignmentX(LEFT_ALIGNMENT);

            buildHeaderRow();
            add(Box.createVerticalStrut(3));
            buildChipsRow();
            // Mirrors the roster row layout: build chips go on their own line
            // directly below the [Region]+style strip so the card reads as
            // "same profile, fewer affordances".
            add(Box.createVerticalStrut(2));
            buildBuildsRow();
            add(Box.createVerticalStrut(3));
            buildInfoRow();
            add(Box.createVerticalStrut(4));
            buildActionRow();
            startCountdown();
        }

        @Override
        public Dimension getMaximumSize()
        {
            Dimension d = super.getPreferredSize();
            return new Dimension(Integer.MAX_VALUE, d.height);
        }

        private void buildHeaderRow()
        {
            // peakRankIdx < 0 (or out of range) means the rating
            // isn't yet available — typically a synthetic sender
            // built from flat invite fields when the roster cache
            // hadn't seen them yet. Render "Waiting" in the rank
            // slot and white name text so the card doesn't crash
            // on RANK_LABELS[-1] or mis-render as "Bronze 3".
            boolean rankKnown = sender.peakRankIdx >= 0 && sender.peakRankIdx < RANK_LABELS.length;
            String rankLabel = rankKnown ? RANK_LABELS[sender.peakRankIdx] : "Waiting";
            Color rankColor = rankKnown
                ? RankUtils.getRankColor(rankLabel)
                : Color.WHITE;
            Color rankTextColor = rankKnown
                ? rankColor
                : new Color(0xaa, 0xaa, 0xaa);

            // Base: name spans full row width, paints its full text and
            // clips under the rank/lookup overlay (no ellipsis).
            String displayName = displayNameOf(sender);
            NonEllipsisLabel name = new NonEllipsisLabel(displayName);
            name.setFont(name.getFont().deriveFont(Font.BOLD, (float) ROW_FONT_PT));
            name.setForeground(rankColor);
            name.setToolTipText(displayName);

            JLabel rank = new JLabel(rankLabel);
            rank.setFont(rank.getFont().deriveFont(Font.BOLD, (float) ROW_FONT_PT));
            rank.setForeground(rankTextColor);
            rank.setHorizontalAlignment(SwingConstants.RIGHT);
            if (!rankKnown) rank.setToolTipText("Rating not yet available");

            // [Lookup] chip — opens Player Lookup so the receiver can vet
            // the sender before accept/decline. NOT the accept path.
            JLabel lookup = new JLabel("Lookup");
            lookup.setFont(lookup.getFont().deriveFont(Font.BOLD, (float) (ROW_FONT_PT - 1)));
            lookup.setForeground(Color.WHITE);
            lookup.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(0x88, 0x88, 0x88), 1),
                BorderFactory.createEmptyBorder(1, 4, 1, 4)));
            lookup.setOpaque(false);
            lookup.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            lookup.setToolTipText("Open " + displayName + "'s profile in Player Lookup");
            lookup.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e)
                {
                    if (openProfile != null) openProfile.accept(sender.name);
                }
            });

            // Overlay: rank + [Lookup] cluster, opaque card-bg so name
            // overflow is visually masked. 4px left inset = minimal
            // breathing room before the rank text. Inner BorderLayout's
            // 6px hgap is retained because rank and [Lookup] are two
            // distinct chips that should not visually merge.
            JPanel east = new JPanel(new BorderLayout(6, 0));
            east.setOpaque(true);
            east.setBackground(new Color(0x33, 0x2a, 0x1e));
            east.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
            east.add(rank, BorderLayout.CENTER);
            east.add(lookup, BorderLayout.EAST);

            OverlayRightRow row = new OverlayRightRow(name, east);
            row.setAlignmentX(LEFT_ALIGNMENT);
            add(row);
        }

        private void buildChipsRow()
        {
            JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
            chips.setOpaque(false);
            chips.setAlignmentX(LEFT_ALIGNMENT);
            int chipFont = Math.max(10, ROW_FONT_PT - 3);
            chips.add(makeChipStatic(sender.region, true, Color.WHITE, chipFont));
            for (Style s : Style.values())
            {
                boolean advertised = sender.styles.contains(s);
                chips.add(makeChipStatic(s.label, advertised, new Color(0xff, 0xc1, 0x07), chipFont));
            }
            add(chips);
        }

        /** [MOD]? [Main] [Zerker] [Pure] — second chip row, cyan to distinguish
         *  from the yellow style chips above. MOD (red) sits to the left of
         *  the build chips on this row. Same advertised/dim pattern the
         *  roster row uses. */
        private void buildBuildsRow()
        {
            JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
            chips.setOpaque(false);
            chips.setAlignmentX(LEFT_ALIGNMENT);
            int chipFont = Math.max(10, ROW_FONT_PT - 3);
            if (sender.isMod)
            {
                chips.add(makeChipStatic("MOD", true, new Color(0xff, 0x55, 0x55), chipFont));
            }
            Color buildColor = new Color(0x4f, 0xc3, 0xf7);
            for (BuildType a : BuildType.values())
            {
                boolean advertised = sender.builds.contains(a);
                chips.add(makeChipStatic(a.label, advertised, buildColor, chipFont));
            }
            add(chips);
        }

        private void buildInfoRow()
        {
            infoLabel = new JLabel(buildInfoText(System.currentTimeMillis()));
            // Match the Accept Fight / Decline Fight button font (BOLD, ROW_FONT_PT-1)
            // so the "Style - Build @ Place * X:XX" line is the visual
            // focal point of the card.
            infoLabel.setFont(infoLabel.getFont().deriveFont(Font.BOLD,
                (float) (ROW_FONT_PT - 1)));
            infoLabel.setForeground(new Color(0xdd, 0xdd, 0xdd));
            infoLabel.setAlignmentX(LEFT_ALIGNMENT);
            add(infoLabel);
        }

        private String buildInfoText(long now)
        {
            long remaining = Math.max(0, expiresAt - now);
            long totalSec = (remaining + 999) / 1000;
            long mins = totalSec / 60;
            long secs = totalSec % 60;
            // "Style - Build @ Place * X:XX" per spec — shared formatter
            // keeps this identical to the opponent line on Confirm/Waiting/MeetAt.
            return formatStyleBuildPlace(style, build, location)
                + " * " + String.format("%d:%02d", mins, secs);
        }

        private void buildActionRow()
        {
            JPanel actions = new JPanel(new GridLayout(1, 2, 6, 0));
            actions.setOpaque(false);
            actions.setAlignmentX(LEFT_ALIGNMENT);
            actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

            JButton accept = new JButton("Accept Fight");
            accept.setFont(accept.getFont().deriveFont(Font.BOLD, (float) (ROW_FONT_PT - 1)));
            accept.setMargin(new Insets(2, 6, 2, 6));
            accept.setFocusPainted(false);
            accept.setBackground(new Color(0x2e, 0x7d, 0x32));
            accept.setForeground(Color.WHITE);
            accept.setOpaque(true);
            accept.setBorderPainted(false);

            JButton decline = new JButton("Decline Fight");
            decline.setFont(decline.getFont().deriveFont(Font.BOLD, (float) (ROW_FONT_PT - 1)));
            decline.setMargin(new Insets(2, 6, 2, 6));
            decline.setFocusPainted(false);
            decline.setBackground(new Color(0x66, 0x33, 0x33));
            decline.setForeground(Color.WHITE);
            decline.setOpaque(true);
            decline.setBorderPainted(false);

            // Debounce both buttons + relabel the clicked one so the user
            // sees instant evidence the press registered. Pre-debounce,
            // a double-click on Accept fired two acceptInvite() calls
            // (server idempotent but UI didn't repaint between clicks),
            // and the ~200ms Swing invalidate/repaint gap after the
            // card-removal action produced the same "I clicked but
            // nothing happened" black-box symptom we see on Confirm
            // Fight. Log the click too so the receiver-side debug log
            // proves the click fired in asymmetric-visibility reports
            // where only one side's log is available.
            accept.addActionListener(e ->
            {
                if (!accept.isEnabled()) return;
                LOG.debug("MatchmakingLobbyPanel.IncomingInvitePanel: Accept Fight clicked sender={}",
                    sender == null ? "?" : sender.name);
                accept.setEnabled(false);
                accept.setText("Accepting\u2026");
                decline.setEnabled(false);
                stopCountdown();
                onAccept.run();
            });
            decline.addActionListener(e ->
            {
                if (!decline.isEnabled()) return;
                LOG.debug("MatchmakingLobbyPanel.IncomingInvitePanel: Decline Fight clicked sender={}",
                    sender == null ? "?" : sender.name);
                decline.setEnabled(false);
                decline.setText("Declining\u2026");
                accept.setEnabled(false);
                stopCountdown();
                onDecline.run();
            });

            actions.add(accept);
            actions.add(decline);
            add(actions);
        }

        private void startCountdown()
        {
            countdown = new Timer(1000, ev ->
            {
                long now = System.currentTimeMillis();
                if (now >= expiresAt)
                {
                    stopCountdown();
                    onDecline.run();
                    return;
                }
                if (infoLabel != null) infoLabel.setText(buildInfoText(now));
            });
            countdown.setRepeats(true);
            countdown.start();
        }

        private void stopCountdown()
        {
            if (countdown != null)
            {
                countdown.stop();
                countdown = null;
            }
        }
    }

    /** Outer-class twin of {@link PlayerRow#makeChip}. */
    private static JLabel makeChipStatic(String text, boolean active, Color activeColor, int fontPt)
    {
        // See PlayerRow.makeChip for why this is a ChipLabel rather
        // than a vanilla JLabel — same Substance L&F rollover-erasure
        // bug applies to incoming-invite chips when the user hovers
        // the receiver-side card.
        ChipLabel chip = new ChipLabel(text);
        chip.setFont(chip.getFont().deriveFont(active ? Font.BOLD : Font.PLAIN, (float) fontPt));
        chip.setForeground(active ? activeColor : new Color(0x55, 0x55, 0x55));
        Color borderColor = active ? activeColor : new Color(0x3a, 0x3a, 0x3a);
        chip.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(borderColor, 1),
            BorderFactory.createEmptyBorder(1, 5, 1, 5)));
        chip.setOpaque(false);
        return chip;
    }

    /** JLabel subclass whose {@link #paintComponent} bypasses the L&F UI
     *  delegate's text rendering — under Substance L&F (which RuneLite
     *  ships with), JLabels auto-truncate with {@code "…"} when their
     *  bounds are narrower than the rendered text's preferred width. By
     *  drawing the text ourselves with {@link Graphics2D#drawString}, the
     *  text simply clips at the component's right edge (no ellipsis).
     *
     *  Intended for player-name labels paired with an {@link OverlayRightRow}
     *  that lets the right-side rank chip visually mask the overflowing
     *  characters. Not a drop-in for general JLabels — single-line LTR
     *  text only, no icon, no border insets, vertical-centered baseline. */
    private static final class NonEllipsisLabel extends JLabel
    {
        NonEllipsisLabel(String text)
        {
            super(text);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            try
            {
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                    RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setColor(getForeground());
                g2.setFont(getFont());
                FontMetrics fm = g2.getFontMetrics();
                int baselineY = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
                String t = getText();
                if (t != null) g2.drawString(t, 0, baselineY);
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    /** Border-aware sibling of {@link NonEllipsisLabel} used for the
     *  per-row style/build/region chips ([Main], [Pure], [Any Build],
     *  [NA-W], etc.). Same rationale as NonEllipsisLabel — bypass the
     *  Substance L&F text-rendering path — but here the motivation is
     *  hover stability, not ellipsis suppression: under Substance, a
     *  vanilla JLabel parented inside a panel that has a row-level
     *  MouseListener fanout (PlayerRow's attachListenerRecursively
     *  installs the same adapter on every descendant) repaints with a
     *  blank foreground on hover state changes, making chip text
     *  intermittently disappear while the cursor sits over a row.
     *
     *  <p>Painting the text directly in paintComponent skips
     *  Substance's LabelUI entirely. The chip's CompoundBorder
     *  (line + empty padding) still paints normally because
     *  {@link JComponent#paintBorder(Graphics)} is independent of the
     *  L&F text path. Honours horizontal-alignment + border insets so
     *  centred and left-aligned chip variants both render correctly. */
    private static final class ChipLabel extends JLabel
    {
        ChipLabel(String text)
        {
            super(text);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            try
            {
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                    RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setColor(getForeground());
                g2.setFont(getFont());
                Insets in = getInsets();
                FontMetrics fm = g2.getFontMetrics();
                String t = getText();
                if (t == null || t.isEmpty()) return;
                int textW = fm.stringWidth(t);
                // Centre vertically inside the inner content box (height
                // minus border insets). Centre or left-align horizontally
                // based on the JLabel's horizontalAlignment setting so
                // makeActionChip-style centred chips and the default
                // left-aligned chips both render at the right x.
                int innerH = getHeight() - in.top - in.bottom;
                int baselineY = in.top + ((innerH - fm.getHeight()) / 2) + fm.getAscent();
                int x = in.left;
                if (getHorizontalAlignment() == SwingConstants.CENTER)
                {
                    int innerW = getWidth() - in.left - in.right;
                    x = in.left + Math.max(0, (innerW - textW) / 2);
                }
                else if (getHorizontalAlignment() == SwingConstants.RIGHT
                    || getHorizontalAlignment() == SwingConstants.TRAILING)
                {
                    int innerW = getWidth() - in.left - in.right;
                    x = in.left + Math.max(0, innerW - textW);
                }
                g2.drawString(t, x, baselineY);
            }
            finally
            {
                g2.dispose();
            }
        }

        /** Substance L&F's LabelUI computes a preferred width using its
         *  own font metrics that under-report glyph widths for the
         *  derived bold 15pt run we use on the rank slider — the
         *  result is BorderLayout assigning a width slightly less
         *  than the rendered text needs, which Swing then clips at
         *  paint time. Recomputing preferred width from the actual
         *  AWT FontMetrics here gets the layout-time and paint-time
         *  metrics back in sync, so labels like "Bronze 3" /
         *  "3rd Age 1" get exactly the width they paint into.
         *
         *  Pure JLabels (no border, no icon) so the calc is just
         *  insets + text width + tiny safety margin. The +2px
         *  belt-and-braces guards against sub-pixel rounding when
         *  the parent uses a non-integer Graphics2D scale (HiDPI).
         *  Height defers to super so vertical-centring inside
         *  paintComponent agrees with the parent's row height. */
        @Override
        public Dimension getPreferredSize()
        {
            String t = getText();
            if (t == null || t.isEmpty()) return super.getPreferredSize();
            FontMetrics fm = getFontMetrics(getFont());
            Insets in = getInsets();
            int w = fm.stringWidth(t) + in.left + in.right + 2;
            int h = super.getPreferredSize().height;
            return new Dimension(w, h);
        }
    }

    /** Two-child header row where {@code base} spans the row's full width
     *  and {@code overlay} is right-anchored on top of it (in Swing
     *  z-order). The overlay must be opaque with the row's background
     *  colour — that's what visually masks any base content that would
     *  otherwise overflow into the overlay's territory.
     *
     *  Used for player-name rows so long names render their full text and
     *  visually clip under the rank/lookup cluster instead of ellipsizing.
     *  The 4px {@code EmptyBorder(0, 4, 0, 0)} the caller sets on the
     *  overlay provides the "minimal spacing" gap the user requested
     *  between the last visible character of the name and the rank text. */
    private static final class OverlayRightRow extends JPanel
    {
        private final JComponent base;
        private final JComponent overlay;

        OverlayRightRow(JComponent base, JComponent overlay)
        {
            super(null); // manual layout — neither BorderLayout nor BoxLayout supports z-stacked overlap
            setOpaque(false);
            this.base = base;
            this.overlay = overlay;
            // Swing paints children in REVERSE component-array order, so
            // index 0 is drawn last (= on top). Add overlay first so it
            // wins the z-order against the base.
            add(overlay);
            add(base);
        }

        @Override
        public void doLayout()
        {
            int w = getWidth();
            int h = getHeight();
            Dimension op = overlay.getPreferredSize();
            int ow = Math.min(op.width, w);
            overlay.setBounds(w - ow, 0, ow, h);
            // Base spans the entire row; its right portion is visually
            // masked by the overlay's opaque background where they overlap.
            base.setBounds(0, 0, w, h);
        }

        @Override
        public Dimension getPreferredSize()
        {
            Dimension bp = base.getPreferredSize();
            Dimension op = overlay.getPreferredSize();
            // Preferred = base + overlay so the parent BoxLayout knows the
            // "natural" width. Actual width comes from the parent and may
            // be smaller, in which case base clips under overlay.
            return new Dimension(bp.width + op.width, Math.max(bp.height, op.height));
        }

        @Override
        public Dimension getMaximumSize()
        {
            return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
        }

        @Override
        public Dimension getMinimumSize()
        {
            // Allow the row to shrink horizontally to just the overlay's
            // width — the base happily clips under it.
            Dimension op = overlay.getPreferredSize();
            return new Dimension(op.width, getPreferredSize().height);
        }
    }

    /** Adds an incoming-invite card to the top stack and flips the sender's
     *  roster chip to [Lookup] for the lifetime of the invite. Driven by
     *  {@link #onIncomingInvite} listener pushes; never seeded inline.
     *
     *  <p>The accept / decline runnables forward to the {@link LobbyService}
     *  using the original {@link IncomingInvite} (so the server can match
     *  by {@code inviteId}). The ConfirmFight transition is NOT triggered
     *  here — it arrives asynchronously as an {@link #onFightProposed}
     *  push the server fires to both players once the receiver accepts. */
    private void addIncomingInvite(IncomingInvite invite)
    {
        if (invitesContainer == null || invite == null || invite.sender == null) return;
        final LobbyMember sender = invite.sender;
        final String inviteId = invite.inviteId;
        // Idempotent guard: if the exact same invite_id is already on
        // the strip, drop the duplicate add. Pre-fix the dedupe loop
        // {@code continue}'d past matching ids but the post-loop
        // {@code invitesContainer.add(card)} still ran, producing the
        // "two invite cards from one sender" symptom in the
        // 2026-05-21 QA log (gamerwoadie's wire showed only one
        // {@code lobby/invite_received}, yet the user reported two
        // visible cards — only path is a double-{@code addIncomingInvite}
        // for the same {@code invite_id}, e.g. a replayed bus event
        // or a future call site that re-routes through this method).
        // Returning early matches the documented "idempotent against
        // duplicate invite_id" semantic.
        if (inviteId != null && incomingCardsById.containsKey(inviteId))
        {
            LOG.debug("MatchmakingLobbyPanel.addIncomingInvite: skipping duplicate inviteId={} sender={}",
                inviteId, sender.name);
            return;
        }
        // Dedupe by sender's player_id: only one invite card per
        // sender at a time, mirroring the "one outgoing invite per
        // sender" semantic the server enforces. If the sender has an
        // older card still on the stack (e.g. they cancelled +
        // re-sent before the cancel push landed on our wire, or a
        // partial-deploy backend pushed two invite_received frames
        // for what should have been a single invite), replace it
        // with this newer one — the server treats the newer
        // invite_id as authoritative.
        java.util.Iterator<Map.Entry<String, IncomingInvitePanel>> it
            = incomingCardsById.entrySet().iterator();
        while (it.hasNext())
        {
            Map.Entry<String, IncomingInvitePanel> e = it.next();
            LobbyMember existingSender = senderOfCard(e.getValue());
            if (existingSender != null
                && sender.playerId != null
                && sender.playerId.equals(existingSender.playerId))
            {
                removeInvite(e.getValue());
                incomingInviteNames.remove(existingSender.name);
                it.remove();
            }
        }
        incomingInviteNames.add(sender.name);
        IncomingInvitePanel[] holder = new IncomingInvitePanel[1];
        Runnable accept = () ->
        {
            incomingInviteNames.remove(sender.name);
            if (inviteId != null) incomingCardsById.remove(inviteId);
            removeInvite(holder[0]);
            // Receiver flow: server creates the fight session and pushes
            // onFightProposed to both players — that listener swaps the
            // panel into ConfirmFight (30s window). Go-back-to-Lobby exits
            // the view at any point.
            service.acceptInvite(invite);
            renderRoster();
        };
        Runnable decline = () ->
        {
            incomingInviteNames.remove(sender.name);
            if (inviteId != null) incomingCardsById.remove(inviteId);
            removeInvite(holder[0]);
            service.declineInvite(invite);
            renderRoster();
        };
        long ttlMs = Math.max(0L, invite.expiresAtEpochMs - System.currentTimeMillis());
        IncomingInvitePanel card = new IncomingInvitePanel(
            sender, invite.style, invite.build, invite.location, ttlMs,
            accept, decline,
            this::routeOpenProfile);
        holder[0] = card;
        if (inviteId != null) incomingCardsById.put(inviteId, card);
        invitesContainer.add(card);
        invitesContainer.add(Box.createVerticalStrut(4));
        refreshInvitesContainer();
        renderRoster();
    }

    private void removeInvite(IncomingInvitePanel card)
    {
        if (invitesContainer == null || card == null) return;
        // Drop the card + its trailing strut so the gap collapses too.
        Component[] kids = invitesContainer.getComponents();
        for (int i = 0; i < kids.length; i++)
        {
            if (kids[i] == card)
            {
                invitesContainer.remove(card);
                if (i + 1 < kids.length && kids[i + 1] instanceof Box.Filler)
                {
                    invitesContainer.remove(kids[i + 1]);
                }
                break;
            }
        }
        refreshInvitesContainer();
    }

    /** Hides the strip when empty so it doesn't reserve vertical space, AND
     *  applies the rank-range slider gate per-card: cards whose sender is
     *  outside the user's current min/max range are setVisible(false) (with
     *  their trailing strut) so the invite is invisible. The card object
     *  stays in the container so it reappears immediately if the user
     *  widens the slider — no need to rebuild + lose its countdown timer. */
    private void refreshInvitesContainer()
    {
        if (invitesContainer == null) return;
        Component[] kids = invitesContainer.getComponents();
        boolean anyVisible = false;
        for (int i = 0; i < kids.length; i++)
        {
            Component c = kids[i];
            if (c instanceof IncomingInvitePanel)
            {
                IncomingInvitePanel card = (IncomingInvitePanel) c;
                boolean inRange = rankInRange(card.sender);
                card.setVisible(inRange);
                // Hide the trailing strut too so the gap collapses with the card.
                if (i + 1 < kids.length && kids[i + 1] instanceof Box.Filler)
                {
                    kids[i + 1].setVisible(inRange);
                }
                if (inRange) anyVisible = true;
            }
        }
        invitesContainer.setVisible(anyVisible);
        invitesContainer.revalidate();
        invitesContainer.repaint();
    }

    /** Builds the human-readable rank labels (e.g. "Bronze 3", "3rd Age") in
     *  the same index order as {@link RankUtils#THRESHOLDS}. */
    private static String[] buildRankLabels()
    {
        String[] out = new String[RankUtils.THRESHOLDS.length];
        for (int i = 0; i < RankUtils.THRESHOLDS.length; i++)
        {
            String name = RankUtils.THRESHOLDS[i][0];
            String div = RankUtils.THRESHOLDS[i][1];
            out[i] = "0".equals(div) ? name : name + " " + div;
        }
        return out;
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pvp.leaderboard.util.RankUtils;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.text.SimpleDateFormat;
import java.util.Date;

public class MatchHistoryPanel extends JPanel
{
    private JTable matchHistoryTable;
    private DefaultTableModel tableModel;

    public MatchHistoryPanel()
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createTitledBorder("Match History"));

        createTable();
    }

    private void createTable()
    {
        String[] columns = {"Res", "Opponent", "Type", "Match", "Change", "Time"};
        tableModel = new DefaultTableModel(columns, 0);
        matchHistoryTable = new JTable(tableModel);
        matchHistoryTable.setFillsViewportHeight(true);
        matchHistoryTable.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
        try {
            matchHistoryTable.getColumnModel().getColumn(0).setPreferredWidth(40);
            matchHistoryTable.getColumnModel().getColumn(1).setPreferredWidth(140);
            matchHistoryTable.getColumnModel().getColumn(2).setPreferredWidth(60);
            matchHistoryTable.getColumnModel().getColumn(3).setPreferredWidth(220);
            matchHistoryTable.getColumnModel().getColumn(4).setPreferredWidth(180);
            matchHistoryTable.getColumnModel().getColumn(5).setPreferredWidth(160);
        } catch (Exception ignore) {}

        JScrollPane scrollPane = new JScrollPane(matchHistoryTable);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setPreferredSize(new Dimension(0, 300));
        add(scrollPane, BorderLayout.CENTER);
    }

    public void setMatches(JsonArray matches)
    {
        SwingUtilities.invokeLater(() -> {
            tableModel.setRowCount(0);
            if (matches == null) return;

            for (int i = 0; i < matches.size(); i++)
            {
                JsonObject match = matches.get(i).getAsJsonObject();
                String result = match.has("result") ? match.get("result").getAsString() : "";
                String opponent = match.has("opponent_id") ? match.get("opponent_id").getAsString() : "";
                String matchType = match.has("bucket") ? match.get("bucket").getAsString().toUpperCase() : "Unknown";
                String playerRank = computeRank(match, "player_");
                String opponentRank = computeRank(match, "opponent_");
                String matchDisplay = playerRank + " vs " + opponentRank;
                String change = computeRatingChangePlain(match);
                String time = match.has("when") ? formatTime(match.get("when").getAsLong()) : "";

                tableModel.addRow(new Object[]{result, opponent, matchType, matchDisplay, change, time});
            }
        });
    }

    public void clear()
    {
        SwingUtilities.invokeLater(() -> tableModel.setRowCount(0));
    }

    private String computeRank(JsonObject match, String prefix)
    {
        if (match.has(prefix + "rank"))
        {
            String rank = match.get(prefix + "rank").getAsString();
            int division = match.has(prefix + "division") ? match.get(prefix + "division").getAsInt() : 0;
            return rank + (division > 0 ? " " + division : "");
        }
        return "Unknown";
    }

    private String computeRatingChangePlain(JsonObject match)
    {
        if (match.has("rating_change"))
        {
            JsonObject ratingChange = match.getAsJsonObject("rating_change");

            // Prefer actual MMR delta from backend when present
            if (ratingChange.has("mmr_delta"))
            {
                double mmrDelta = ratingChange.get("mmr_delta").getAsDouble();
                String mmrText = String.format("%+.2f MMR", mmrDelta);
                return mmrText; // Simplified for plain text view, or add more details if space allows
            }

            // Fallback to progress calculation logic if needed, or simplified
            // Reuse logic from DashboardPanel if we want exact same output:

            double progressChange = ratingChange.has("progress_change") ? ratingChange.get("progress_change").getAsDouble() : 0;

            // Re-implement simplified delta calculation or just show percentage
            // The original logic was quite complex to handle wrapping.
            // Let's copy the essential part or reuse RankUtils if possible.
            // RankUtils doesn't have "computeRatingChangeText".


            String fromRank = ratingChange.has("from_rank") ? ratingChange.get("from_rank").getAsString() : "";
            String toRank = ratingChange.has("to_rank") ? ratingChange.get("to_rank").getAsString() : "";
            int fromDiv = ratingChange.has("from_division") ? ratingChange.get("from_division").getAsInt() : 0;
            int toDiv = ratingChange.has("to_division") ? ratingChange.get("to_division").getAsInt() : 0;

            double playerMmr = match.has("player_mmr") ? match.get("player_mmr").getAsDouble() : 0;
            double afterProg = RankUtils.calculateProgressFromMMR(playerMmr);
            double beforeProg = afterProg - progressChange;

            String fromKey = fromRank + "|" + fromDiv;
            String toKey = toRank + "|" + toDiv;
            if (!fromKey.equals(toKey) && Math.abs(progressChange) > 0)
            {
                String result = match.has("result") ? match.get("result").getAsString().toLowerCase() : "";
                int signShouldBe = "win".equals(result) ? 1 : ("loss".equals(result) ? -1 : (int)Math.signum(progressChange));
                if (Math.signum(progressChange) != signShouldBe)
                {
                    beforeProg = afterProg + (100 - Math.abs(progressChange)) * signShouldBe;
                }
            }

            beforeProg = Math.max(0, Math.min(100, beforeProg));

            int fromIdx = RankUtils.getRankIndex(fromRank, fromDiv);
            int toIdx = RankUtils.getRankIndex(toRank, toDiv);
            double rawDelta = (afterProg - beforeProg) + (toIdx - fromIdx) * 100;

            String result = match.has("result") ? match.get("result").getAsString().toLowerCase() : "";
            if ("tie".equals(result)) return "0% change";
            return String.format("%+.2f%% change", rawDelta);
        }
        return "-";
    }

    private String formatTime(long timestamp)
    {
        return new SimpleDateFormat("MM/dd/yyyy HH:mm").format(new Date(timestamp * 1000));
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.JsonObject;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.util.RankUtils;

import javax.swing.*;
import java.awt.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

/**
 * "What are the ranks" view: every tier from 3rd Age down to Bronze 3 with
 * a live "Top X%" derived from the infra-side rank histogram
 * ({@code rank_hist/<bucket>.json}, see {@code backend/core/rank_histogram.py}).
 *
 * <p>A bucket toggle ([Overall][NH][Veng][Multi][DMM], NH selected by
 * default) mirrors the Performance Breakdown selector in Player Lookup.
 * Switching buckets re-fetches that bucket's histogram (cached per bucket)
 * and recomputes the per-tier share of the population at or above each
 * tier's MMR cutoff.
 */
public class RankTierPanel extends JPanel implements Scrollable
{
    /** Button label → bucket key (label.toLowerCase()). NH is selected by default. */
    private static final String[] BUCKET_LABELS = {"Overall", "NH", "Veng", "Multi", "DMM"};
    private static final String DEFAULT_BUCKET = "nh";

    private static final Color VALUE_COLOR = new Color(200, 200, 200);
    private static final Color SELECTED_BG = new Color(60, 60, 60);

    private final PvPDataService pvpDataService;

    private JPanel bucketBar;
    /** THRESHOLDS index → that tier's right-hand "Top X%" label. */
    private final Map<Integer, JLabel> valueByThresholdIdx = new HashMap<>();
    /** bucket key → fetched histogram (avoids refetching on toggle). */
    private final Map<String, JsonObject> histogramCache = new ConcurrentHashMap<>();

    private volatile String selectedBucket = DEFAULT_BUCKET;

    /** No-arg constructor kept for callers/tests that don't need live data. */
    public RankTierPanel()
    {
        this(null);
    }

    public RankTierPanel(PvPDataService pvpDataService)
    {
        this.pvpDataService = pvpDataService;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        add(buildBucketBar());
        add(buildTierList());
        styleBucketButtons(selectedBucket);
    }

    /**
     * Trigger (or refresh) the histogram load for the selected bucket.
     * Called by {@link DashboardPanel} when the view is revealed so no
     * network request happens until the user actually opens it. Cached
     * buckets render instantly; a previously-failed fetch is retried.
     */
    public void onShown()
    {
        loadBucket(selectedBucket);
    }

    private JPanel buildBucketBar()
    {
        // Two rows of 3 (Overall/NH/Veng · Multi/DMM) — five labels don't fit
        // on one row in the ~225px sidepanel. Mirrors the Performance
        // Breakdown selector geometry for consistency.
        bucketBar = new JPanel(new GridLayout(2, 3, 2, 2));
        bucketBar.setName("rankTierBucketBar");
        bucketBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
        bucketBar.setAlignmentX(LEFT_ALIGNMENT);

        Font baseFont = UIManager.getFont("Label.font");
        if (baseFont == null) baseFont = new Font("SansSerif", Font.PLAIN, 12);
        Font small = baseFont.deriveFont(Font.PLAIN, Math.max(10f, baseFont.getSize2D() - 1f));

        for (String label : BUCKET_LABELS)
        {
            JButton btn = new JButton(label);
            btn.setName("rankTierBucketBtn");
            btn.setFont(small);
            btn.setMargin(new Insets(2, 2, 2, 2));
            btn.setFocusPainted(false);
            final String bucketKey = label.toLowerCase();
            btn.addActionListener(e -> loadBucket(bucketKey));
            bucketBar.add(btn);
        }
        return bucketBar;
    }

    private JPanel buildTierList()
    {
        JPanel list = new JPanel();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setName("rankTierList");
        list.setAlignmentX(LEFT_ALIGNMENT);

        String[][] thresholds = RankUtils.THRESHOLDS;
        for (int i = thresholds.length - 1; i >= 0; i--)
        {
            String rankName = thresholds[i][0];
            int division = Integer.parseInt(thresholds[i][1]);

            String displayName = "3rd Age".equals(rankName)
                ? "3rd Age"
                : rankName + " " + division;

            JPanel row = new JPanel(new BorderLayout(6, 0));
            row.setName("tierRow");
            row.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
            row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
            row.setAlignmentX(LEFT_ALIGNMENT);

            JLabel nameLabel = new JLabel(displayName);
            nameLabel.setName("tierName");
            nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 12f));
            nameLabel.setForeground("3rd Age".equals(rankName) ? Color.WHITE : RankUtils.getRankColor(rankName));
            row.add(nameLabel, BorderLayout.WEST);

            // Right-aligned in CENTER (not EAST) so the value uses all the
            // space left of the inner edge: every row's value ends flush at
            // the same right margin (an "equalized" column) and a long
            // "No one currently here" stays fully visible.
            JLabel valueLabel = new JLabel("\u2014");
            valueLabel.setName("tierValue");
            valueLabel.setFont(valueLabel.getFont().deriveFont(Font.PLAIN, 11f));
            valueLabel.setForeground(VALUE_COLOR);
            valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
            row.add(valueLabel, BorderLayout.CENTER);

            valueByThresholdIdx.put(i, valueLabel);
            list.add(row);
        }
        return list;
    }

    private void loadBucket(String bucket)
    {
        final String bucketKey = (bucket == null || bucket.trim().isEmpty())
            ? DEFAULT_BUCKET
            : bucket.trim().toLowerCase();
        selectedBucket = bucketKey;
        styleBucketButtons(bucketKey);

        JsonObject cached = histogramCache.get(bucketKey);
        if (cached != null)
        {
            applyHistogram(cached);
            return;
        }

        if (pvpDataService == null)
        {
            setAllValues("Unavailable");
            return;
        }

        setAllValues("\u2026"); // ellipsis = loading
        CompletableFuture<JsonObject> future = pvpDataService.getRankHistogram(bucketKey);
        if (future == null)
        {
            setAllValues("Unavailable");
            return;
        }
        future.thenAccept(hist -> SwingUtilities.invokeLater(() ->
        {
            if (hist != null && hist.has("bins"))
            {
                histogramCache.put(bucketKey, hist);
                if (bucketKey.equals(selectedBucket)) applyHistogram(hist);
            }
            else if (bucketKey.equals(selectedBucket))
            {
                setAllValues("Unavailable");
            }
        })).exceptionally(ex ->
        {
            SwingUtilities.invokeLater(() ->
            {
                if (bucketKey.equals(selectedBucket)) setAllValues("Unavailable");
            });
            return null;
        });
    }

    private void applyHistogram(JsonObject hist)
    {
        long total = RankUtils.histogramTotal(hist);
        for (Map.Entry<Integer, JLabel> e : valueByThresholdIdx.entrySet())
        {
            double cutoff = Double.parseDouble(RankUtils.THRESHOLDS[e.getKey()][2]);
            long atOrAbove = RankUtils.cumulativeCountAtOrAbove(hist, cutoff);
            e.getValue().setText(RankUtils.formatTopPercent(atOrAbove, total));
        }
    }

    private void setAllValues(String text)
    {
        for (JLabel label : valueByThresholdIdx.values())
        {
            label.setText(text);
        }
    }

    // --- Scrollable: track the viewport WIDTH so rows never overflow
    // horizontally (the right-aligned value column stays flush at the inner
    // edge), while still allowing vertical scrolling for the 25 tiers. ---

    @Override
    public Dimension getPreferredScrollableViewportSize()
    {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
    {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
    {
        return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
    }

    @Override
    public boolean getScrollableTracksViewportWidth()
    {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight()
    {
        return false;
    }

    private void styleBucketButtons(String activeBucket)
    {
        if (bucketBar == null) return;
        for (Component c : bucketBar.getComponents())
        {
            if (!(c instanceof JButton)) continue;
            JButton btn = (JButton) c;
            boolean selected = btn.getText().equalsIgnoreCase(activeBucket);
            if (selected)
            {
                btn.setForeground(Color.WHITE);
                btn.setBackground(SELECTED_BG);
            }
            else
            {
                btn.setForeground(Color.GRAY);
                btn.setBackground(UIManager.getColor("Button.background"));
            }
        }
    }
}

package com.pvp.leaderboard.ui;

import javax.swing.*;
import javax.swing.event.ChangeEvent;
import javax.swing.event.ChangeListener;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.util.ArrayList;
import java.util.List;

/**
 * Single-track double-handled range slider. Drop-in replacement for two
 * {@link JSlider}s where you want a min and a max bound on the same scale.
 *
 * <p>Why a custom widget instead of {@link JSlider} × 2:
 * <ul>
 *   <li>Two stacked sliders take ~2× the vertical real estate of one
 *       range slider — the lobby panel is height-starved (community box +
 *       nav + filters + roster + chat all share ~700px).</li>
 *   <li>{@link JSlider} reserves a "thumb-radius" inset on each side of
 *       its track which makes the track visually offset from the panel's
 *       left edge — that was the source of the "left-side gap" the user
 *       called out. This widget paints the track edge-to-edge.</li>
 *   <li>The Substance L&F draws JSlider in a way that ignores opacity
 *       overrides, making it impossible to colour-match the lobby palette.</li>
 * </ul>
 *
 * <p>Values are integers in {@code [min, max]} (inclusive); high &ge; low is
 * always enforced. {@link ChangeListener}s fire on every drag tick so
 * callers should defer expensive work until {@link #getValueIsAdjusting()}
 * returns {@code false}.
 */
public class RangeSlider extends JComponent
{
    /** Track thickness in pixels. */
    private static final int TRACK_HEIGHT = 6;
    /** Thumb diameter — also dictates the left/right margin reserved so the
     *  thumbs can sit half-off the track at the extremes. */
    private static final int THUMB_SIZE = 14;
    /** Reserve room above + below the track so the thumbs aren't clipped. */
    private static final int PREFERRED_HEIGHT = 24;

    private static final Color TRACK_COLOR = new Color(0x40, 0x40, 0x40);
    private static final Color RANGE_COLOR = new Color(0xff, 0x6b, 0x00);
    private static final Color THUMB_COLOR = new Color(0xee, 0xee, 0xee);
    private static final Color THUMB_BORDER = new Color(0x22, 0x22, 0x22);

    private final int min;
    private final int max;
    private int low;
    private int high;
    /** {@code 0} = low handle, {@code 1} = high handle, {@code -1} = no drag. */
    private int draggingHandle = -1;
    private boolean adjusting;
    private final List<ChangeListener> listeners = new ArrayList<>();

    public RangeSlider(int min, int max, int low, int high)
    {
        if (max <= min) throw new IllegalArgumentException("max must be > min");
        this.min = min;
        this.max = max;
        this.low = clamp(low, min, max);
        this.high = clamp(high, this.low, max);
        setOpaque(false);
        setPreferredSize(new Dimension(120, PREFERRED_HEIGHT));
        setMinimumSize(new Dimension(60, PREFERRED_HEIGHT));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, PREFERRED_HEIGHT));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        installMouseHandlers();
    }

    public int getLow()  { return low; }
    public int getHigh() { return high; }
    public boolean getValueIsAdjusting() { return adjusting; }

    public void setLow(int v)
    {
        int nv = clamp(v, min, high);
        if (nv == low) return;
        low = nv;
        fireChange();
        repaint();
    }

    public void setHigh(int v)
    {
        int nv = clamp(v, low, max);
        if (nv == high) return;
        high = nv;
        fireChange();
        repaint();
    }

    public void addChangeListener(ChangeListener l)
    {
        if (l != null) listeners.add(l);
    }

    private void fireChange()
    {
        ChangeEvent ev = new ChangeEvent(this);
        for (ChangeListener l : listeners) l.stateChanged(ev);
    }

    // -------------------- Mouse handling --------------------

    private void installMouseHandlers()
    {
        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                draggingHandle = pickHandleAt(e.getX());
                adjusting = true;
                dragTo(e.getX());
            }

            @Override
            public void mouseReleased(MouseEvent e)
            {
                draggingHandle = -1;
                adjusting = false;
                fireChange();
            }
        });
        addMouseMotionListener(new MouseMotionAdapter()
        {
            @Override
            public void mouseDragged(MouseEvent e)
            {
                if (draggingHandle < 0) return;
                dragTo(e.getX());
            }
        });
    }

    /** Picks the handle nearest the click x. If the click lands inside the
     *  active range we pick the closer of low/high; outside the range we pick
     *  whichever handle the click is nearer to. */
    private int pickHandleAt(int xPx)
    {
        int xLow = valueToX(low);
        int xHigh = valueToX(high);
        return Math.abs(xPx - xLow) <= Math.abs(xPx - xHigh) ? 0 : 1;
    }

    private void dragTo(int xPx)
    {
        int v = xToValue(xPx);
        if (draggingHandle == 0)
        {
            int nv = Math.min(v, high);
            if (nv != low) { low = nv; fireChange(); repaint(); }
        }
        else if (draggingHandle == 1)
        {
            int nv = Math.max(v, low);
            if (nv != high) { high = nv; fireChange(); repaint(); }
        }
    }

    // -------------------- Geometry --------------------

    /** Effective track region. Reserves THUMB_SIZE/2 on each side so a thumb
     *  centered on the extreme value sits flush with the panel edge. */
    private int trackLeft() { return THUMB_SIZE / 2; }
    private int trackRight() { return getWidth() - THUMB_SIZE / 2; }
    private int trackWidth() { return Math.max(1, trackRight() - trackLeft()); }

    private int valueToX(int v)
    {
        double t = (double) (v - min) / (max - min);
        return trackLeft() + (int) Math.round(t * trackWidth());
    }

    private int xToValue(int x)
    {
        double t = (double) (x - trackLeft()) / trackWidth();
        t = Math.max(0.0, Math.min(1.0, t));
        return min + (int) Math.round(t * (max - min));
    }

    private static int clamp(int v, int lo, int hi)
    {
        return Math.max(lo, Math.min(hi, v));
    }

    // -------------------- Painting --------------------

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int trackY = getHeight() / 2 - TRACK_HEIGHT / 2;
            int xL = trackLeft();
            int w = trackWidth();

            g2.setColor(TRACK_COLOR);
            g2.fillRoundRect(xL, trackY, w, TRACK_HEIGHT, 4, 4);

            int xLow = valueToX(low);
            int xHigh = valueToX(high);
            g2.setColor(RANGE_COLOR);
            g2.fillRoundRect(xLow, trackY, Math.max(1, xHigh - xLow), TRACK_HEIGHT, 4, 4);

            paintThumb(g2, xLow);
            paintThumb(g2, xHigh);
        }
        finally
        {
            g2.dispose();
        }
    }

    private void paintThumb(Graphics2D g2, int xCenter)
    {
        int yCenter = getHeight() / 2;
        int r = THUMB_SIZE / 2;
        g2.setColor(THUMB_COLOR);
        g2.fillOval(xCenter - r, yCenter - r, THUMB_SIZE, THUMB_SIZE);
        g2.setColor(THUMB_BORDER);
        g2.setStroke(new BasicStroke(1f));
        g2.drawOval(xCenter - r, yCenter - r, THUMB_SIZE - 1, THUMB_SIZE - 1);
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.util.RankUtils;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.awt.*;
import java.text.SimpleDateFormat;
import java.time.LocalDate;
import java.util.*;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

@Slf4j
public class AdditionalStatsPanel extends JPanel {
    private final JLabel highestRankLabel = new JLabel("-");
    private final JLabel highestTimeLabel = new JLabel("-");
    private final JLabel lowestRankLabel = new JLabel("-");
    private final JLabel lowestTimeLabel = new JLabel("-");

    private final SimpleDateFormat fmt = new SimpleDateFormat("M/d/yyyy, h:mm:ss a");
    private String selectedBucket = "overall";
    private JsonArray matches = new JsonArray();

    private PvPDataService pvpDataService;
    private String playerName;
    private String acctSha;

    private static final int MAX_UNIQUE_PLAYERS_PER_DAY = 3;
    private static final int INCREMENTAL_PAGE_SIZE = 15;
    private static final int MAX_INCREMENTAL_MATCHES = 200;
    private static final long MAX_LOOKBACK_MS = 24L * 60 * 60 * 1000;

    private final Map<String, CachedMatches> matchCache = new HashMap<>();

    private final Set<String> dailyNewLookups = new HashSet<>();
    private LocalDate dailyLookupDate = LocalDate.now();

    private static class CachedMatches {
        final JsonArray matches;
        final long cachedAtMs;
        final double newestMatchWhen;

        CachedMatches(JsonArray matches, long cachedAtMs) {
            this.matches = matches;
            this.cachedAtMs = cachedAtMs;
            double max = 0;
            for (int i = 0; i < matches.size(); i++) {
                JsonObject m = matches.get(i).getAsJsonObject();
                if (m.has("when") && !m.get("when").isJsonNull()) {
                    max = Math.max(max, m.get("when").getAsDouble());
                }
            }
            this.newestMatchWhen = max;
        }
    }

    private final JButton tierGraphBtn;
    private final JLabel tierGraphInfo;

    public AdditionalStatsPanel() {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createTitledBorder("Additional Stats"));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

        JPanel statsCol = new JPanel();
        statsCol.setLayout(new BoxLayout(statsCol, BoxLayout.Y_AXIS));
        statsCol.setAlignmentX(LEFT_ALIGNMENT);
        statsCol.add(makeStat("Highest Rank Defeated", highestRankLabel, highestTimeLabel));
        statsCol.add(Box.createVerticalStrut(6));
        statsCol.add(makeStat("Lowest Rank Lost To", lowestRankLabel, lowestTimeLabel));
        content.add(statsCol);
        content.add(Box.createVerticalStrut(8));

        tierGraphBtn = new JButton(getTierGraphButtonText());
        tierGraphBtn.setAlignmentX(LEFT_ALIGNMENT);
        tierGraphBtn.addActionListener(e -> onTierGraphClicked());
        content.add(tierGraphBtn);
        content.add(Box.createVerticalStrut(4));

        tierGraphInfo = new JLabel(
                "<html>Free tier allows 3 unique player searches per day due to "
                + "backend cost, reach out to Toyco on discord to get more access</html>");
        tierGraphInfo.setForeground(Color.GRAY);
        tierGraphInfo.setFont(tierGraphInfo.getFont().deriveFont(Font.PLAIN, 14f));
        tierGraphInfo.setAlignmentX(LEFT_ALIGNMENT);
        content.add(tierGraphInfo);

        add(content, BorderLayout.NORTH);
    }

    /**
     * Clamp the maximum height to the preferred height. The content is pinned
     * to {@link BorderLayout#NORTH}, and {@code BorderLayout} (a
     * {@code LayoutManager2}) otherwise reports an unbounded maximum height.
     * When this panel sits in the dashboard's vertical {@code BoxLayout}, that
     * unbounded maximum makes {@code BoxLayout} hand it all of the leftover
     * vertical slack — stretching the "Additional Stats" box far below its
     * content and leaving a large empty gap (most visible right after login,
     * when the rank/advanced sections below are short). Capping the height
     * keeps the box exactly as tall as its content; width stays flexible so it
     * still fills the panel.
     */
    @Override
    public Dimension getMaximumSize() {
        Dimension max = super.getMaximumSize();
        Dimension pref = getPreferredSize();
        return new Dimension(max.width, pref.height);
    }

    public void setPvPDataService(PvPDataService service) {
        this.pvpDataService = service;
    }

    public void setPlayerName(String name) {
        this.playerName = name;
    }

    public void setAcctSha(String sha) {
        this.acctSha = sha;
    }

    public void setMatches(JsonArray newMatches) {
        this.matches = (newMatches != null) ? newMatches : new JsonArray();
        updateAdditionalStats();
    }

    public void setBucket(String bucket) {
        this.selectedBucket = (bucket == null ? "overall" : bucket.toLowerCase(Locale.ROOT));
    }

    private String getTierGraphButtonText() {
        resetDayIfNeeded();
        int used = dailyNewLookups.size();
        int remaining = MAX_UNIQUE_PLAYERS_PER_DAY - used;
        return "Tier Graph " + remaining + "/" + MAX_UNIQUE_PLAYERS_PER_DAY + " remaining";
    }

    private void resetDayIfNeeded() {
        LocalDate today = LocalDate.now();
        if (!today.equals(dailyLookupDate)) {
            dailyLookupDate = today;
            dailyNewLookups.clear();
        }
    }

    private void onTierGraphClicked() {
        resetDayIfNeeded();
        if (pvpDataService == null || playerName == null || playerName.isEmpty()) {
            JOptionPane.showMessageDialog(this,
                    "No player loaded. Please search for a player first.",
                    "No Player", JOptionPane.INFORMATION_MESSAGE);
            return;
        }
        String key = playerName.toLowerCase(Locale.ROOT);
        boolean alreadyCached = matchCache.containsKey(key);
        if (!alreadyCached && dailyNewLookups.size() >= MAX_UNIQUE_PLAYERS_PER_DAY
                && !dailyNewLookups.contains(key)) {
            JOptionPane.showMessageDialog(this,
                    "You have used all 3 unique new player tier graph lookups for today.\n"
                    + "Previously cached players can still be reopened.\n"
                    + "This limit resets daily.",
                    "Daily Limit Reached", JOptionPane.WARNING_MESSAGE);
            return;
        }

        showTierGraphDialog(key, alreadyCached);
    }

    private void showTierGraphDialog(String cacheKey, boolean alreadyCached) {
        Window owner = SwingUtilities.getWindowAncestor(this);
        JDialog dialog = new JDialog(owner, "Tier Graph Over Time - " + playerName, Dialog.ModalityType.MODELESS);
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.setSize(700, 500);
        dialog.setLocationRelativeTo(owner);

        JPanel mainPanel = new JPanel(new BorderLayout(0, 4));

        String[] bucketKeys = {"overall", "nh", "veng", "multi", "dmm"};
        String[] bucketLabels = {"Overall", "NH", "Veng", "Multi", "DMM"};
        JPanel bucketBar = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        JButton[] bucketBtns = new JButton[bucketKeys.length];
        TierGraphLabelsPanel labelsPanel = new TierGraphLabelsPanel();
        TierGraphPlotPanel plotPanel = new TierGraphPlotPanel();
        JLabel statusLabel = new JLabel("Loading all matches...");
        statusLabel.setHorizontalAlignment(SwingConstants.CENTER);

        final String[] dialogBucket = { selectedBucket };
        final JsonArray[] dialogMatches = { new JsonArray() };

        for (int i = 0; i < bucketKeys.length; i++) {
            final String key = bucketKeys[i];
            bucketBtns[i] = new JButton(bucketLabels[i]);
            bucketBtns[i].setEnabled(alreadyCached);
            bucketBtns[i].addActionListener(e -> {
                dialogBucket[0] = key;
                updateBucketBtnStyles(bucketBtns, bucketKeys, key);
                rebuildDialogSeries(dialogMatches[0], key, labelsPanel, plotPanel);
            });
            bucketBar.add(bucketBtns[i]);
        }
        updateBucketBtnStyles(bucketBtns, bucketKeys, dialogBucket[0]);

        mainPanel.add(bucketBar, BorderLayout.NORTH);

        JPanel graphPanel = new JPanel(new BorderLayout());
        labelsPanel.setPreferredSize(new Dimension(80, 400));
        plotPanel.setPreferredSize(new Dimension(580, 400));
        graphPanel.add(labelsPanel, BorderLayout.WEST);
        graphPanel.add(plotPanel, BorderLayout.CENTER);

        JPanel centerWrapper = new JPanel(new CardLayout());
        centerWrapper.add(statusLabel, "loading");
        centerWrapper.add(graphPanel, "graph");

        mainPanel.add(centerWrapper, BorderLayout.CENTER);
        dialog.add(mainPanel);
        dialog.setVisible(true);

        Runnable showGraph = () -> SwingUtilities.invokeLater(() -> {
            JsonArray current = matchCache.containsKey(cacheKey)
                    ? matchCache.get(cacheKey).matches : new JsonArray();
            dialogMatches[0] = current;
            for (JButton btn : bucketBtns) btn.setEnabled(true);
            rebuildDialogSeries(current, dialogBucket[0], labelsPanel, plotPanel);
            ((CardLayout) centerWrapper.getLayout()).show(centerWrapper, "graph");
            tierGraphBtn.setText(getTierGraphButtonText());
        });

        if (alreadyCached) {
            statusLabel.setText("Updating with latest matches...");
            ((CardLayout) centerWrapper.getLayout()).show(centerWrapper, "loading");
            CachedMatches cached = matchCache.get(cacheKey);
            long now = System.currentTimeMillis();
            double cutoffSec = Math.max(cached.cachedAtMs / 1000.0, (now - MAX_LOOKBACK_MS) / 1000.0);
            log.debug("[TierGraph] Incremental refresh for '{}': cachedMatches={}, newestWhen={}, cutoffSec={}, cacheAge={}s",
                    cacheKey, cached.matches.size(), cached.newestMatchWhen, cutoffSec,
                    (now - cached.cachedAtMs) / 1000);
            JsonArray newMatches = new JsonArray();
            fetchIncrementalPage(null, newMatches, cached.newestMatchWhen, cutoffSec, 0, () -> {
                log.debug("[TierGraph] Incremental done: {} new matches fetched", newMatches.size());
                JsonArray merged = new JsonArray();
                for (int i = 0; i < newMatches.size(); i++) merged.add(newMatches.get(i));
                for (int i = 0; i < cached.matches.size(); i++) merged.add(cached.matches.get(i));
                log.debug("[TierGraph] Merged total: {} matches", merged.size());
                matchCache.put(cacheKey, new CachedMatches(merged, System.currentTimeMillis()));
                showGraph.run();
            });
        } else {
            ((CardLayout) centerWrapper.getLayout()).show(centerWrapper, "loading");
            log.debug("[TierGraph] Full fetch for '{}', acctSha={}", playerName, acctSha != null);
            CompletableFuture<JsonArray> fetchFuture;
            if (acctSha != null && !acctSha.isEmpty()) {
                fetchFuture = pvpDataService.getAllPlayerMatchesByAcct(acctSha);
            } else {
                fetchFuture = pvpDataService.getAllPlayerMatches(playerName);
            }
            fetchFuture.thenAccept(allMatches -> {
                log.debug("[TierGraph] Full fetch complete: {} total matches for '{}'", allMatches.size(), playerName);
                matchCache.put(cacheKey, new CachedMatches(allMatches, System.currentTimeMillis()));
                dailyNewLookups.add(cacheKey);
                showGraph.run();
            }).exceptionally(ex -> {
                log.warn("Failed to fetch all matches for tier graph", ex);
                SwingUtilities.invokeLater(() -> {
                    statusLabel.setText("Failed to load matches.");
                    for (JButton btn : bucketBtns) btn.setEnabled(true);
                });
                return null;
            });
        }
    }

    private void fetchIncrementalPage(String nextToken, JsonArray accumulator,
                                      double newestCachedWhen, double cutoffSec,
                                      int totalFetched, Runnable onDone) {
        if (totalFetched >= MAX_INCREMENTAL_MATCHES) {
            log.debug("[TierGraph] Incremental: hit max {} matches, stopping", MAX_INCREMENTAL_MATCHES);
            onDone.run();
            return;
        }
        log.debug("[TierGraph] Incremental: fetching page (totalSoFar={}, nextToken={}, acct={})",
                totalFetched, nextToken != null, acctSha != null);
        CompletableFuture<JsonObject> pageFuture;
        if (acctSha != null && !acctSha.isEmpty()) {
            pageFuture = pvpDataService.getPlayerMatchesByAcct(acctSha, nextToken, INCREMENTAL_PAGE_SIZE, true);
        } else {
            pageFuture = pvpDataService.getPlayerMatches(playerName, nextToken, INCREMENTAL_PAGE_SIZE, true);
        }
        pageFuture
                .thenAccept(response -> {
                    if (response == null || !response.has("matches")
                            || !response.get("matches").isJsonArray()) {
                        log.debug("[TierGraph] Incremental: null/empty response, stopping");
                        onDone.run();
                        return;
                    }
                    JsonArray page = response.getAsJsonArray("matches");
                    log.debug("[TierGraph] Incremental: page returned {} matches", page.size());
                    if (page.size() == 0) {
                        onDone.run();
                        return;
                    }
                    boolean caughtUp = false;
                    int added = 0;
                    for (int i = 0; i < page.size(); i++) {
                        JsonObject m = page.get(i).getAsJsonObject();
                        double when = m.has("when") && !m.get("when").isJsonNull()
                                ? m.get("when").getAsDouble() : 0;
                        if (when <= newestCachedWhen) {
                            log.debug("[TierGraph] Incremental: match when={} <= newestCached={}, caught up", when, newestCachedWhen);
                            caughtUp = true;
                            break;
                        }
                        if (when < cutoffSec) {
                            log.debug("[TierGraph] Incremental: match when={} < cutoff={}, stopping", when, cutoffSec);
                            caughtUp = true;
                            break;
                        }
                        accumulator.add(m);
                        added++;
                        if (totalFetched + added >= MAX_INCREMENTAL_MATCHES) {
                            caughtUp = true;
                            break;
                        }
                    }
                    if (caughtUp) {
                        log.debug("[TierGraph] Incremental: caught up after adding {} this page", added);
                        onDone.run();
                        return;
                    }
                    String next = response.has("next_token") && !response.get("next_token").isJsonNull()
                            ? response.get("next_token").getAsString() : null;
                    if (next != null && !next.isEmpty()) {
                        fetchIncrementalPage(next, accumulator, newestCachedWhen, cutoffSec,
                                totalFetched + added, onDone);
                    } else {
                        log.debug("[TierGraph] Incremental: no more pages, done with {} added", added);
                        onDone.run();
                    }
                }).exceptionally(ex -> {
                    log.warn("Incremental match fetch failed", ex);
                    onDone.run();
                    return null;
                });
    }

    private void updateBucketBtnStyles(JButton[] btns, String[] keys, String selected) {
        Color selBg = new Color(60, 60, 60);
        Color selFg = Color.WHITE;
        Color unselFg = Color.GRAY;
        for (int i = 0; i < btns.length; i++) {
            if (keys[i].equals(selected)) {
                btns[i].setBackground(selBg);
                btns[i].setForeground(selFg);
            } else {
                btns[i].setBackground(null);
                btns[i].setForeground(unselFg);
            }
        }
    }

    private void rebuildDialogSeries(JsonArray allMatches, String bucket,
                                     TierGraphLabelsPanel labelsPanel, TierGraphPlotPanel plotPanel) {
        log.debug("[TierGraph] rebuildDialogSeries: totalMatches={}, bucket='{}'", allMatches.size(), bucket);
        List<JsonObject> items = new ArrayList<>();
        for (int i = 0; i < allMatches.size(); i++) items.add(allMatches.get(i).getAsJsonObject());
        items = items.stream()
                .filter(m -> bucket.equals("overall") || bucket.equalsIgnoreCase(asStr(m, "bucket")))
                .sorted(Comparator.comparingDouble(m -> m.has("when") ? m.get("when").getAsDouble() : 0))
                .collect(Collectors.toList());
        log.debug("[TierGraph] After filter/sort for '{}': {} matches with MMR data", bucket, items.size());

        final int MAX_MMR_DELTA_PER_MATCH = 250;
        List<Double> rawY = new ArrayList<>();

        if ("overall".equals(bucket)) {
            final Map<String, Double> weights = new LinkedHashMap<>();
            weights.put("nh", 0.55); weights.put("veng", 0.30); weights.put("multi", 0.05); weights.put("dmm", 0.10);
            final Map<String, Double> last = new HashMap<>();
            weights.keySet().forEach(k -> last.put(k, 1000.0));

            for (JsonObject m : items) {
                String b = asStr(m, "bucket").toLowerCase(Locale.ROOT);
                if (weights.containsKey(b)) {
                    Double prev = last.get(b);
                    double mu = resolveMuFromMatch(m, prev);
                    if (Double.isFinite(mu)) {
                        if (!Double.isFinite(prev) || Math.abs(mu - prev) <= MAX_MMR_DELTA_PER_MATCH) {
                            last.put(b, mu);
                        }
                    }
                }
                double overallMu = 0.0;
                for (Map.Entry<String, Double> e : weights.entrySet()) {
                    overallMu += last.getOrDefault(e.getKey(), 1000.0) * e.getValue();
                }
                rawY.add(RankUtils.calculateContinuousTierValue(overallMu));
            }
        } else {
            Double prevMu = null;
            for (JsonObject m : items) {
                double mu = resolveMuFromMatch(m, prevMu);
                double chosen;
                if (Double.isFinite(mu)) {
                    if (prevMu != null && Double.isFinite(prevMu) && Math.abs(mu - prevMu) > MAX_MMR_DELTA_PER_MATCH) {
                        chosen = prevMu;
                    } else {
                        chosen = mu;
                        prevMu = mu;
                    }
                } else {
                    chosen = (prevMu != null) ? prevMu : 1000.0;
                }
                rawY.add(RankUtils.calculateContinuousTierValue(chosen));
            }
        }

        double minY = 24.0, maxYv = 0.0;
        for (Double yv : rawY) {
            if (yv != null && Double.isFinite(yv)) {
                minY = Math.min(minY, yv);
                maxYv = Math.max(maxYv, yv);
            }
        }
        if (!Double.isFinite(minY)) minY = 0.0;
        if (!Double.isFinite(maxYv)) maxYv = 24.0;
        double low = Math.max(0, (int) Math.floor(minY / 3.0) * 3);
        double high = Math.min(24, (int) Math.ceil(maxYv / 3.0) * 3);
        if (high <= low) high = Math.min(24, low + 3);

        labelsPanel.setVisibleRange(low, high);
        plotPanel.setVisibleRange(low, high);

        List<Double> series = new ArrayList<>();
        double span = Math.max(1e-6, high - low);
        for (Double yv : rawY) {
            double y = (yv != null && Double.isFinite(yv)) ? yv : low;
            series.add(Math.max(0.0, Math.min(100.0, ((y - low) / span) * 100.0)));
        }
        plotPanel.setSeries(series);
        log.debug("[TierGraph] Series built: {} data points, range [{}, {}]", series.size(), low, high);
        labelsPanel.repaint();
    }

    private JPanel makeStat(String title, JLabel value, JLabel time) {
        JPanel p = new JPanel();
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        JLabel t = new JLabel(title);
        t.setFont(t.getFont().deriveFont(Font.BOLD, 16f));
        value.setFont(value.getFont().deriveFont(Font.BOLD, 18f));
        time.setForeground(new Color(230, 200, 80));
        p.add(t);
        p.add(Box.createVerticalStrut(4));
        p.add(value);
        p.add(time);
        return p;
    }

    private void updateAdditionalStats() {
        String bestRank = null; Long bestTs = null;
        String worstRank = null; Long worstTs = null;

        for (int i = 0; i < matches.size(); i++) {
            JsonObject m = matches.get(i).getAsJsonObject();
            String bucket = asStr(m, "bucket").toLowerCase(Locale.ROOT);
            if (!selectedBucket.equals("overall") && !bucket.equals(selectedBucket)) continue;

            String result = asStr(m, "result").toLowerCase(Locale.ROOT);
            long ts = m.has("when") ? (long) Math.floor(m.get("when").getAsDouble()) : 0;

            String oppRank = rankLabel(asStr(m, "opponent_rank"), asInt(m, "opponent_division"));
            if (oppRank.isEmpty()) continue;

            if ("win".equals(result)) {
                if (bestRank == null || RankUtils.getRankOrder(oppRank) > RankUtils.getRankOrder(bestRank)) {
                    bestRank = oppRank; bestTs = ts;
                }
            } else if ("loss".equals(result)) {
                if (worstRank == null || RankUtils.getRankOrder(oppRank) < RankUtils.getRankOrder(worstRank)) {
                    worstRank = oppRank; worstTs = ts;
                }
            }
        }

        highestRankLabel.setText(bestRank != null ? bestRank : "-");
        highestTimeLabel.setText(bestTs != null ? fmt.format(new Date(bestTs * 1000)) : "-");
        lowestRankLabel.setText(worstRank != null ? worstRank : "-");
        lowestTimeLabel.setText(worstTs != null ? fmt.format(new Date(worstTs * 1000)) : "-");
    }

    private static double resolveMuFromMatch(JsonObject m, Double prevMu) {
        try {
            if (m.has("player_mmr_after") && !m.get("player_mmr_after").isJsonNull()) {
                return m.get("player_mmr_after").getAsDouble();
            }
            if (m.has("player_new_mmr") && !m.get("player_new_mmr").isJsonNull()) {
                return m.get("player_new_mmr").getAsDouble();
            }
            if (m.has("player_mmr") && !m.get("player_mmr").isJsonNull()) {
                return m.get("player_mmr").getAsDouble();
            }
            if (m.has("rating_change") && m.get("rating_change").isJsonObject()) {
                JsonObject rc = m.getAsJsonObject("rating_change");
                if (rc.has("mmr_delta") && !rc.get("mmr_delta").isJsonNull() && prevMu != null) {
                    return prevMu + rc.get("mmr_delta").getAsDouble();
                }
            }
        } catch (Exception ignore) {}
        return Double.NaN;
    }

    private static String asStr(JsonObject o, String k) {
        return (o.has(k) && !o.get(k).isJsonNull()) ? o.get(k).getAsString() : "";
    }

    private static int asInt(JsonObject o, String k) {
        try { return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsInt() : 0; } catch (Exception e) { return 0; }
    }

    private static String rankLabel(String rank, int division) {
        if (rank == null || rank.isEmpty()) return "";
        return division > 0 ? (rank + " " + division) : rank;
    }

    static class TierGraphLabelsPanel extends JPanel {
        double vMin = 0.0, vMax = 24.0;
        void setVisibleRange(double a, double b) { this.vMin = a; this.vMax = b; repaint(); }
        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g;
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth(), h = getHeight();
            int top = 20, bottom = 20;
            int innerH = Math.max(1, h - top - bottom);
            int start = (int) Math.floor(vMin);
            int end = (int) Math.ceil(vMax);
            for (int gi = start; gi <= end; gi++) {
                double frac = (gi - vMin) / Math.max(1e-6, (vMax - vMin));
                int y = top + innerH - (int) Math.round(frac * innerH);
                g2.setColor(new Color(120, 120, 120));
                g2.drawLine(0, y, w, y);
                int base = gi / 3;
                int off = gi % 3;
                String baseRank = RankUtils.THRESHOLDS[Math.min(base * 3, RankUtils.THRESHOLDS.length - 1)][0];
                if (off == 0) {
                    String label = baseRank.equals("3rd Age") ? baseRank : baseRank + " 3";
                    g2.setColor(RankUtils.getRankColor(baseRank));
                    g2.drawString(label, 2, y + 5);
                }
            }
        }
    }

    static class TierGraphPlotPanel extends JPanel {
        double vMin = 0.0, vMax = 24.0;
        void setVisibleRange(double a, double b) { this.vMin = a; this.vMax = b; repaint(); }
        List<Double> series = new ArrayList<>();
        void setSeries(List<Double> s) { this.series = (s != null) ? s : new ArrayList<>(); repaint(); }
        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g;
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth(), h = getHeight();
            int left = 0, bottom = 20, top = 20, right = 20;
            int innerW = Math.max(1, w - left - right);
            int innerH = Math.max(1, h - top - bottom);

            g2.setColor(new Color(120, 120, 120));
            int start = (int) Math.floor(vMin);
            int end = (int) Math.ceil(vMax);
            for (int gi = start; gi <= end; gi++) {
                if (gi % 3 != 0) continue;
                double frac = (gi - vMin) / Math.max(1e-6, (vMax - vMin));
                int y = top + innerH - (int) Math.round(frac * innerH);
                g2.drawLine(left, y, left + innerW, y);
            }

            if (series.size() > 1) {
                g2.setColor(Color.WHITE);
                g2.setStroke(new BasicStroke(2f));
                for (int i = 0; i < series.size() - 1; i++) {
                    int x1 = left + (i * innerW / Math.max(1, series.size() - 1));
                    int x2 = left + ((i + 1) * innerW / Math.max(1, series.size() - 1));
                    int y1 = top + innerH - (int) Math.round((series.get(i) / 100.0) * innerH);
                    int y2 = top + innerH - (int) Math.round((series.get(i + 1) / 100.0) * innerH);
                    g2.drawLine(x1, y1, x2, y2);
                }
            } else {
                g2.setColor(Color.GRAY);
                g2.drawString("No tier data available", w / 2 - 60, h / 2);
            }
        }
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.PvPLeaderboardConstants;
import com.pvp.leaderboard.service.DiscordAuthService;
import javax.swing.*;
import java.awt.*;
import java.net.URLEncoder;
import java.util.function.Consumer;
import net.runelite.client.util.LinkBrowser;

public class LoginPanel extends JPanel
{
    private static final int MAX_PLUGIN_SEARCHES_PER_MINUTE = 10;

    /** Discord brand "blurple" (#5865F2) — matches flipping-copilot's button. */
    private static final Color DISCORD_BLURPLE = new Color(88, 101, 242);

    private final DiscordAuthService discordAuthService;
    private final Consumer<String> onPluginSearch;
    private final Runnable onLoginStateChanged;

    private JTextField searchField;
    private JButton pluginSearchBtn;
    private JButton loginButton;

    private boolean loginInProgress = false;
    private boolean isLoggedIn = false;

    // Rate limiting for plugin search (10 per minute)
    private final java.util.Deque<Long> pluginSearchTimestamps = new java.util.ArrayDeque<>();

    public LoginPanel(DiscordAuthService discordAuthService, Consumer<String> onPluginSearch, Runnable onLoginStateChanged)
    {
        this.discordAuthService = discordAuthService;
        this.onPluginSearch = onPluginSearch;
        this.onLoginStateChanged = onLoginStateChanged;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
        setMaximumSize(new Dimension(220, 85));
        setPreferredSize(new Dimension(220, 85));

        initUI();
    }

    private static final String PLACEHOLDER = "Player to search";

    private void initUI()
    {
        searchField = new JTextField(PLACEHOLDER);
        searchField.setHorizontalAlignment(JTextField.CENTER);
        searchField.setForeground(Color.GRAY);
        searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
        searchField.setAlignmentX(Component.LEFT_ALIGNMENT);
        searchField.addFocusListener(new java.awt.event.FocusAdapter() {
            @Override
            public void focusGained(java.awt.event.FocusEvent e) {
                if (searchField.getText().equals(PLACEHOLDER)) {
                    searchField.setText("");
                    searchField.setForeground(null);
                }
            }
            @Override
            public void focusLost(java.awt.event.FocusEvent e) {
                if (searchField.getText().isEmpty()) {
                    searchField.setText(PLACEHOLDER);
                    searchField.setForeground(Color.GRAY);
                }
            }
        });
        searchField.addActionListener(e -> searchUserOnPlugin());
        add(searchField);

        add(Box.createVerticalStrut(4));

        JPanel btnPanel = new JPanel(new GridLayout(1, 2, 4, 0));
        btnPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        btnPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

        JButton websiteSearchBtn = new JButton("<html><center>Website<br>Search</center></html>");
        websiteSearchBtn.addActionListener(e -> searchUserOnWebsite());

        pluginSearchBtn = new JButton("<html><center>Plugin<br>Search</center></html>");
        pluginSearchBtn.addActionListener(e -> searchUserOnPlugin());

        btnPanel.add(websiteSearchBtn);
        btnPanel.add(pluginSearchBtn);
        add(btnPanel);

        loginButton = new JButton("Login with Discord");
        loginButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
        loginButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        // Discord blurple (#5865F2), matching flipping-copilot's login button.
        loginButton.setBackground(DISCORD_BLURPLE);
        loginButton.setForeground(Color.WHITE);
        loginButton.setOpaque(true);
        loginButton.setFocusPainted(false);
        loginButton.addActionListener(e -> handleLogin());
    }

    public JButton getLoginButton()
    {
        return loginButton;
    }

    private boolean isValidUsername(String username)
    {
        if (username == null) return false;
        String trimmed = username.trim();
        if (trimmed.isEmpty() || trimmed.length() > 12) return false;
        // Allow alphanumeric, spaces, underscores, and hyphens (RuneScape username format)
        return trimmed.matches("^[a-zA-Z0-9 _-]+$");
    }

    private String normalizeUsername(String username)
    {
        if (username == null) return null;
        // Normalize: trim, lowercase, collapse multiple spaces to single space
        return username.trim().toLowerCase().replaceAll("\\s+", " ");
    }

    private void searchUserOnWebsite()
    {
        String username = searchField.getText();
        if (username == null || username.trim().isEmpty() || PLACEHOLDER.equals(username))
        {
            LinkBrowser.browse(PvPLeaderboardConstants.PUBLIC_SITE_BASE_URL);
            return;
        }
        if (!isValidUsername(username)) return;
        try
        {
            String normalizedUsername = normalizeUsername(username);
            String encodedUsername = URLEncoder.encode(normalizedUsername, "UTF-8");
            String url = PvPLeaderboardConstants.PUBLIC_SITE_BASE_URL + "/profile.html?player=" + encodedUsername;
            LinkBrowser.browse(url);
        }
        catch (Exception ignore) {}
    }

    private void searchUserOnPlugin()
    {
        String username = searchField.getText();
        if (username == null || username.trim().isEmpty() || PLACEHOLDER.equals(username))
        {
            return;
        }
        if (!isValidUsername(username))
        {
            return;
        }

        // Rate limit: 10 searches per minute
        if (!checkPluginSearchRateLimit())
        {
            // Show rate limit feedback briefly
            if (pluginSearchBtn != null)
            {
                pluginSearchBtn.setText("Wait...");
                Timer timer = new Timer(1000, e -> pluginSearchBtn.setText("Search"));
                timer.setRepeats(false);
                timer.start();
            }
            return;

        }

        if (onPluginSearch != null)
        {
            String normalizedUsername = normalizeUsername(username);
            onPluginSearch.accept(normalizedUsername);

            searchField.setText(PLACEHOLDER);
            searchField.setForeground(Color.GRAY);
            searchField.transferFocus();
        }
    }

    private boolean checkPluginSearchRateLimit()
    {
        long now = System.currentTimeMillis();
        long oneMinuteAgo = now - 60_000;

        // Remove timestamps older than 1 minute
        while (!pluginSearchTimestamps.isEmpty() && pluginSearchTimestamps.peekFirst() < oneMinuteAgo)
        {
            pluginSearchTimestamps.pollFirst();
        }

        // Check if we've exceeded the limit
        if (pluginSearchTimestamps.size() >= MAX_PLUGIN_SEARCHES_PER_MINUTE)
        {
            return false; // Rate limited
        }

        // Record this search
        pluginSearchTimestamps.addLast(now);
        return true;
    }

    private void handleLogin()
    {
        if (loginInProgress)
        {
            // The button doubles as "Cancel login" while a handshake is in
            // flight (the OAuth redirect now lands on a hosted page, so login
            // takes a browser round-trip + polling).
            try { discordAuthService.cancelLogin(); } catch (Exception ignore) {}
            setLoginBusy(false);
            return;
        }
        if (isLoggedIn)
        {
            // Logout
            setLoggedIn(false);
            clearTokens();
            if (onLoginStateChanged != null) onLoginStateChanged.run();
            return;
        }

        // Use Discord OAuth flow
        try
        {
            setLoginBusy(true);
            discordAuthService.login().thenAccept(success -> {
                if (success && discordAuthService.isLoggedIn())
                {
                    SwingUtilities.invokeLater(() -> {
                        setLoginBusy(false);
                        setLoggedIn(true);
                        if (onLoginStateChanged != null) onLoginStateChanged.run();
                    });
                }
                else
                {
                    SwingUtilities.invokeLater(() -> {
                        setLoginBusy(false);
                    });
                }
            }).exceptionally(ex -> {
                SwingUtilities.invokeLater(() -> {
                    setLoginBusy(false);
                });
                return null;
            });
        }
        catch (Exception e)
        {
            setLoginBusy(false);
        }
    }

    private void setLoginBusy(boolean busy)
    {
        loginInProgress = busy;
        try
        {
            if (loginButton != null)
            {
                // Stay enabled while busy so the user can cancel the handshake.
                loginButton.setEnabled(true);
                loginButton.setText(busy ? "Cancel login" : (isLoggedIn ? "Logout" : "Login with Discord"));
            }
            if (searchField != null) searchField.setEnabled(!busy);
        }
        catch (Exception ignore) {}
    }

    public void setLoggedIn(boolean loggedIn)
    {
        this.isLoggedIn = loggedIn;
        if (loginButton != null)
        {
            loginButton.setText(loggedIn ? "Logout" : "Login with Discord");
        }
    }

    public void setPluginSearchText(String text)
    {
        if (searchField != null)
        {
            searchField.setText(text);
        }
    }

    public String getPluginSearchText()
    {
        if (searchField == null) return "";
        String text = searchField.getText();
        return PLACEHOLDER.equals(text) ? "" : text;
    }

    private void clearTokens() {
        discordAuthService.logout();
        isLoggedIn = false;
        if (loginButton != null) loginButton.setText("Login with Discord");
    }
}

package com.pvp.leaderboard.ui;

import javax.swing.*;
import java.awt.*;
import java.util.List;
import java.util.ArrayList;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

public class WinRateChartPanel extends JPanel
{
    private List<Double> winRateHistory = new ArrayList<>();

    public WinRateChartPanel()
    {
        setPreferredSize(new Dimension(1024, 280));
    }

    public void setMatches(JsonArray matches)
    {
        this.winRateHistory = calculateWinRateHistory(matches);
        setPreferredSize(new Dimension(Math.max(240, winRateHistory.size() * 5), 200));
        revalidate();
        repaint();
    }

    private List<Double> calculateWinRateHistory(JsonArray matches)
    {
        List<Double> history = new ArrayList<>();
        if (matches == null || matches.size() == 0) return history;

        // Sort by time ascending
        List<JsonObject> sorted = new ArrayList<>();
        for (int i = 0; i < matches.size(); i++) sorted.add(matches.get(i).getAsJsonObject());
        sorted.sort((a, b) -> {
            double ta = a.has("when") ? a.get("when").getAsDouble() : 0;
            double tb = b.has("when") ? b.get("when").getAsDouble() : 0;
            return Double.compare(ta, tb);
        });

        int wins = 0;
        int total = 0;
        for (JsonObject m : sorted)
        {
            String result = m.has("result") ? m.get("result").getAsString().toLowerCase() : "";
            if ("win".equals(result)) wins++;
            if ("win".equals(result) || "loss".equals(result))
            {
                total++;
                if (total >= 10) // Only show after 10 games to avoid noise
                {
                    history.add((double) wins / total * 100.0);
                }
            }
        }
        return history;
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        Graphics2D g2 = (Graphics2D) g;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int width = getWidth() - 40;
        int height = getHeight() - 40;

        if (width <= 0 || height <= 0) return;

        // Draw axes
        g2.setColor(Color.LIGHT_GRAY);
        g2.drawLine(20, height + 20, width + 20, height + 20);
        g2.drawLine(20, 20, 20, height + 20);

        // Draw grid lines and Y-axis labels
        g2.setColor(Color.GRAY);
        for (int i = 0; i <= 10; i++)
        {
            int y = 20 + (i * height / 10);
            g2.drawLine(20, y, width + 20, y);
            g2.setColor(Color.WHITE);
            g2.drawString((100 - i * 10) + "%", 2, y + 5);
            g2.setColor(Color.GRAY);
        }

        // Draw X-axis labels and win rate line
        if (winRateHistory != null && winRateHistory.size() > 1)
        {
            // Draw win rate line
            g2.setColor(new Color(255, 215, 0)); // Gold color
            g2.setStroke(new BasicStroke(2));
            for (int i = 0; i < winRateHistory.size() - 1; i++)
            {
                int x1 = 20 + (i * width / (winRateHistory.size() - 1));
                int y1 = height + 20 - (int)(winRateHistory.get(i) * height / 100);
                int x2 = 20 + ((i + 1) * width / (winRateHistory.size() - 1));
                int y2 = height + 20 - (int)(winRateHistory.get(i + 1) * height / 100);
                g2.drawLine(x1, y1, x2, y2);
            }
        }
        else
        {
            g2.setColor(Color.GRAY);
            g2.drawString("No match data available", width / 2 - 60, height / 2);
        }
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class PerformanceStatsPanel extends JPanel
{
    private JLabel cumulativeStatsLabel;
    private JPanel bucketSelectorPanel;

    private DefaultTableModel rankBreakdownModel;
    private JTable rankBreakdownTable;

    private String currentBucket = "overall";

    /** All-time wins/losses/ties per bucket from {@code /user} →
     *  {@code cumulative_stats}. Source of truth for the K/D summary
     *  row — matches the website's {@code updatePerformanceOverviewDisplay}. */
    private Map<String, int[]> cumulativeStatsByBucket;

    // Cumulative opponent rank stats per bucket: bucket -> (rank -> [wins, losses])
    private Map<String, Map<String, int[]>> opponentRankStatsByBucket;

    public PerformanceStatsPanel()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createTitledBorder("Performance Breakdown"));

        initUI();
    }

    private void initUI()
    {
        Font baseFont = UIManager.getFont("Label.font");
        if (baseFont == null) baseFont = new Font("SansSerif", Font.PLAIN, 12);
        Font small = baseFont.deriveFont(Font.PLAIN, Math.max(10f, baseFont.getSize2D() - 1f));

        bucketSelectorPanel = new JPanel(new GridLayout(2, 3, 2, 2));
        bucketSelectorPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 56));
        String[] buckets = {"Overall", "NH", "Veng", "Multi", "DMM"};
        for (String b : buckets) {
            JButton btn = new JButton(b);
            btn.setFont(small);
            btn.setMargin(new Insets(2, 2, 2, 2));
            btn.setFocusPainted(false);
            final String bucketKey = b.toLowerCase();
            btn.addActionListener(e -> setBucket(bucketKey));
            bucketSelectorPanel.add(btn);
        }
        styleBucketButtons("overall");
        add(bucketSelectorPanel);

        // Summary row
        JPanel summaryRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));

        cumulativeStatsLabel = new JLabel("K: - D: - Winrate -%");
        cumulativeStatsLabel.setFont(small);
        summaryRow.add(cumulativeStatsLabel);

        add(summaryRow);

        // Rank breakdown table
        add(createRankBreakdownTable());
    }

    private JPanel createRankBreakdownTable()
    {
        String[] columns = {"Rank", "Wins", "Deaths", "KD"};
        rankBreakdownModel = new DefaultTableModel(columns, 0);
        rankBreakdownTable = new JTable(rankBreakdownModel);
        rankBreakdownTable.setEnabled(false);

        rankBreakdownTable.getColumnModel().getColumn(0).setPreferredWidth(90);
        rankBreakdownTable.getColumnModel().getColumn(1).setPreferredWidth(45);
        rankBreakdownTable.getColumnModel().getColumn(2).setPreferredWidth(45);
        rankBreakdownTable.getColumnModel().getColumn(3).setPreferredWidth(45);
        rankBreakdownTable.setAutoResizeMode(JTable.AUTO_RESIZE_ALL_COLUMNS);

        JScrollPane sp = new JScrollPane(rankBreakdownTable);
        sp.setPreferredSize(new Dimension(0, 150)); // Adjusted height

        // Wrap in panel to control sizing better if needed
        JPanel p = new JPanel(new BorderLayout());
        p.add(sp, BorderLayout.CENTER);
        p.setPreferredSize(new Dimension(0, 340)); // Match original preferred size
        return p;
    }

    /**
     * Switch to a different bucket for display.
     */
    public void setBucket(String bucket)
    {
        this.currentBucket = bucket;
        updateCumulativeDisplay();
        updateRankBreakdownDisplay();
        SwingUtilities.invokeLater(() -> styleBucketButtons(bucket));
    }

    private void styleBucketButtons(String activeBucket)
    {
        for (Component c : bucketSelectorPanel.getComponents())
        {
            if (c instanceof JButton)
            {
                JButton btn = (JButton) c;
                boolean selected = btn.getText().equalsIgnoreCase(activeBucket);
                if (selected)
                {
                    btn.setForeground(Color.WHITE);
                    btn.setBackground(new Color(60, 60, 60));
                }
                else
                {
                    btn.setForeground(Color.GRAY);
                    btn.setBackground(UIManager.getColor("Button.background"));
                }
            }
        }
    }

    /**
     * Receive all-time wins/losses/ties from {@code /user} →
     * {@code cumulative_stats}. Drives the K/D summary label for the
     * selected bucket. Matches the website's performance overview.
     */
    public void setCumulativeStats(JsonObject cumulativeStats)
    {
        cumulativeStatsByBucket = parseCumulativeStats(cumulativeStats);
        updateCumulativeDisplay();
    }

    private static Map<String, int[]> parseCumulativeStats(JsonObject cumulativeStats)
    {
        Map<String, int[]> out = new HashMap<>();
        if (cumulativeStats == null) return out;
        for (String bucket : cumulativeStats.keySet())
        {
            try
            {
                if (!cumulativeStats.get(bucket).isJsonObject()) continue;
                JsonObject b = cumulativeStats.getAsJsonObject(bucket);
                int wins = b.has("wins") ? b.get("wins").getAsInt() : 0;
                int losses = b.has("losses") ? b.get("losses").getAsInt() : 0;
                int ties = b.has("ties") ? b.get("ties").getAsInt() : 0;
                out.put(bucket.toLowerCase(), new int[]{wins, losses, ties});
            }
            catch (Exception ignored) {}
        }
        return out;
    }

    /**
     * Update the K/D summary from {@link #cumulativeStatsByBucket}, falling
     * back to summing {@link #opponentRankStatsByBucket} when cumulative
     * data is absent (legacy /user payloads).
     */
    private void updateCumulativeDisplay()
    {
        int kills = 0, deaths = 0, ties = 0;
        if (cumulativeStatsByBucket != null && !cumulativeStatsByBucket.isEmpty())
        {
            int[] row = cumulativeStatsByBucket.get(currentBucket);
            if (row == null && !"overall".equals(currentBucket))
            {
                row = cumulativeStatsByBucket.get("overall");
            }
            if (row != null)
            {
                kills = row[0];
                deaths = row[1];
                ties = row[2];
            }
        }
        else if (opponentRankStatsByBucket != null)
        {
            Map<String, int[]> currentStats = opponentRankStatsByBucket.getOrDefault(
                currentBucket, Collections.emptyMap()
            );
            for (int[] v : currentStats.values())
            {
                kills += v[0];
                deaths += v[1];
            }
        }
        int total = kills + deaths + ties;
        double winRate = total > 0 ? (double) kills / total * 100 : 0;

        final int k = kills, d = deaths;
        final double wr = winRate;
        SwingUtilities.invokeLater(() -> {
            cumulativeStatsLabel.setText(String.format("K: %d D: %d Winrate %.1f%%", k, d, wr));
        });
    }

    /**
     * @deprecated Use {@link #setCumulativeStats(JsonObject)} instead.
     */
    @Deprecated
    public void updateStats(int wins, int losses, int ties)
    {
        // No longer used - cumulative stats come from API now
    }

    /**
     * Helper method to parse rank stats from a JsonObject containing rank -> {wins, losses} entries.
     */
    private Map<String, int[]> parseRankStats(JsonObject rankData)
    {
        Map<String, int[]> result = new HashMap<>();
        if (rankData == null) return result;
        for (String key : rankData.keySet()) {
            try {
                JsonObject rs = rankData.getAsJsonObject(key);
                int wins = rs.has("wins") ? rs.get("wins").getAsInt() : 0;
                int losses = rs.has("losses") ? rs.get("losses").getAsInt() : 0;
                if (wins > 0 || losses > 0) {
                    result.put(key, new int[]{wins, losses});
                }
            } catch (Exception ignored) {}
        }
        return result;
    }

    /**
     * Receive opponent rank stats from the /user API response.
     * Called from DashboardPanel.loadPlayerStats() after getUserProfile.
     * Updates the rank breakdown table with all-time stats per opponent tier+division.
     * 
     * Handles two formats:
     * - New format: nested by bucket {"overall": {...}, "nh": {...}, ...}
     * - Old format: flat {rank -> stats} (wrapped in "overall" for all buckets)
     */
    public void setOpponentRankStats(JsonObject opponentStats)
    {
        opponentRankStatsByBucket = new HashMap<>();

        if (opponentStats != null) {
            // Detect new format: has "overall" key with nested object
            if (opponentStats.has("overall") && 
                opponentStats.get("overall").isJsonObject()) {
                // New format: parse each bucket
                for (String bucket : opponentStats.keySet()) {
                    try {
                        JsonObject bucketData = opponentStats.getAsJsonObject(bucket);
                        opponentRankStatsByBucket.put(bucket, parseRankStats(bucketData));
                    } catch (Exception ignored) {}
                }
            } else {
                // Old format: wrap in "overall" and copy to all buckets
                Map<String, int[]> overall = parseRankStats(opponentStats);
                for (String b : new String[]{"overall", "nh", "veng", "multi", "dmm"}) {
                    opponentRankStatsByBucket.put(b, overall);
                }
            }
        }
        updateRankBreakdownDisplay();
    }

    /**
     * Update the rank breakdown table from cumulative opponent rank stats for current bucket.
     * Sorts by rank tier (highest first) then by division (1, 2, 3).
     */
    private void updateRankBreakdownDisplay()
    {
        SwingUtilities.invokeLater(() -> {
            if (rankBreakdownModel == null) return;
            rankBreakdownModel.setRowCount(0);

            // Get stats for current bucket, fallback to overall
            Map<String, int[]> currentStats = Collections.emptyMap();
            if (opponentRankStatsByBucket != null) {
                currentStats = opponentRankStatsByBucket.getOrDefault(
                    currentBucket, Collections.emptyMap()
                );
            }

            if (currentStats.isEmpty()) return;

            // Rank order for sorting (highest first)
            final String[] RANK_ORDER = {"3rd Age", "Dragon", "Rune", "Adamant", "Mithril", "Black", "Steel", "Iron", "Bronze"};
            java.util.Map<String, Integer> rankIndex = new HashMap<>();
            for (int i = 0; i < RANK_ORDER.length; i++) {
                rankIndex.put(RANK_ORDER[i], i);
            }

            // Sort keys by rank tier then division
            java.util.List<String> sortedKeys = new java.util.ArrayList<>(currentStats.keySet());
            sortedKeys.sort((a, b) -> {
                String[] partsA = a.split(" ");
                String[] partsB = b.split(" ");
                String rankA = partsA[0].equals("3rd") ? "3rd Age" : partsA[0];
                String rankB = partsB[0].equals("3rd") ? "3rd Age" : partsB[0];
                int idxA = rankIndex.getOrDefault(rankA, 999);
                int idxB = rankIndex.getOrDefault(rankB, 999);
                if (idxA != idxB) return idxA - idxB;
                // Same rank tier, sort by division (1, 2, 3)
                int divA = partsA.length > 1 ? Integer.parseInt(partsA[partsA.length - 1]) : 0;
                int divB = partsB.length > 1 ? Integer.parseInt(partsB[partsB.length - 1]) : 0;
                return divA - divB;
            });

            for (String key : sortedKeys) {
                int[] stats = currentStats.get(key);
                if (stats != null && (stats[0] > 0 || stats[1] > 0)) {
                    String kd = stats[1] > 0
                        ? String.format("%.2f", (double) stats[0] / stats[1])
                        : String.valueOf(stats[0]);
                    rankBreakdownModel.addRow(new Object[]{key, stats[0], stats[1], kd});
                }
            }
        });
    }

    /**
     * @deprecated Use setOpponentRankStats() instead. Kept for backward compatibility.
     * Update rank breakdown table from match history.
     */
    @Deprecated
    public void updateBreakdown(JsonArray matches)
    {
        // Only use if opponentRankStatsByBucket not set (legacy fallback)
        if (opponentRankStatsByBucket != null && !opponentRankStatsByBucket.isEmpty()) {
            return;
        }

        SwingUtilities.invokeLater(() -> {
            if (rankBreakdownModel == null || matches == null) return;
            rankBreakdownModel.setRowCount(0);

            Map<String, int[]> stats = new HashMap<>();
            for (int i = 0; i < matches.size(); i++)
            {
                JsonObject m = matches.get(i).getAsJsonObject();
                String result = m.has("result") ? m.get("result").getAsString().toLowerCase() : "";
                String oppRank = m.has("opponent_rank") ? m.get("opponent_rank").getAsString() : "Unranked";

                stats.putIfAbsent(oppRank, new int[]{0, 0});
                if ("win".equals(result)) stats.get(oppRank)[0]++;
                else if ("loss".equals(result)) stats.get(oppRank)[1]++;
            }

            for (Map.Entry<String, int[]> e : stats.entrySet())
            {
                int w = e.getValue()[0], l = e.getValue()[1];
                String kd = l > 0 ? String.format("%.2f", (double) w / l) : String.valueOf(w);
                rankBreakdownModel.addRow(new Object[]{e.getKey(), w, l, kd});
            }
        });
    }

    public void reset()
    {
        opponentRankStatsByBucket = null;
        cumulativeStatsByBucket = null;
        currentBucket = "overall";
        SwingUtilities.invokeLater(() -> {
            cumulativeStatsLabel.setText("K: - D: - Winrate -%");
            if (rankBreakdownModel != null) rankBreakdownModel.setRowCount(0);
            styleBucketButtons("overall");
        });
    }
}

