package com.pvp.leaderboard.service;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class ClientIdentityService
{
    private final ConfigManager configManager;
    private String clientUniqueId;

    @Inject
    public ClientIdentityService(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    /**
     * Initializes the client ID on startup.
     * Logic: Prefer global file ~/.runelite/pvp-leaderboard.id. If missing, generate and save.
     * Also syncs to RuneLite profile config for backup.
     */
    public void loadOrGenerateId()
    {
        if (clientUniqueId != null) return; // Already loaded

        File globalFile = new File(System.getProperty("user.home"), ".runelite/pvp-leaderboard.id");
        String globalId = null;

        try
        {
            if (globalFile.exists())
            {
                byte[] bytes = Files.readAllBytes(globalFile.toPath());
                globalId = new String(bytes, StandardCharsets.UTF_8).trim();
            }
        }
        catch (Exception e)
        {
            // log.debug("Failed to read global identity file", e);
        }

        String finalId = globalId;

        // If disk file missing, try to recover from profile config
        if (finalId == null || finalId.isEmpty())
        {
            String profileId = configManager.getConfiguration("PvPLeaderboard", "clientUniqueId");
            if (profileId != null && !profileId.isEmpty())
            {
                finalId = profileId;
            }
        }

        // If still no ID, generate new one
        if (finalId == null || finalId.isEmpty())
        {
            finalId = UUID.randomUUID().toString();
        }

        // Save to global file
        try
        {
            File parent = globalFile.getParentFile();
            if (parent != null && !parent.exists())
            {
                parent.mkdirs();
            }
            Files.write(globalFile.toPath(), finalId.getBytes(StandardCharsets.UTF_8));
        }
        catch (Exception e)
        {
            // log.debug("Failed to write global identity file", e);
        }

        // Sync to profile
        String profileId = configManager.getConfiguration("PvPLeaderboard", "clientUniqueId");
        if (!finalId.equals(profileId))
        {
            configManager.setConfiguration("PvPLeaderboard", "clientUniqueId", finalId);
        }

        this.clientUniqueId = finalId;
    }

    public String getClientUniqueId()
    {
        if (clientUniqueId == null) loadOrGenerateId();
        return clientUniqueId;
    }
}

package com.pvp.leaderboard.service;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pvp.leaderboard.PvPLeaderboardConstants;
import com.pvp.leaderboard.cache.MembershipCache;
import com.pvp.leaderboard.config.PvPLeaderboardConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLiteProperties;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Fetches the rank-overlay MEMBERSHIP feed (names only) and maintains
 * {@link MembershipCache}.
 *
 * <p>Replaces the per-poll {@code whitelist.json} download (which bundled
 * membership + rank into one O(N) blob every client re-pulled every poll →
 * O(N^2) egress). Here:</p>
 * <ul>
 *   <li>{@code plugin-users/snapshot.json} — full member set, fetched once on
 *       login + ETag-revalidated (304 the rest of the day).</li>
 *   <li>{@code plugin-users/delta.json} — absolute diff vs the day's snapshot,
 *       polled every 10 minutes (tiny payload, mostly unchanged).</li>
 * </ul>
 *
 * <p>Rank is NOT in this feed — the overlay resolves rank per on-screen name
 * via the name-keyed {@code rank_idx} shards. See PLAN_PRESENCE_FRESHNESS.md.</p>
 *
 * <p>The plugin uses ONLY this feed for membership; the legacy
 * {@code whitelist.json} path is retired client-side (the backend keeps it as
 * a fallback). Heartbeats still flow via {@link WhitelistService}.</p>
 */
@Slf4j
@Singleton
public class MembershipService
{
    private static final String SNAPSHOT_URL =
        PvPLeaderboardConstants.PUBLIC_SITE_BASE_URL + "/plugin-users/snapshot.json";
    private static final String DELTA_URL =
        PvPLeaderboardConstants.PUBLIC_SITE_BASE_URL + "/plugin-users/delta.json";
    private static final String USER_AGENT = "RuneLite/" + RuneLiteProperties.getVersion();

    /** Matches the backend membership_generator 10-min delta cadence. */
    private static final long DELTA_POLL_MS = 10L * 60L * 1000L;

    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final PvPLeaderboardConfig config;
    private final MembershipCache cache;
    private final ScheduledExecutorService scheduler;

    private final AtomicBoolean active = new AtomicBoolean(false);
    private volatile ScheduledFuture<?> scheduledPoll = null;
    private volatile String snapshotEtag = null;

    @Inject
    public MembershipService(OkHttpClient okHttpClient, Gson gson, PvPLeaderboardConfig config,
                             MembershipCache cache, ScheduledExecutorService scheduler)
    {
        this.okHttpClient = okHttpClient;
        this.gson = gson;
        this.config = config;
        this.cache = cache;
        this.scheduler = scheduler;
    }

    /**
     * Start the membership sync (snapshot now, then delta every 10 min).
     * No-op when "Display other players ranks" is disabled.
     */
    public void onLogin()
    {
        if (!config.enableWhitelistRanks())
        {
            log.debug("[Membership] Display-others-ranks disabled — not starting sync");
            return;
        }
        if (!active.compareAndSet(false, true))
        {
            return; // already running
        }
        log.debug("[Membership] Starting membership sync");
        fetchSnapshot();
        scheduleDeltaPoll();
    }

    /**
     * Stop the membership sync. Safe to call when not running.
     */
    public void onLogout()
    {
        active.set(false);
        ScheduledFuture<?> scheduled = scheduledPoll;
        if (scheduled != null && !scheduled.isDone())
        {
            scheduled.cancel(false);
        }
        scheduledPoll = null;
    }

    private void scheduleDeltaPoll()
    {
        scheduledPoll = scheduler.schedule(() ->
        {
            if (active.get())
            {
                pollDelta();
                scheduleDeltaPoll();
            }
        }, DELTA_POLL_MS, TimeUnit.MILLISECONDS);
    }

    private void fetchSnapshot()
    {
        Request.Builder builder = new Request.Builder()
            .url(SNAPSHOT_URL)
            .header("User-Agent", USER_AGENT)
            .get();
        String etag = snapshotEtag;
        if (etag != null)
        {
            builder.header("If-None-Match", etag);
        }

        okHttpClient.newCall(builder.build()).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.debug("[Membership] Snapshot fetch failed: {}", e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response res = response)
                {
                    if (res.code() == 304)
                    {
                        log.debug("[Membership] Snapshot 304 (unchanged)");
                        return;
                    }
                    if (!res.isSuccessful())
                    {
                        log.debug("[Membership] Snapshot HTTP {}", res.code());
                        return;
                    }
                    ResponseBody body = res.body();
                    if (body == null)
                    {
                        return;
                    }
                    String json = body.string();
                    String tag = res.header("ETag");
                    if (tag != null)
                    {
                        snapshotEtag = tag;
                    }
                    applySnapshotJson(json);
                }
                catch (Exception e)
                {
                    log.debug("[Membership] Snapshot parse error: {}", e.getMessage());
                }
            }
        });
    }

    private void pollDelta()
    {
        Request request = new Request.Builder()
            .url(DELTA_URL)
            .header("User-Agent", USER_AGENT)
            .get()
            .build();

        okHttpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.debug("[Membership] Delta fetch failed: {}", e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response res = response)
                {
                    if (!res.isSuccessful())
                    {
                        log.debug("[Membership] Delta HTTP {}", res.code());
                        return;
                    }
                    ResponseBody body = res.body();
                    if (body == null)
                    {
                        return;
                    }
                    applyDeltaJson(body.string());
                }
                catch (Exception e)
                {
                    log.debug("[Membership] Delta parse error: {}", e.getMessage());
                }
            }
        });
    }

    private void applySnapshotJson(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        if (root == null)
        {
            return;
        }
        long epoch = root.has("epoch") && !root.get("epoch").isJsonNull()
            ? root.get("epoch").getAsLong() : 0L;
        List<String> names = parseStringArray(root, "names");
        cache.replaceFromSnapshot(names, epoch);
    }

    private void applyDeltaJson(String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        if (root == null)
        {
            return;
        }
        long epoch = root.has("epoch") && !root.get("epoch").isJsonNull()
            ? root.get("epoch").getAsLong() : 0L;

        // Epoch mismatch = the daily snapshot rolled over since our last
        // snapshot fetch. Re-fetch the snapshot (its new epoch becomes the
        // baseline); the next delta poll will then line up.
        if (epoch != cache.getEpoch())
        {
            log.debug("[Membership] Delta epoch {} != cached {} — refetching snapshot",
                epoch, cache.getEpoch());
            fetchSnapshot();
            return;
        }

        List<String> added = parseStringArray(root, "added");
        List<String> removed = parseStringArray(root, "removed");
        cache.applyDelta(added, removed, epoch);
    }

    private List<String> parseStringArray(JsonObject obj, String field)
    {
        List<String> out = new ArrayList<>();
        if (obj.has(field) && obj.get(field).isJsonArray())
        {
            JsonArray arr = obj.getAsJsonArray(field);
            for (var el : arr)
            {
                if (el != null && !el.isJsonNull())
                {
                    out.add(el.getAsString());
                }
            }
        }
        return out;
    }
}

package com.pvp.leaderboard.service;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.inject.Inject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;

@Slf4j
public class MatchResultService
{
    private static final String API_URL = "https://l5xya0wf0d.execute-api.us-east-1.amazonaws.com/prod/matchresult";
    private static final String CLIENT_ID = "runelite";
    private static final String PLUGIN_VERSION = "1.0.0";
    // This is meant to be hardcoded and be this value for everyone. New versions of the plugin will update this on the backend so that it doesn't take matches from old clients if there is an incompatibility added.
    private static final String RUNELITE_CLIENT_SECRET = "7f2f6a0e-2c6b-4b1d-9a39-6f2b2a8a1f3c"; 
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public MatchResultService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    // Fallback constructor for tests: use RuneLite injector (no fresh clients)
    public MatchResultService()
    {
        this(
            net.runelite.client.RuneLite.getInjector().getInstance(OkHttpClient.class),
            net.runelite.client.RuneLite.getInjector().getInstance(Gson.class)
        );
    }

    /**
     * Validates a RuneScape username format.
     * Valid: alphanumeric, spaces, underscores, hyphens, 1-12 characters
     */
    private boolean isValidRunescapeName(String name)
    {
        if (name == null) return false;
        String trimmed = name.trim();
        if (trimmed.isEmpty() || trimmed.length() > 12) return false;
        return trimmed.matches("^[a-zA-Z0-9 _-]+$");
    }

    public CompletableFuture<Boolean> submitMatchResult(MatchResult match)
    {
        CompletableFuture<Boolean> overall = new CompletableFuture<>();
        try
        {
            // Validate player and opponent names match RuneScape format
            if (!isValidRunescapeName(match.getPlayerId()) || !isValidRunescapeName(match.getOpponentId()))
            {
                log.debug("[Submit] Invalid name format: player='{}' opponent='{}'", match.getPlayerId(), match.getOpponentId());
                overall.complete(false);
                return overall;
            }

            String bodyJson = buildBodyJson(match);

            log.debug("[MatchAPI] Request body: {}", bodyJson);

            // HMAC-signed submission is the sole path. The plugin holds no
            // user token (Discord login does not mint one for the client),
            // so every match is authenticated by the shared client secret.
            submitSignedFightAsync(bodyJson, match.getClientUniqueId()).whenComplete((ok, ex) -> {
                if (ex != null) overall.complete(false); else overall.complete(ok);
            });
        }
        catch (Exception e)
        {
            log.debug("[MatchAPI] EXCEPTION during submit: {}", e.getMessage(), e);
            overall.complete(false);
        }
        return overall;
    }

    /**
     * Builds the {@code POST /matchresult} JSON body. The 12 base fields
     * are always present and unchanged; the two LMS freeze-log fields are
     * appended <b>last</b> and only when set, so a normal fight produces a
     * byte-for-byte identical payload to before this feature existed. The
     * backend treats {@code lms_freeze_logout} / {@code lms_freeze_reason}
     * as optional trailing fields.
     *
     * <p>Package-private so {@code MatchResultServiceTest} can pin the
     * serialization contract without a network round-trip.
     */
    String buildBodyJson(MatchResult match)
    {
        JsonObject body = new JsonObject();
        body.addProperty("player_id", match.getPlayerId());
        body.addProperty("opponent_id", match.getOpponentId());
        body.addProperty("result", match.getResult());
        body.addProperty("world", match.getWorld());
        body.addProperty("fight_start_ts", match.getFightStartTs());
        body.addProperty("fight_end_ts", match.getFightEndTs());
        body.addProperty("fightStartSpellbook", match.getFightStartSpellbook());
        body.addProperty("fightEndSpellbook", match.getFightEndSpellbook());
        body.addProperty("wasInMulti", match.isWasInMulti());
        body.addProperty("client_id", CLIENT_ID);
        body.addProperty("plugin_version", PLUGIN_VERSION);
        body.addProperty("damage_to_opponent", match.getDamageToOpponent());

        // Optional trailing LMS freeze-log fields — omitted entirely for
        // normal fights so the common-case payload is unchanged.
        if (match.isLmsFreezeLogout())
        {
            body.addProperty("lms_freeze_logout", true);
            String reason = match.getLmsFreezeReason();
            if (reason != null && !reason.trim().isEmpty())
            {
                body.addProperty("lms_freeze_reason", reason);
            }
        }

        return gson.toJson(body);
    }

    private CompletableFuture<Boolean> submitSignedFightAsync(String body, String clientUniqueId)
    {
        CompletableFuture<Boolean> future = new CompletableFuture<>();
        long timestamp = System.currentTimeMillis() / 1000;
        String signature;
        try
        {
            signature = generateSignature(body, timestamp);
        }
        catch (Exception e)
        {
            log.debug("[MatchAPI] Unauth signature generation FAILED: {}", e.getMessage());
            future.completeExceptionally(e);
            return future;
        }

        Request request = new Request.Builder()
            .url(API_URL)
            .post(RequestBody.create(JSON, body))
            .addHeader("x-client-id", CLIENT_ID)
            .addHeader("x-timestamp", String.valueOf(timestamp))
            .addHeader("x-signature", signature)
            .addHeader("X-Client-Unique-Id", clientUniqueId)
            .build();

        log.debug("[MatchAPI] Unauth request to: {} timestamp={}", API_URL, timestamp);
        final long reqStart = System.nanoTime();

        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                long ms = (System.nanoTime() - reqStart) / 1_000_000;
                log.debug("[MatchAPI] Unauth request NETWORK FAILURE after {}ms: {}", ms, e.getMessage());
                future.complete(false);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                long ms = (System.nanoTime() - reqStart) / 1_000_000;
                try (Response res = response)
                {
                    int code = res.code();
                    String reqId = null; try { reqId = res.header("x-amzn-RequestId"); } catch (Exception ignore) {}

                    if ((code >= 200 && code < 300) || code == 202)
                    {
                        log.debug("[MatchAPI] Unauth response SUCCESS in {}ms: code={} requestId={}", ms, code, reqId);
                        future.complete(true);
                    }
                    else
                    {
                        String errBody = null;
                        try { okhttp3.ResponseBody err = res.body(); errBody = err != null ? err.string() : null; } catch (Exception ignore) {}
                        log.debug("[MatchAPI] Unauth response FAILED in {}ms: code={} requestId={} body={}", ms, code, reqId, errBody);
                        future.complete(false);
                    }
                }
            }
        });

        return future;
    }

    private String generateSignature(String body, long timestamp) throws Exception
    {
        String message = "POST\n/matchresult\n" + body + "\n" + timestamp;
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec secretKey = new SecretKeySpec(RUNELITE_CLIENT_SECRET.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
        mac.init(secretKey);
        byte[] hash = mac.doFinal(message.getBytes(StandardCharsets.UTF_8));

        StringBuilder hexString = new StringBuilder();
        for (byte b : hash)
        {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

