package com.pvp.leaderboard.lobby;

import com.google.gson.JsonObject;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.util.RankUtils;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;

/**
 * Production {@link LobbyJoinGate} backed by
 * {@link PvPDataService#getUserProfile}. Wires the local player's
 * {@code cumulative_stats.<bucket>} to per-{@link Style} match counts +
 * exposes an hourly auto-refresh.
 *
 * <p><b>Lifecycle.</b>
 * <ol>
 *   <li>{@link #configure} is called once from {@code
 *   PvPLeaderboardPlugin.startUp()} to wire the {@link Supplier}s that
 *   resolve the local player's name + UUID at refresh time. Held as
 *   {@link Supplier}s rather than snapshot values because the player
 *   name is unavailable until {@code GameState.LOGGED_IN} fires (the
 *   plugin's {@code startUp()} can run before login).</li>
 *   <li>{@link #onLogin} fires from {@code onGameStateChanged
 *   LOGGED_IN}; kicks off an immediate refresh and starts the hourly
 *   auto-refresh timer.</li>
 *   <li>{@link #onLogout} fires from {@code LOGIN_SCREEN}; cancels the
 *   timer and clears the count map (returning to "unknown" state). The
 *   gate doesn't tear down listeners — the panel is registered for the
 *   lifetime of the dashboard.</li>
 * </ol>
 *
 * <p><b>Why no listener removal?</b> The only known caller is
 * {@code MatchmakingLobbyPanel}, which is a singleton-lifetime
 * collaborator; adding {@code removeListener} just invites lifecycle
 * bugs where the panel forgets to clean up. Mirror of the same decision
 * in {@code WebSocketManager.addConnectListener}.
 */
@Slf4j
@Singleton
public final class UserProfileLobbyJoinGate implements LobbyJoinGate
{
    private final PvPDataService pvpDataService;
    private final ScheduledExecutorService scheduler;

    /** Listeners notified on the EDT after every state mutation (refresh
     *  start, refresh complete, counts changed). {@link CopyOnWriteArrayList}
     *  so {@code addListener} during a fire callback doesn't trip
     *  ConcurrentModificationException. */
    private final CopyOnWriteArrayList<Runnable> listeners = new CopyOnWriteArrayList<>();

    /** Suppliers resolve at refresh time — see class javadoc for why
     *  these aren't snapshot values. {@code volatile} since
     *  {@link #configure} writes from the plugin's startup thread and
     *  {@link #refresh} reads from the scheduler thread / EDT. */
    private volatile Supplier<String> nameSupplier;
    private volatile Supplier<String> uuidSupplier;

    /** Guard against concurrent in-flight refreshes. CAS-incremented at
     *  {@link #refresh()} entry; cleared in the completion callback. */
    private final AtomicBoolean refreshing = new AtomicBoolean(false);

    /** Synchronised on {@code this} for read+write because the EnumMap
     *  isn't thread-safe and listeners may read it from the EDT while
     *  the refresh callback writes from an OkHttp dispatcher thread. */
    private final EnumMap<Style, Integer> counts = new EnumMap<>(Style.class);

    /** Per-style rank index parallel to {@link #counts}, derived from
     *  {@code cumulative_stats.<bucket>.tier}. Independent of the
     *  threshold check — a user with 5 NH matches still has an NH
     *  rank (Bronze 3 by default); we just don't let them queue NH
     *  yet. Read by {@link #getRankIdxByStyle()} for the panel's
     *  self-profile preview. Same lock discipline as {@link #counts}. */
    private final EnumMap<Style, Integer> rankIdxByStyle = new EnumMap<>(Style.class);

    private volatile long lastRefreshEpochMs;

    /** Active auto-refresh handle; null when {@link #onLogout()} or no
     *  login has occurred. */
    private ScheduledFuture<?> autoRefresh;

    /** {@code true} between {@link #onLogin()} and {@link #onLogout()}.
     *  Independent of whether a refresh has completed — flips
     *  synchronously when the plugin reports the game-state change so
     *  the panel can swap its "Please log into the game" notice without
     *  waiting for the first network roundtrip. {@code volatile} since
     *  reads come from the EDT and writes from the plugin's game-event
     *  thread. */
    private volatile boolean loggedIn;

    /** Server-supplied moderator bit for the local user, parsed off the
     *  {@code /user} profile JSON's {@code is_mod} field. Authoritative
     *  source for the {@link MatchmakingLobbyPanel} self-preview row's
     *  [MOD] chip — the lobby roster server-filters the viewer's own
     *  row out of every push, so this is the only client-side path
     *  that surfaces the local user's own mod status.
     *
     *  <p>Strict-boolean read mirrors {@code WebSocketLobbyService.parseMember}
     *  for peer roster rows: only a JSON boolean primitive {@code true}
     *  flips the bit. Defaults to {@code false} on construction, on
     *  {@link #onLogout()}, and on a soft-404 (null profile) refresh
     *  so a stale mod flag never carries between sessions / accounts.
     *  {@code volatile} for the same EDT-vs-network-callback reason as
     *  {@link #loggedIn}. */
    private volatile boolean isMod = false;

    @Inject
    public UserProfileLobbyJoinGate(PvPDataService pvpDataService,
                                    ScheduledExecutorService scheduler)
    {
        if (pvpDataService == null) throw new IllegalArgumentException("pvpDataService is required");
        if (scheduler == null) throw new IllegalArgumentException("scheduler is required");
        this.pvpDataService = pvpDataService;
        this.scheduler = scheduler;
    }

    /** Wire the identity suppliers — must be called once before the
     *  first {@link #onLogin()}. Idempotent on repeat calls (just
     *  overwrites). */
    public void configure(Supplier<String> nameSupplier,
                          Supplier<String> uuidSupplier)
    {
        this.nameSupplier = nameSupplier;
        this.uuidSupplier = uuidSupplier;
    }

    /** Called by the plugin on {@code GameState.LOGGED_IN}. Schedules the
     *  hourly auto-refresh + kicks off an immediate first refresh.
     *  Idempotent: a second call (e.g. on character-switch) replaces the
     *  existing schedule without stacking. */
    public synchronized void onLogin()
    {
        cancelAutoRefreshLocked();
        loggedIn = true;
        // Fast-retry schedule for the initial-fetch window: every
        // minute until the first refresh succeeds. The refresh()
        // success path replaces this with the {@link
        // #AUTO_REFRESH_INTERVAL_MS} hourly schedule. Without the
        // fast-retry, a failed initial fetch would leave the user
        // waiting an hour for the next attempt (and the gate stuck
        // on "Please log into the game" the whole time).
        autoRefresh = scheduler.scheduleAtFixedRate(
            this::autoTick,
            INITIAL_RETRY_INTERVAL_MS,
            INITIAL_RETRY_INTERVAL_MS,
            TimeUnit.MILLISECONDS);
        // Initial fetch — without this the panel would have no counts to
        // show until the first fast-retry tick. refresh() fires
        // listeners on entry, which is what swaps the panel from
        // "Please log into the game" → the real gate UI.
        refresh();
    }

    /** Called by the plugin on {@code GameState.LOGIN_SCREEN}. Cancels
     *  the auto-refresh + clears cached counts so the next user logging
     *  in on the same client doesn't see the previous user's counts. */
    public synchronized void onLogout()
    {
        cancelAutoRefreshLocked();
        loggedIn = false;
        synchronized (counts)
        {
            counts.clear();
            rankIdxByStyle.clear();
        }
        lastRefreshEpochMs = 0L;
        // Drop the mod bit — without this, a non-mod logging in on the
        // same client right after a moderator would inherit the [MOD]
        // chip on their self-preview until the first /user fetch
        // completed.
        isMod = false;
        fireListenersOnEdt();
    }

    private void cancelAutoRefreshLocked()
    {
        if (autoRefresh != null)
        {
            autoRefresh.cancel(false);
            autoRefresh = null;
        }
    }

    /** Auto-refresh tick handler. Skips if there's already a refresh in
     *  flight (manual refresh racing with the scheduler) to keep the
     *  network footprint to "at most one in-flight at a time". */
    private void autoTick()
    {
        if (refreshing.get()) return;
        refresh();
    }

    @Override
    public Map<Style, Integer> getMatchCounts()
    {
        synchronized (counts)
        {
            return Collections.unmodifiableMap(new EnumMap<>(counts));
        }
    }

    @Override
    public Map<Style, Integer> getRankIdxByStyle()
    {
        synchronized (counts)
        {
            // Share the same monitor as {@link #counts} — the two
            // EnumMaps are mutated together inside {@link
            // #applyProfile} so they never observe a torn snapshot.
            return Collections.unmodifiableMap(new EnumMap<>(rankIdxByStyle));
        }
    }

    @Override
    public long getLastRefreshEpochMs() { return lastRefreshEpochMs; }

    @Override
    public boolean isRefreshing() { return refreshing.get(); }

    @Override
    public boolean isLoggedIn() { return loggedIn; }

    @Override
    public boolean isMod() { return isMod; }

    @Override
    public void refresh()
    {
        if (!refreshing.compareAndSet(false, true))
        {
            // Already in flight — debounce. The in-flight call will fire
            // listeners on its own completion path.
            return;
        }
        fireListenersOnEdt(); // refreshing=true

        Supplier<String> nameSup = this.nameSupplier;
        Supplier<String> uuidSup = this.uuidSupplier;
        String name = nameSup != null ? nameSup.get() : null;
        String uuid = uuidSup != null ? uuidSup.get() : null;
        if (name == null || name.trim().isEmpty())
        {
            // Pre-login refresh attempt — bail cleanly. We do NOT
            // promote the autoRefresh schedule to hourly here; the
            // fast-retry schedule from onLogin() will fire again in
            // INITIAL_RETRY_INTERVAL_MS so the count auto-populates
            // as soon as the local player name resolves. (Previously
            // refresh() unconditionally promoted to hourly at entry,
            // which meant a single failed initial attempt locked the
            // user out of auto-refresh for an hour.)
            refreshing.set(false);
            fireListenersOnEdt();
            return;
        }

        // forceRefresh=true bypasses PvPDataService's 30s local TTL —
        // we want the freshest read. Server-side CloudFront cache (60s)
        // still applies, which is fine; the user can't refresh faster
        // than that and get materially newer data anyway.
        pvpDataService.getUserProfile(name, uuid, true)
            .whenComplete((profile, ex) ->
            {
                try
                {
                    if (ex != null)
                    {
                        log.debug("LobbyJoinGate refresh failed for {}", name, ex);
                        // Don't clear counts — stale counts are better
                        // than empty ones (user already saw them; this
                        // would just flicker them to "Unknown" then
                        // back). Just don't update lastRefreshEpochMs
                        // and don't promote the schedule — the
                        // fast-retry tick will try again in 1 min.
                        return;
                    }
                    if (profile == null)
                    {
                        // Soft 404 from the API — player profile doesn't
                        // exist yet (e.g. brand-new account with zero
                        // matches). Surface zeros in the UI but do NOT
                        // treat this as a successful refresh: promoting
                        // to the hourly schedule here left new players
                        // stuck below THRESHOLD until they restarted
                        // RuneLite or clicked Refresh count manually.
                        applyAllZero();
                        return;
                    }
                    applyProfile(profile);
                    lastRefreshEpochMs = System.currentTimeMillis();
                    // First-success / manual-refresh promote: switch to
                    // the hourly cadence and reset the clock so the
                    // next auto-tick is 1h from now (not 1h from the
                    // previous tick). Was at refresh() entry — that
                    // version unconditionally promoted even on failure
                    // paths, which broke the initial-fetch retry loop.
                    promoteToHourlyScheduleLocked();
                }
                catch (Exception e)
                {
                    log.debug("LobbyJoinGate refresh: callback threw", e);
                }
                finally
                {
                    refreshing.set(false);
                    fireListenersOnEdt();
                }
            });
    }

    /** Replace the active {@link #autoRefresh} with the long-period
     *  hourly schedule. Called only from the success path of
     *  {@link #refresh()} so first-success transitions us off the
     *  fast-retry cadence and manual refreshes reset the hourly clock
     *  in one place. No-op if logged out (cancelAutoRefreshLocked has
     *  already nulled out the schedule). */
    private synchronized void promoteToHourlyScheduleLocked()
    {
        if (!loggedIn) return;
        cancelAutoRefreshLocked();
        autoRefresh = scheduler.scheduleAtFixedRate(
            this::autoTick,
            AUTO_REFRESH_INTERVAL_MS,
            AUTO_REFRESH_INTERVAL_MS,
            TimeUnit.MILLISECONDS);
    }

    private void applyProfile(JsonObject profile)
    {
        if (profile == null)
        {
            applyAllZero();
            return;
        }
        // Parse is_mod before any cumulative_stats early-return so a
        // mod account still surfaces the [MOD] chip on the self-preview
        // row even when match counts are absent (brand-new account,
        // partial profile payload, etc.). Strict-boolean only — mirrors
        // WebSocketLobbyService.parseMember's wire contract.
        isMod = parseIsModStrict(profile);
        if (!profile.has("cumulative_stats") ||
            !profile.get("cumulative_stats").isJsonObject())
        {
            applyCountsZero();
            return;
        }
        JsonObject cum = profile.getAsJsonObject("cumulative_stats");
        // Per-bucket rank lives in a separate top-level object on the
        // {@code /user} endpoint — NOT inside {@code cumulative_stats}.
        // See {@code PvPDataService.extractTierFromUserResponse}: the
        // per-bucket shape is {@code {"rank": "Adamant", "division":
        // 2, "mmr": ...}} where {@code rank} is the family name and
        // {@code division} is 1–3 (absent / non-1–3 for the
        // single-division "3rd Age" tier). Earlier draft of this
        // method read {@code cumulative_stats.<bucket>.tier} which
        // doesn't exist on this endpoint (only the S3 shard payload
        // has a {@code tier} field) — meaning {@link
        // #rankIdxByStyle} would stay empty and the self-preview
        // row's name rendered in plain white. Fixed by reading from
        // {@code buckets.<bucket>} instead.
        JsonObject buckets = profile.has("buckets") && profile.get("buckets").isJsonObject()
            ? profile.getAsJsonObject("buckets")
            : null;
        EnumMap<Style, Integer> nextCounts = new EnumMap<>(Style.class);
        EnumMap<Style, Integer> nextRanks = new EnumMap<>(Style.class);
        for (Style s : Style.values())
        {
            String bucket = bucketFor(s);
            int total = 0;
            int rankIdx = -1;
            if (bucket != null && cum.has(bucket) && cum.get(bucket).isJsonObject())
            {
                JsonObject b = cum.getAsJsonObject(bucket);
                // Defensive ints — backend has been seen to return both
                // numeric primitives and Decimal-typed values depending
                // on the path through the Lambda; getAsInt() handles
                // both via Gson's coercion.
                int wins = optInt(b, "wins");
                int losses = optInt(b, "losses");
                int ties = optInt(b, "ties");
                total = wins + losses + ties;
                if (total < 0) total = 0;
            }
            if (bucket != null && buckets != null
                && buckets.has(bucket) && buckets.get(bucket).isJsonObject())
            {
                rankIdx = readRankIdxFromBucket(buckets.getAsJsonObject(bucket));
            }
            nextCounts.put(s, total);
            if (rankIdx >= 0) nextRanks.put(s, rankIdx);
        }
        synchronized (counts)
        {
            counts.clear();
            counts.putAll(nextCounts);
            rankIdxByStyle.clear();
            rankIdxByStyle.putAll(nextRanks);
        }
    }

    /** Parses the {@code {rank, division}} pair off a single
     *  {@code buckets.<bucket>} object and returns the
     *  {@link RankUtils#THRESHOLDS} index, or {@code -1} if the
     *  bucket has no rank ("Bronze 3 / 0 MMR" default that the
     *  backend stamps on never-fought buckets — that defaults state
     *  shouldn't pop a rank chip on the self-preview row).
     *
     *  <p>Wire format from {@code PvPDataService.extractTierFromUserResponse}:
     *  {@code rank} is the family ("Bronze".."Dragon" or "3rd Age");
     *  {@code division} is 1-3 or absent. We compose them into the
     *  spaced label form ({@code "Adamant 2"} / {@code "3rd Age"})
     *  before handing off to {@link RankUtils#rankIndexForTier}. */
    private static int readRankIdxFromBucket(JsonObject b)
    {
        if (b == null) return -1;
        String rank = optString(b, "rank");
        if (rank == null || rank.isEmpty()) return -1;
        int division = optInt(b, "division");
        // Default-state bucket ({@code Bronze} family + division 3 +
        // 0 MMR) — surface as "unknown" so a brand-new account
        // doesn't get a misleading Bronze 3 chip on the preview row.
        if ("Bronze".equalsIgnoreCase(rank) && division == 3
            && Math.abs(optDouble(b, "mmr")) < 0.001)
        {
            return -1;
        }
        String composed = (division >= 1 && division <= 3)
            ? rank + " " + division
            : rank;
        try
        {
            return RankUtils.rankIndexForTier(composed);
        }
        catch (UnsupportedOperationException | IllegalStateException e)
        {
            return -1;
        }
    }

    private static String optString(JsonObject o, String key)
    {
        try
        {
            return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : null;
        }
        catch (UnsupportedOperationException | IllegalStateException e)
        {
            return null;
        }
    }

    private static double optDouble(JsonObject o, String key)
    {
        try
        {
            return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsDouble() : 0.0;
        }
        catch (NumberFormatException | UnsupportedOperationException | IllegalStateException e)
        {
            return 0.0;
        }
    }

    private void applyAllZero()
    {
        applyCountsZero();
        isMod = false;
    }

    /** Clears match counts + rank indices without touching {@link #isMod}.
     *  Used when {@code cumulative_stats} is absent but {@code is_mod}
     *  was still parsed from the top-level profile object. */
    private void applyCountsZero()
    {
        synchronized (counts)
        {
            counts.clear();
            for (Style s : Style.values()) counts.put(s, 0);
            // Soft-404 / brand-new player: leave rankIdxByStyle empty.
            // The self-preview row falls back to "rank unknown" and
            // suppresses the rank chip rather than showing a default
            // Bronze 3.
            rankIdxByStyle.clear();
        }
    }

    /** Strict-boolean read of {@code is_mod} from a {@code /user} profile
     *  JSON object. Package-visible for unit tests. */
    static boolean parseIsModStrict(JsonObject profile)
    {
        if (profile == null) return false;
        return profile.has("is_mod")
            && profile.get("is_mod").isJsonPrimitive()
            && profile.get("is_mod").getAsJsonPrimitive().isBoolean()
            && profile.get("is_mod").getAsBoolean();
    }

    private static String bucketFor(Style s)
    {
        // Lowercased style name → cumulative_stats bucket key. Locked
        // to a switch instead of {@code s.name().toLowerCase()} so
        // future enum renames (e.g. NH → "Nh") don't silently break the
        // wire mapping.
        switch (s)
        {
            case NH: return "nh";
            case VENG: return "veng";
            case MULTI: return "multi";
            case DMM: return "dmm";
            default: return null;
        }
    }

    private static int optInt(JsonObject o, String key)
    {
        try
        {
            return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsInt() : 0;
        }
        catch (NumberFormatException | UnsupportedOperationException | IllegalStateException e)
        {
            return 0;
        }
    }

    @Override
    public void addListener(Runnable listener)
    {
        if (listener != null) listeners.add(listener);
    }

    private void fireListenersOnEdt()
    {
        if (listeners.isEmpty()) return;
        if (SwingUtilities.isEventDispatchThread())
        {
            fireListeners();
        }
        else
        {
            SwingUtilities.invokeLater(this::fireListeners);
        }
    }

    private void fireListeners()
    {
        for (Runnable r : listeners)
        {
            try { r.run(); }
            catch (Exception e) { log.debug("LobbyJoinGate listener threw", e); }
        }
    }
}

package com.pvp.leaderboard.lobby;

import java.util.Collections;
import java.util.Map;

/**
 * Pre-lobby gate that tracks the local user's per-style match count and
 * enforces the {@link #THRESHOLD}-match minimum for queueing. Drives the
 * "you need N more kills/deaths in &lt;Style&gt; to queue" UX in
 * {@code MatchmakingLobbyPanel}'s pre-lobby gate.
 *
 * <p><b>"Match count" definition.</b> The count is
 * {@code wins + losses + ties} from the player's
 * {@code cumulative_stats.<bucket>} returned by
 * {@link com.pvp.leaderboard.service.PvPDataService#getUserProfile}. We
 * use the same data the Player Lookup tab already renders so there's a
 * single source of truth (and the user can sanity-check the number by
 * looking up their own profile).
 *
 * <p><b>Refresh cadence.</b> First refresh fires when the local player
 * logs in (driven by {@code PvPLeaderboardPlugin.onGameStateChanged
 * LOGGED_IN}). Auto-refresh repeats every {@link #AUTO_REFRESH_INTERVAL_MS}
 * (1 hour). Users can also force a manual refresh via {@link #refresh()};
 * a manual refresh resets the auto-refresh clock to avoid double-fires.
 *
 * <p><b>Trust boundary.</b> This gate is UX-only — it gives the user
 * immediate feedback without having to attempt a {@code lobby/join} the
 * server would reject. The server enforces the same rule at
 * {@code lobby/join} time; a modified plugin that bypasses this gate
 * still trips the server-side check and receives an
 * {@code error/lobby SMURF_GUARD} response.
 *
 * <p><b>Threading.</b> Listeners fire on the EDT; getters are safe to
 * call from any thread but their return values are point-in-time.
 *
 * @see com.pvp.leaderboard.lobby.UserProfileLobbyJoinGate production impl
 * @see com.pvp.leaderboard.lobby.NoOpLobbyJoinGate test impl + pre-login placeholder
 */
public interface LobbyJoinGate
{
    /** Per-style minimum {@code wins + losses + ties} needed to queue.
     *  Mirror this exactly on the backend's {@code SMURF_GUARD} check —
     *  any drift between client and server would surface as the user
     *  passing the local gate but getting {@code SMURF_GUARD} back from
     *  {@code lobby/join} (or vice versa, which is worse — UI says
     *  "locked" but the server would have let them in). */
    int THRESHOLD = 20;

    /** Auto-refresh cadence — once per hour. Manual {@link #refresh()}
     *  resets this clock so a user who refreshes right before the hourly
     *  tick doesn't see a redundant fetch a moment later. */
    long AUTO_REFRESH_INTERVAL_MS = 60L * 60L * 1000L;

    /** Fast-retry cadence used between {@code onLogin()} and the first
     *  successful refresh. Guards against the failure mode where the
     *  initial fetch bails (name supplier not yet ready, API transient
     *  5xx, network blip) — without a fast retry the user would be
     *  stuck on "Loading your match count…" until the next manual
     *  Refresh click or the 1-hour auto-tick, whichever comes first.
     *  After the first success the production impl switches to
     *  {@link #AUTO_REFRESH_INTERVAL_MS}. */
    long INITIAL_RETRY_INTERVAL_MS = 60L * 1000L;

    /** Snapshot of last-known match counts per {@link Style}. Keys are
     *  only present for styles the gate has fetched a count for —
     *  callers must treat a missing key as "unknown" (render placeholder
     *  text, not 0). Empty map if the gate has never successfully
     *  refreshed (still in pre-login / pre-first-fetch state). */
    Map<Style, Integer> getMatchCounts();

    /** Snapshot of last-known rank index per {@link Style}, indexed
     *  into {@link com.pvp.leaderboard.util.RankUtils#THRESHOLDS}. Used
     *  by the matchmaking panel's self-profile preview row to render
     *  the same rank the player sees on the website + Player Lookup
     *  tab. Priority for the single-rank display is NH > Veng > Multi
     *  > DMM (matches {@link Style} declaration order).
     *
     *  <p>Keys are only present for styles the gate has both a rank
     *  string and a successful tier→index lookup for; callers must
     *  treat a missing key (or value {@code < 0}) as "rank unknown"
     *  and suppress the rank chip rather than rendering "Bronze 3"
     *  (the THRESHOLDS[0] default). Default implementation returns an
     *  empty map so test/no-op gates don't have to opt in. */
    default Map<Style, Integer> getRankIdxByStyle() { return Collections.emptyMap(); }

    /** Epoch ms of the last successful refresh; {@code 0} if never
     *  refreshed. UI uses this to render "Updated N min ago" so the user
     *  knows whether their count is stale. */
    long getLastRefreshEpochMs();

    /** {@code true} while a {@link #refresh()} is in-flight. UI uses
     *  this to debounce the Refresh button (so a frustrated user
     *  hammering it doesn't queue ten parallel fetches). */
    boolean isRefreshing();

    /** {@code true} between {@code onLogin()} and {@code onLogout()} on
     *  the production impl — i.e. while the local OSRS player is in
     *  {@code GameState.LOGGED_IN} and the gate has a player-name to
     *  query against. UI uses this to swap the entire pre-lobby gate
     *  for a "Please log into the game" notice when {@code false} so
     *  the user isn't confronted with style toggles that look broken
     *  / locked for reasons they can't fix from outside the game.
     *
     *  <p>Note this is the <b>game</b> login state, not the website's
     *  Cognito session. A user authenticated to the website but parked
     *  on the OSRS login screen still reports {@code false} here. */
    boolean isLoggedIn();

    /** {@code true} when the local user is a server-recognised
     *  moderator (member of the {@code OSRS-LobbyMods} table on the
     *  backend). Authoritative for the {@code MatchmakingLobbyPanel}
     *  self-preview row's [MOD] chip — the lobby roster server-filters
     *  the viewer's own row out of every push, so this is the only
     *  client-side path that surfaces the local user's own mod status.
     *
     *  <p>Source of truth: parsed off the {@code /user} profile JSON's
     *  {@code is_mod} field on every successful refresh. Default
     *  implementation returns {@code false} so the no-op gate +
     *  test/placeholder gates don't have to opt in (and so a wiring
     *  bug doesn't accidentally promote a regular user). */
    default boolean isMod() { return false; }

    /** Triggers an immediate refresh. No-op if already refreshing.
     *  Listeners fire on entry (so the UI can show "Refreshing…") and
     *  again on completion. Resets the auto-refresh clock. */
    void refresh();

    /** Subscribe to refresh events. Listener fires on the EDT every
     *  time {@link #getMatchCounts()}, {@link #getLastRefreshEpochMs()},
     *  or {@link #isRefreshing()} could have changed. Listeners are not
     *  de-duplicated — adding the same {@code Runnable} twice will fire
     *  it twice. There is no {@code removeListener}: the panel that
     *  registers is a singleton-lifetime collaborator. */
    void addListener(Runnable listener);

    /** Helper: how many more matches the user needs in {@code style}
     *  before they can queue it. Returns 0 if already unlocked, or
     *  {@link #THRESHOLD} if the count is unknown / missing. */
    static int remaining(int count)
    {
        if (count >= THRESHOLD) return 0;
        if (count < 0) return THRESHOLD;
        return THRESHOLD - count;
    }

    /** Helper: is {@code count} sufficient to queue? Counts below 0
     *  (shouldn't happen but defend) treated as unknown → locked. */
    static boolean isUnlocked(int count)
    {
        return count >= THRESHOLD;
    }
}

package com.pvp.leaderboard.lobby;

import java.util.List;
import java.util.Set;

/**
 * Server-push callbacks the panel registers with a {@link LobbyService} via
 * {@link LobbyService#setListener}. Every callback is invoked on Swing's
 * event-dispatch thread (EDT) — implementations of {@link LobbyService}
 * MUST marshal via {@code SwingUtilities.invokeLater} so listeners can
 * directly mutate Swing components.
 *
 * <p>Mirrors the server-to-client lobby command set ({@code lobby/roster},
 * {@code lobby/invite_received}, etc.). Method names follow the
 * {@code onSomething} convention rather than mirroring the wire command
 * names verbatim, because some events have no 1-to-1 wire equivalent
 * (e.g. {@link #onFightConfirmedByPeer} maps to
 * {@code lobby/fight_confirmed_by_peer} but is named for what the panel
 * does with it).
 *
 * <p>All methods are {@code default} no-ops so implementations override
 * only the events they care about (e.g. unit tests that only assert one
 * callback fires).
 */
public interface LobbyEventListener
{
    /** Full roster snapshot pushed after a {@code lobby/join} or whenever
     *  membership changes server-side. The panel coalesces visible roster
     *  updates to one render per 60 s — so this can fire as often as the
     *  server pleases without flickering the UI under the user's cursor.
     *  Replaces members verbatim (no merge / diff). */
    default void onRosterSnapshot(List<LobbyMember> roster) {}

    /** Periodic presence count broadcast (architecture: {@code presence/count}).
     *  Distinct from {@link #onRosterSnapshot} which is the full member list;
     *  this is just a cheap "X players online" header update. */
    default void onPresenceCount(int totalOnline) {}

    /** Someone in the lobby sent the local user an invite. Panel pins an
     *  invite card at the top of the roster with Accept / Decline buttons
     *  and a TTL countdown derived from {@link IncomingInvite#getExpiresAtEpochMs}. */
    default void onIncomingInvite(IncomingInvite invite) {}

    /** An invite was withdrawn server-side (sender cancelled,
     *  block-cascade, leave-cascade, TTL elapsed). Panel removes the
     *  matching card or outgoing chip. */
    default void onIncomingInviteCancelled(String inviteId) {}

    /** The receiver of an invite declined it. Sender-side only.
     *  Panel removes the outgoing chip, exits the fight-setup wizard
     *  if the user was mid-flow against this opponent, and shows an
     *  "Invite declined by {@code declinedByName}" banner. */
    default void onIncomingInviteDeclined(String inviteId, String declinedByName) {}

    /** An invite — either one the local user sent and the opponent
     *  accepted, OR one the local user just accepted — has transitioned to
     *  the 30-s mutual-confirm phase. Panel switches to its ConfirmFight
     *  view. Both players see this event simultaneously. */
    default void onFightProposed(FightSession session) {}

    /** The peer has confirmed the active fight session, but the local user
     *  hasn't yet. Panel flips the ConfirmFight subheader from
     *  "Waiting on other player" to "Confirmed by other player" (or shows
     *  "Confirmed by other player" if the local user is the slow one). */
    default void onFightConfirmedByPeer(String fightSessionId) {}

    /** Both players have confirmed; here's the meeting world and place.
     *  Panel transitions to its terminal Meet-At view. */
    default void onMatchFound(MatchInfo match) {}

    /** The 30-s confirm window elapsed without both players confirming.
     *  Panel returns the user to the lobby with no penalty. */
    default void onFightSessionExpired(String fightSessionId) {}

    /** An operation failed with a stable error code from the server's
     *  error envelope (e.g. {@code INVITE_EXPIRED}, {@code RANK_OUT_OF_RANGE},
     *  {@code BLOCKED}). Panel renders human-readable text via
     *  {@link LobbyErrorMessages} — never the raw code. */
    default void onError(String code, String message) {}

    /** Server's ACK of a {@code lobby/join} cmd. Useful for surfacing
     *  "joined as observer" feedback or starting a session-scoped clock;
     *  the panel currently doesn't render anything off it but the hook
     *  exists for future telemetry. */
    default void onJoinedEcho() {}

    /** Authoritative snapshot of canonical player IDs (lowercased display
     *  names) the local user has blocked. Pushed once on join and after
     *  every block/unblock the server applies. Panel uses this to gray
     *  out matching rows in the roster. */
    default void onBlockListSnapshot(Set<String> blockedPlayerIds) {}

    /** Cross-device delta: the local user (on another device or this one)
     *  just blocked {@code playerId}. Panel adds to its block set and
     *  re-renders the row. Mostly redundant with {@link #onBlockListSnapshot}
     *  since the server also re-pushes the full snapshot, but the delta
     *  arrives first so the UI feels snappier. */
    default void onBlockAdded(String playerId) {}

    /** Cross-device delta inverse of {@link #onBlockAdded}. Panel removes
     *  {@code playerId} from its block set and re-renders the row. */
    default void onBlockRemoved(String playerId) {}

    /** The local user was displaced from the lobby because another account
     *  linked to the same canonical identity (a logged-in alt) joined.
     *  The server has already removed THIS account's lobby membership —
     *  only one linked account can occupy the lobby at a time — so the
     *  panel drops back to the pre-lobby gate and shows an explanatory
     *  notice. The panel must NOT auto-rejoin (that would bounce the alt
     *  back out); the user re-enters deliberately via Go-to-lobby.
     *
     *  <p>{@code activeAccountName} is the display name of the account
     *  that is now the active lobby occupant (may be null/empty when the
     *  server omits it — the panel then shows a generic message). */
    default void onDisplacedByAlt(String activeAccountName) {}
}

package com.pvp.leaderboard.lobby;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

/**
 * One row in the lobby roster. Server is source of truth; the panel
 * only reads this type and never mutates it.
 *
 * <p><b>Identity model</b>:
 * <ul>
 *   <li>{@link #playerId} — canonical, lowercased display name.
 *   Stable wire identifier used as the {@code to_player_id} /
 *   {@code blocked_player_id} value on outbound cmds and as the
 *   panel's map key for outgoing-invite and block-list state.</li>
 *   <li>{@link #name} — the display-cased name the player shows up as
 *   in-game (e.g. {@code "Toyco"} when {@link #playerId} is
 *   {@code "toyco"}). What the UI renders.</li>
 * </ul>
 *
 * <p>Instances are immutable — every field is {@code final} and the
 * {@link #styles}/{@link #builds} sets are wrapped in
 * {@link Collections#unmodifiableSet}.
 */
public final class LobbyMember
{
    /** Sentinel value used by both {@link #minRankIdx} and
     *  {@link #maxRankIdx} when the server has not (yet) pushed the
     *  member's slider settings. Callers must treat either field
     *  equalling this value as "range unknown" and skip the
     *  out-of-their-range greyout — never as "accepts no-one" (which
     *  would incorrectly grey every row on every pre-deploy
     *  build of the backend). */
    public static final int UNKNOWN_RANK_IDX = -1;

    public final String playerId;
    public final String name;
    public final Set<Style> styles;
    public final Set<BuildType> builds;
    /** Current rank index (0..24) for the viewer's sort bucket. Source of
     *  truth for matchmaking — drives the rank-slider filter and is what
     *  the server's RANK_OUT_OF_RANGE check reads on
     *  {@code lobby/invite}. -1 means the server returned no value. */
    public final int currentRankIdx;
    /** All-time peak rank index (0..24) for the viewer's sort bucket. The
     *  big rank label rendered on each card. **Display-only** — never
     *  used as a matchmaking gate. -1 means no peak has been computed
     *  yet (brand-new player with no completed matches in this bucket). */
    public final int peakRankIdx;
    public final String region;
    public final boolean isMod;
    /** Operator matchmaking-suspend stamp from {@code lobby/roster}
     *  ({@code is_suspended}). When {@code true}, every viewer greys
     *  this member's Fight option — the server blocks invite/accept
     *  with {@code MATCHMAKING_SUSPENDED} regardless of rank/block
     *  state. Server-supplied only; defaults to {@code false} when
     *  the field is absent (pre-deploy backend). */
    public final boolean isSuspended;
    /** Lower bound of this member's own accept-invite slider (index into
     *  {@code RANK_LABELS}, inclusive). The plugin compares the
     *  <b>viewer's</b> own rank against {@code [minRankIdx, maxRankIdx]}
     *  to decide whether to grey their row out — when the viewer is
     *  outside this band the member would server-reject any
     *  {@code lobby/invite} with {@code RANK_OUT_OF_RANGE}, so showing
     *  a live [Fight] chip would be misleading.
     *
     *  <p>{@link #UNKNOWN_RANK_IDX} (-1) when the server did not push
     *  the field (pre-deploy build of the lobby backend, or a partial
     *  roster row); the greyout logic interprets that as "range
     *  unknown — show the row normally" so missing data never causes
     *  every row to grey out. */
    public final int minRankIdx;
    /** Upper bound of this member's own accept-invite slider — see
     *  {@link #minRankIdx} for semantics. {@link #UNKNOWN_RANK_IDX}
     *  (-1) when the server did not push the field. */
    public final int maxRankIdx;

    /** Backwards-compatible ctor — defaults the new slider-bound fields
     *  to {@link #UNKNOWN_RANK_IDX}. Kept so test fixtures, the
     *  self-preview builder, and the lookup-row constructors don't
     *  have to thread two more args through every call site. */
    public LobbyMember(String playerId, String name, Set<Style> styles, Set<BuildType> builds,
                       int currentRankIdx, int peakRankIdx, String region, boolean isMod)
    {
        this(playerId, name, styles, builds, currentRankIdx, peakRankIdx, region, isMod,
            false, UNKNOWN_RANK_IDX, UNKNOWN_RANK_IDX);
    }

    public LobbyMember(String playerId, String name, Set<Style> styles, Set<BuildType> builds,
                       int currentRankIdx, int peakRankIdx, String region, boolean isMod,
                       int minRankIdx, int maxRankIdx)
    {
        this(playerId, name, styles, builds, currentRankIdx, peakRankIdx, region, isMod,
            false, minRankIdx, maxRankIdx);
    }

    public LobbyMember(String playerId, String name, Set<Style> styles, Set<BuildType> builds,
                       int currentRankIdx, int peakRankIdx, String region, boolean isMod,
                       boolean isSuspended, int minRankIdx, int maxRankIdx)
    {
        this.playerId = playerId;
        this.name = name;
        this.styles = styles == null
            ? Collections.unmodifiableSet(EnumSet.noneOf(Style.class))
            : Collections.unmodifiableSet(EnumSet.copyOf(styles));
        this.builds = builds == null
            ? Collections.unmodifiableSet(EnumSet.noneOf(BuildType.class))
            : Collections.unmodifiableSet(EnumSet.copyOf(builds));
        this.currentRankIdx = currentRankIdx;
        this.peakRankIdx = peakRankIdx;
        this.region = region;
        this.isMod = isMod;
        this.isSuspended = isSuspended;
        this.minRankIdx = minRankIdx;
        this.maxRankIdx = maxRankIdx;
    }

    /** Compact style-flag string ("NVMD" if all four styles are set).
     *  Order follows {@link Style} declaration order. */
    public String styleFlags()
    {
        StringBuilder sb = new StringBuilder();
        for (Style s : Style.values())
        {
            if (styles.contains(s)) sb.append(s.label.charAt(0));
        }
        return sb.toString();
    }
}

package com.pvp.leaderboard.lobby;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.logging.Level;
import java.util.logging.Logger;
import net.runelite.client.config.ConfigManager;

/**
 * Persisted lobby gate preferences — region, advertised styles, advertised
 * builds, rank slider bounds, a "user already finished gate setup" sticky
 * flag, and a "user explicitly left the lobby" opt-out flag (suppresses
 * zero-config auto-join until a manual re-join).
 *
 * <p>The matchmaking panel reads through this on construction so a user who
 * has previously completed the gate is dropped straight into the lobby on
 * subsequent logins, with their picks pre-restored. {@link
 * com.pvp.leaderboard.ui.MatchmakingLobbyPanel#resetGateOptions()} writes
 * through to {@link #clear()} so the explicit "I want to re-pick" path
 * forgets everything.
 *
 * <p>Backed by RuneLite's {@link ConfigManager} — the values land in the
 * active RuneLite profile's config alongside the existing
 * {@code PvPLeaderboard.*} settings. The keys deliberately don't carry
 * {@code @ConfigItem} annotations because we don't want them to surface in
 * the RuneLite settings panel; they're hidden runtime state, not a user
 * setting.
 *
 * <p>An {@link #inMemory()} factory returns a no-op variant that keeps the
 * panel building without a real {@code ConfigManager} (unit tests, the
 * existing {@link com.pvp.leaderboard.lobby.NoOpLobbyService}-only call
 * sites). The in-memory variant simulates a fresh "no preferences yet" user
 * — every getter returns its supplied default and setters write to a local
 * map that's discarded when the JVM exits.
 */
@Singleton
public class LobbyPreferences
{
    private static final Logger LOG = Logger.getLogger(LobbyPreferences.class.getName());

    /** Same group used by {@link com.pvp.leaderboard.config.PvPLeaderboardConfig}
     *  so the values share a profile namespace with the existing
     *  user-facing settings. */
    public static final String CONFIG_GROUP = "PvPLeaderboard";

    public static final String KEY_REGION = "lobbyRegion";
    public static final String KEY_STYLES = "lobbyStyles";
    public static final String KEY_BUILDS = "lobbyBuilds";
    public static final String KEY_MIN_RANK_IDX = "lobbyMinRankIdx";
    public static final String KEY_MAX_RANK_IDX = "lobbyMaxRankIdx";
    public static final String KEY_HAS_JOINED = "lobbyHasJoined";
    /** Sticky "user explicitly left the lobby" opt-out. When {@code true}
     *  the panel suppresses zero-config auto-join until the user manually
     *  re-joins via the gate's Go-to-lobby button. Set by Leave Lobby,
     *  cleared by a manual Go-to-lobby. */
    public static final String KEY_USER_LEFT = "lobbyUserLeft";

    /** Aggregated list so {@link #clear()} can wipe in one loop without
     *  drifting from the constants above. */
    private static final String[] ALL_KEYS = {
        KEY_REGION, KEY_STYLES, KEY_BUILDS,
        KEY_MIN_RANK_IDX, KEY_MAX_RANK_IDX, KEY_HAS_JOINED, KEY_USER_LEFT,
    };

    /** {@code null} ⇒ in-memory mode. */
    private final ConfigManager configManager;
    /** Backing store for in-memory mode. {@code null} when {@link #configManager}
     *  is non-null — we always use one or the other. */
    private final Map<String, String> inMemoryStore;

    @Inject
    public LobbyPreferences(ConfigManager configManager)
    {
        this.configManager = configManager;
        this.inMemoryStore = null;
    }

    private LobbyPreferences()
    {
        this.configManager = null;
        this.inMemoryStore = new HashMap<>();
    }

    /** No-persistence variant for unit tests + null-config call sites. The
     *  returned instance behaves identically to a fresh user (every getter
     *  returns its supplied default until a setter is called); writes are
     *  scoped to the returned instance and never escape the JVM. */
    public static LobbyPreferences inMemory()
    {
        return new LobbyPreferences();
    }

    // -------------------- Region --------------------

    public String getRegion(String defaultValue)
    {
        String raw = readRaw(KEY_REGION);
        return (raw == null || raw.isEmpty()) ? defaultValue : raw;
    }

    public void setRegion(String region)
    {
        writeRaw(KEY_REGION, region == null ? "" : region);
    }

    // -------------------- Styles --------------------

    /** Returns the persisted style set, or {@code defaultStyles} (defensively
     *  copied) when nothing is persisted yet. Unknown enum names in the
     *  persisted CSV are silently dropped — handles the case where an old
     *  plugin version persisted a style that no longer exists. */
    public Set<Style> getStyles(Set<Style> defaultStyles)
    {
        String raw = readRaw(KEY_STYLES);
        if (raw == null || raw.isEmpty())
        {
            return defaultStyles == null
                ? EnumSet.noneOf(Style.class)
                : EnumSet.copyOf(defaultStyles);
        }
        EnumSet<Style> out = EnumSet.noneOf(Style.class);
        for (String token : raw.split(","))
        {
            String trimmed = token.trim();
            if (trimmed.isEmpty()) continue;
            try
            {
                out.add(Style.valueOf(trimmed));
            }
            catch (IllegalArgumentException ignored)
            {
                // Ignore unknown enum names — preserves forward/backward
                // compat across plugin versions.
            }
        }
        return out;
    }

    public void setStyles(Set<Style> styles)
    {
        writeRaw(KEY_STYLES, encodeEnumSet(styles));
    }

    // -------------------- Builds --------------------

    public Set<BuildType> getBuilds(Set<BuildType> defaultBuilds)
    {
        String raw = readRaw(KEY_BUILDS);
        if (raw == null || raw.isEmpty())
        {
            return defaultBuilds == null
                ? EnumSet.noneOf(BuildType.class)
                : EnumSet.copyOf(defaultBuilds);
        }
        EnumSet<BuildType> out = EnumSet.noneOf(BuildType.class);
        for (String token : raw.split(","))
        {
            String trimmed = token.trim();
            if (trimmed.isEmpty()) continue;
            try
            {
                out.add(BuildType.valueOf(trimmed));
            }
            catch (IllegalArgumentException ignored)
            {
            }
        }
        return out;
    }

    public void setBuilds(Set<BuildType> builds)
    {
        writeRaw(KEY_BUILDS, encodeEnumSet(builds));
    }

    // -------------------- Rank slider --------------------

    public int getMinRankIdx(int defaultValue)
    {
        return readInt(KEY_MIN_RANK_IDX, defaultValue);
    }

    public void setMinRankIdx(int idx)
    {
        writeRaw(KEY_MIN_RANK_IDX, Integer.toString(idx));
    }

    public int getMaxRankIdx(int defaultValue)
    {
        return readInt(KEY_MAX_RANK_IDX, defaultValue);
    }

    public void setMaxRankIdx(int idx)
    {
        writeRaw(KEY_MAX_RANK_IDX, Integer.toString(idx));
    }

    // -------------------- Has-joined sticky --------------------

    public boolean getHasJoined()
    {
        String raw = readRaw(KEY_HAS_JOINED);
        return "true".equalsIgnoreCase(raw);
    }

    public void setHasJoined(boolean joined)
    {
        writeRaw(KEY_HAS_JOINED, Boolean.toString(joined));
    }

    // -------------------- User-left sticky opt-out --------------------

    /** {@code true} once the user clicked Leave Lobby and hasn't manually
     *  re-joined since. Defaults to {@code false} (fresh user / after a
     *  {@link #clear()}) so a brand-new user is eligible for zero-config
     *  auto-join. */
    public boolean getUserLeftLobby()
    {
        String raw = readRaw(KEY_USER_LEFT);
        return "true".equalsIgnoreCase(raw);
    }

    public void setUserLeftLobby(boolean left)
    {
        writeRaw(KEY_USER_LEFT, Boolean.toString(left));
    }

    // -------------------- Wipe --------------------

    /** Wipes every persisted lobby preference. Called by Reset Options so
     *  the user is dropped back at a "first launch" gate on next login.
     *  Idempotent — safe to call when nothing has been persisted yet. */
    public void clear()
    {
        for (String key : ALL_KEYS)
        {
            writeRaw(key, null);
        }
    }

    /** Read-only view of the in-memory store, for tests / debugging. Returns
     *  {@link Collections#emptyMap()} in {@link ConfigManager}-backed mode
     *  since the underlying store is not introspectable through this class. */
    public Map<String, String> snapshotInMemoryForTest()
    {
        return inMemoryStore == null
            ? Collections.emptyMap()
            : Collections.unmodifiableMap(new HashMap<>(inMemoryStore));
    }

    // -------------------- Internals --------------------

    private String readRaw(String key)
    {
        try
        {
            if (configManager != null)
            {
                return configManager.getConfiguration(CONFIG_GROUP, key);
            }
            return inMemoryStore.get(key);
        }
        catch (RuntimeException e)
        {
            LOG.log(Level.WARNING, "LobbyPreferences read failed for key " + key, e);
            return null;
        }
    }

    private void writeRaw(String key, String value)
    {
        try
        {
            if (configManager != null)
            {
                if (value == null)
                {
                    configManager.unsetConfiguration(CONFIG_GROUP, key);
                }
                else
                {
                    configManager.setConfiguration(CONFIG_GROUP, key, value);
                }
                return;
            }
            if (value == null)
            {
                inMemoryStore.remove(key);
            }
            else
            {
                inMemoryStore.put(key, value);
            }
        }
        catch (RuntimeException e)
        {
            LOG.log(Level.WARNING, "LobbyPreferences write failed for key " + key, e);
        }
    }

    private int readInt(String key, int defaultValue)
    {
        String raw = readRaw(key);
        if (raw == null || raw.isEmpty()) return defaultValue;
        try
        {
            return Integer.parseInt(raw.trim());
        }
        catch (NumberFormatException e)
        {
            return defaultValue;
        }
    }

    private static <E extends Enum<E>> String encodeEnumSet(Set<E> set)
    {
        if (set == null || set.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (E e : set)
        {
            if (sb.length() > 0) sb.append(',');
            sb.append(e.name());
        }
        return sb.toString();
    }
}

package com.pvp.leaderboard.lobby;

import java.util.Collections;
import java.util.Map;

/**
 * Inert {@link LobbyJoinGate} used in two contexts:
 *
 * <ol>
 *   <li><b>Tests</b> — {@code DashboardPanelTest} and other panel tests
 *   pass this when they don't care about the gate's behaviour, just that
 *   the panel constructs without an NPE.</li>
 *   <li><b>Defensive fallback</b> — if {@code DashboardPanel} is ever
 *   constructed without a gate (e.g. a future refactor that drops the
 *   ctor arg by accident), the panel substitutes this rather than crash.
 *   It reports every style as unlocked so the user isn't locked out by
 *   a wiring bug.</li>
 * </ol>
 *
 * <p>"Unlocked" is conveyed by returning {@link LobbyJoinGate#THRESHOLD}
 * (i.e. exactly the threshold) for every style — that's the safest
 * default because the server-side {@code SMURF_GUARD} is the authoritative
 * check. A misbehaving local gate that says "unlocked" just means the
 * server gets the final word.
 */
public final class NoOpLobbyJoinGate implements LobbyJoinGate
{
    private final Map<Style, Integer> counts;

    public NoOpLobbyJoinGate()
    {
        java.util.EnumMap<Style, Integer> m = new java.util.EnumMap<>(Style.class);
        for (Style s : Style.values()) m.put(s, THRESHOLD);
        this.counts = Collections.unmodifiableMap(m);
    }

    @Override public Map<Style, Integer> getMatchCounts() { return counts; }
    @Override public long getLastRefreshEpochMs() { return 0L; }
    @Override public boolean isRefreshing() { return false; }
    /** Always {@code true} — the NoOp is used in tests + as the
     *  fallback when no real gate was wired in; in both contexts we
     *  don't want to hide the panel behind "Please log into the game".
     *  Tests render the lobby UI deterministically regardless of
     *  game-state, and the fallback path implies a wiring bug already
     *  (no reason to make it worse by hiding the panel). */
    @Override public boolean isLoggedIn() { return true; }
    @Override public void refresh() { /* no-op */ }
    @Override public void addListener(Runnable listener) { /* no-op */ }
}

package com.pvp.leaderboard.lobby;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pvp.leaderboard.service.PvPDataService;
import com.pvp.leaderboard.service.ShardRank;
import com.pvp.leaderboard.service.socket.SocketEventBus;
import com.pvp.leaderboard.service.socket.WebSocketManager;
import com.pvp.leaderboard.util.RankUtils;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Production {@link LobbyService} that adapts the wire protocol to the
 * panel's domain types.
 *
 * <p>Two key concerns this class owns:
 * <ol>
 *   <li><b>Wire ↔ domain marshalling</b>: server pushes are flat (e.g.
 *   {@code lobby/invite_received} carries
 *   {@code from_player_id + from_name + sender_styles + ...}, not a
 *   nested {@code sender} object). This service holds an in-memory
 *   roster cache keyed by canonical {@code player_id} and reconstructs
 *   {@link LobbyMember} instances for the panel's nested
 *   {@link IncomingInvite#sender} / {@link FightSession#opponent} /
 *   {@link MatchInfo#opponent} fields. If a flat payload references a
 *   player id not in the cache (rare — only if the push arrives before
 *   the {@code lobby/roster} that introduced the member), the service
 *   falls back to a synthetic {@link LobbyMember} built from whatever
 *   fields the push carried.</li>
 *
 *   <li><b>Reconnect re-join</b>: caches the last {@link #joinLobby}
 *   args and re-sends them via {@link WebSocketManager#addConnectListener}
 *   on every socket open so server-side state rebuilds without the
 *   panel knowing about reconnects.</li>
 * </ol>
 *
 * <p><b>Threading</b>: server pushes arrive on OkHttp's dispatcher
 * thread via {@link SocketEventBus}; this service marshals every
 * {@link LobbyEventListener} callback through
 * {@link SwingUtilities#invokeLater} per the {@link LobbyService}
 * contract. The injected {@link WebSocketManager} is thread-safe and
 * {@link #send(String, JsonObject)} just hands off to its internal
 * {@code WebSocket.send(String)} which is thread-safe.
 *
 * <p><b>Leave-cascade fast-path</b>: when another member's leave
 * invalidates this viewer's filtered roster the server pushes
 * {@code lobby/roster {members: null, stale: true}}. This service
 * re-issues {@code lobby/join} so the server rebuilds + repushes.
 */
@Slf4j
@Singleton
public class WebSocketLobbyService implements LobbyService
{
    private final WebSocketManager socket;
    private final SocketEventBus bus;
    /** Used to look up each lobby member's rank from the leaderboard
     *  shard files on the CDN. The {@code lobby/roster} push from the
     *  server intentionally does NOT carry a usable rank field; the
     *  plugin treats {@code OSRS-LobbyMembers} as a pure presence
     *  table and resolves rank client-side via the shard URLs at
     *  {@code https://pvp-leaderboard.com/rank_idx/<bucket>/<3-char-prefix>.json}.
     *  Keeping the rank source out-of-band lets the lobby ride a
     *  thinner socket payload AND reuses the same CDN-cached shard
     *  data the overhead-rank overlay already pulls — one cache, one
     *  source of truth, regenerated by the backend at its own cadence. */
    private final PvPDataService pvpDataService;

    /** Drives the {@link #retryUnresolvedRanks()} ticker. Optional —
     *  null when the service is constructed via the test/no-scheduler
     *  path; the periodic retry is then disabled and the panel relies
     *  on roster pushes + explicit
     *  {@link #refreshRankForPlayer(String)} calls for rank updates. */
    private final ScheduledExecutorService scheduler;

    /** Retry interval for roster members whose rank is still
     *  {@code -1} ("Waiting") after the initial shard pass. The shard
     *  generator can run with a multi-minute lag behind the lobby
     *  membership table, so a freshly-joined account or one whose
     *  match just landed shows up in the lobby before the shard
     *  carries them. PvPDataService's negative-player cache
     *  ({@code missingPlayerUntilMs}) defaults to a 1-hour TTL, which
     *  is far too long for an active lobby session — the periodic
     *  retry clears those entries and re-runs enrichment so a
     *  catch-up shard publication recovers the row without forcing
     *  the user to relog. */
    private static final long RANK_RETRY_INTERVAL_MS = 60_000L;

    /** Cache TTL for per-(player, bucket) resolved rank indices. The
     *  backend's shard generator publishes new ranks at a ~1 h
     *  cadence (matches the {@code SHARD_CACHE_EXPIRY_MS} TTL in
     *  {@link PvPDataService#getShard}), so caching the resolved
     *  rank for the same window means a player's row only needs a
     *  shard lookup ONCE per session per hour — every subsequent
     *  {@code lobby/roster} push reuses the cached index for free.
     *
     *  <p>This addresses the QA-reported "shard lookups way too
     *  frequent" issue (2026-05-24): with 60+ roster members and
     *  back-to-back roster pushes (e.g. server-side cascade on a
     *  join/leave), the prior implementation re-dispatched a
     *  {@code getShardRankByName} future for every member on every
     *  push, even though the underlying shard JSON was already
     *  cached in-process. Even cheap futures+map-walks add up to
     *  visible UI hitches and a flood of debug logs. */
    private static final long RESOLVED_RANK_CACHE_TTL_MS = 60L * 60L * 1000L;

    /** Resolved-rank cache entry. {@code rankIdx} only stores
     *  successful resolutions ({@code >= 0}); we intentionally do
     *  NOT cache the {@code -1} "Waiting" sentinel here — those rows
     *  are owned by the periodic {@link #retryUnresolvedRanks()}
     *  ticker which clears
     *  {@link PvPDataService#clearShardNegativeCache(String)} and
     *  re-runs enrichment. {@code resolvedAtMs} is the wall-clock
     *  instant the entry was first cached so the TTL check can run
     *  without per-entry timer threads. */
    private static final class ResolvedRankEntry
    {
        final int rankIdx;
        final long resolvedAtMs;

        ResolvedRankEntry(int rankIdx, long resolvedAtMs)
        {
            this.rankIdx = rankIdx;
            this.resolvedAtMs = resolvedAtMs;
        }

        boolean isFresh(long nowMs)
        {
            return (nowMs - resolvedAtMs) < RESOLVED_RANK_CACHE_TTL_MS;
        }
    }

    /** Cache keyed by {@code canonicalName + ":" + bucket} → resolved
     *  rank index. Survives roster churn within a session (entries
     *  aren't cleared when a player leaves the roster — if they
     *  rejoin within the TTL we still get the cache hit). Cleared by
     *  {@link #refreshRankForPlayer(String)} for explicit refresh,
     *  and on plugin restart (in-memory only). */
    private final Map<String, ResolvedRankEntry> resolvedRankCache = new ConcurrentHashMap<>();

    /** Handle for the periodic {@link #retryUnresolvedRanks()} task,
     *  scheduled from {@link #start()}. Null when no scheduler was
     *  injected or before {@link #start()} ran. */
    private ScheduledFuture<?> rankRetryHandle;

    /** Monotonic version of the most-recent roster snapshot. Used to
     *  discard stale shard-enrichment callbacks: when a new
     *  {@code lobby/roster} arrives mid-enrichment, the previous
     *  enrichment pass's completion is ignored so the panel never
     *  sees a roster older than the latest server snapshot. */
    private final AtomicLong rosterVersion = new AtomicLong();

    /**
     * Roster cache keyed by canonical {@code player_id}. Updated wholesale
     * on every {@code lobby/roster} (not merged — the server's snapshot
     * is authoritative). Read on every flat-payload push to enrich
     * {@code LobbyMember} fields. {@link ConcurrentHashMap} for the
     * snapshot-on-OkHttp-thread + lookup-on-OkHttp-thread access
     * pattern; lookups never race a snapshot write because both happen
     * on the same dispatcher thread, but the map is shared in case a
     * future refactor moves the snapshot write off-thread.
     */
    private final Map<String, LobbyMember> rosterByPlayerId = new ConcurrentHashMap<>();

    /** Block-list snapshot, mirroring {@code lobby/block_list_snapshot}
     *  + the {@code lobby/block_added}/{@code lobby/block_removed}
     *  deltas. Keys are canonical lowercase player ids. Exposed to the
     *  panel via {@link LobbyEventListener#onBlockListSnapshot}. */
    private final Set<String> blockedPlayerIds = ConcurrentHashMap.newKeySet();

    /** Last successful (sent — not necessarily ACKed) join args, replayed
     *  on every reconnect. {@code null} until the first {@link #joinLobby}. */
    private volatile JoinArgs lastJoinArgs;

    /** Buffered {@code fight_session_id} awaiting a healthy socket so its
     *  {@code lobby/confirm} can finally land. Populated by
     *  {@link #confirmFight()} when the socket is closed at send time
     *  (e.g. the user clicked Confirm Fight during the 1-3 s window
     *  between {@code onClose} and the next {@code onOpen}); flushed
     *  by {@link #flushPendingConfirm()} from the connect listener and
     *  cleared by {@link #handleFightProposed}, {@link #handleMatchFound},
     *  and {@link #handleSessionExpired} when the session it refers to
     *  is no longer current. {@code volatile} since
     *  {@code WebSocketManager} invokes the connect listener on the
     *  OkHttp dispatcher thread while {@code confirmFight()} is called
     *  from the Swing EDT. */
    private volatile String pendingConfirmFightSessionId;

    private volatile LobbyEventListener listener;
    private volatile boolean started = false;

    /** Throttle bookkeeping for {@link #updateRankRange(int, int)}.
     *  See the field docs for the throttle algorithm:
     *  <ul>
     *    <li>{@link #lastRangeUpdateAtMs} — wall-clock of the last
     *        sent {@code lobby/update_range} (or {@code lobby/join}
     *        which carries the same fields and resets the throttle so
     *        we don't double-fire immediately after a fresh join).</li>
     *    <li>{@link #pendingRangeMin} / {@link #pendingRangeMax} —
     *        latest values the user has scrubbed to; sent on the
     *        trailing-edge of the throttle when a queued send
     *        finally fires. Read on the scheduler thread, written on
     *        the EDT.</li>
     *    <li>{@link #pendingRangeSendScheduled} — guards against
     *        scheduling more than one trailing-edge send per cool-down
     *        window. Cleared when the scheduled task actually fires.</li>
     *  </ul>
     *  All four are {@code volatile} since the EDT writes them and
     *  the scheduler thread reads them. */
    private volatile long lastRangeUpdateAtMs = 0L;
    private volatile int pendingRangeMin = LobbyMember.UNKNOWN_RANK_IDX;
    private volatile int pendingRangeMax = LobbyMember.UNKNOWN_RANK_IDX;
    private volatile boolean pendingRangeSendScheduled = false;

    @Inject
    public WebSocketLobbyService(WebSocketManager socket, SocketEventBus bus,
                                 PvPDataService pvpDataService,
                                 ScheduledExecutorService scheduler)
    {
        this.socket = socket;
        this.bus = bus;
        this.pvpDataService = pvpDataService;
        this.scheduler = scheduler;
    }

    /** Test/no-scheduler constructor preserved so unit tests that
     *  don't exercise the periodic rank-retry can construct the
     *  service without standing up a real executor. The periodic
     *  retry is disabled in this mode; explicit
     *  {@link #refreshRankForPlayer(String)} calls still work. */
    public WebSocketLobbyService(WebSocketManager socket, SocketEventBus bus,
                                 PvPDataService pvpDataService)
    {
        this(socket, bus, pvpDataService, null);
    }

    @Override
    public void setListener(LobbyEventListener listener)
    {
        this.listener = listener;
    }

    @Override
    public synchronized void start()
    {
        if (started) return;
        started = true;
        bus.register("lobby/joined",                  this::handleJoinedEcho);
        bus.register("lobby/roster",                  this::handleRoster);
        bus.register("lobby/block_list_snapshot",     this::handleBlockListSnapshot);
        bus.register("lobby/block_added",             this::handleBlockAdded);
        bus.register("lobby/block_removed",           this::handleBlockRemoved);
        bus.register("lobby/invite_received",         this::handleInviteReceived);
        bus.register("lobby/invite_cancelled",        this::handleInviteCancelled);
        bus.register("lobby/fight_proposed",          this::handleFightProposed);
        bus.register("lobby/fight_confirmed_by_peer", this::handleFightConfirmedByPeer);
        bus.register("lobby/match_found",             this::handleMatchFound);
        bus.register("lobby/session_expired",         this::handleSessionExpired);
        bus.register("lobby/displaced",               this::handleDisplaced);
        bus.register("error/lobby",                   this::handleError);
        // Single connect listener — runs both reconnect-resilience
        // hooks in deterministic order: re-issue lobby/join first
        // (restores server-side presence) then flush any
        // buffered-during-reconnect lobby/confirm so the buffered
        // confirm lands against a current OSRS-Connections row.
        // Consolidated into one Runnable rather than two
        // addConnectListener calls so existing test helpers that
        // assert exactly one listener registration continue to work.
        socket.addConnectListener(this::onSocketReconnected);

        // Periodic retry for roster members stuck on "Waiting" (rank
        // index -1). The shard generator can lag the lobby membership
        // by minutes; without this retry, any row that missed the
        // initial enrichment pass would stay grey for the full lobby
        // session (PvPDataService's negative-player cache is 1 h by
        // default). Disabled when no scheduler was injected (test
        // constructor path); the panel can still call
        // refreshRankForPlayer() directly for explicit refreshes.
        if (scheduler != null)
        {
            rankRetryHandle = scheduler.scheduleAtFixedRate(
                this::retryUnresolvedRanks,
                RANK_RETRY_INTERVAL_MS,
                RANK_RETRY_INTERVAL_MS,
                TimeUnit.MILLISECONDS);
        }
    }

    /** Combined connect-listener: replays the last {@code lobby/join}
     *  then flushes any buffered {@code lobby/confirm}. See the field
     *  docs for {@link #lastJoinArgs} and
     *  {@link #pendingConfirmFightSessionId} for the why. Runs on
     *  OkHttp's dispatcher thread. */
    private void onSocketReconnected()
    {
        replayJoinOnReconnect();
        flushPendingConfirm();
    }

    @Override
    public synchronized void stop()
    {
        // Cancel the periodic rank-retry task scheduled in start().
        // The injected ScheduledExecutorService is RuneLite's shared
        // client-wide executor, which outlives this service — a
        // leaked scheduleAtFixedRate task would keep firing
        // retryUnresolvedRanks() for the lifetime of the client (and
        // double up on a plugin re-toggle). Best-effort,
        // non-interrupting cancel: the task body is short and
        // self-contained so letting an in-flight run finish is
        // harmless. Cleared to null so a repeated stop() is a no-op.
        ScheduledFuture<?> handle = rankRetryHandle;
        if (handle != null)
        {
            handle.cancel(false);
            rankRetryHandle = null;
        }
        // Bus registrations are intentionally left in place — the bus
        // has no unregister API and re-using the service across panel
        // open/close cycles is the desired behaviour (server-side
        // membership persists for 30 min sliding TTL). The socket
        // itself is torn down separately by the plugin shutdown
        // handler.
    }

    // ---------------------------------------------------------------
    // Outbound: panel -> server
    // ---------------------------------------------------------------

    @Override
    public void joinLobby(String region, Set<Style> styles, Set<BuildType> builds,
                          int minDisplayRankIdx, int maxDisplayRankIdx, String sortBucket)
    {
        // Normalise + default the bucket so a bad/empty caller-supplied
        // value can't reach the wire as a non-string. Allowed buckets
        // mirror backend.core.lobby.ALLOWED_BUCKETS = {"overall", "nh",
        // "veng", "multi", "dmm"}; anything else collapses to
        // "overall" so the server's bucket validator can't trip.
        String normBucket = (sortBucket == null) ? "overall" : sortBucket.trim().toLowerCase();
        switch (normBucket)
        {
            case "overall": case "nh": case "veng": case "multi": case "dmm":
                break;
            default:
                normBucket = "overall";
        }
        lastJoinArgs = new JoinArgs(region, styles, builds, minDisplayRankIdx, maxDisplayRankIdx, normBucket);
        log.debug("WebSocketLobbyService: joinLobby region={} styles={} builds={} rankRange=[{},{}] bucket={}",
            region, styles, builds, minDisplayRankIdx, maxDisplayRankIdx, normBucket);
        JsonObject d = new JsonObject();
        d.addProperty("region", region == null ? "" : region.toLowerCase());
        d.add("styles", toJsonArray(stylesToWire(styles)));
        d.add("builds", toJsonArray(buildsToWire(builds)));
        d.addProperty("min_rank_idx", minDisplayRankIdx);
        d.addProperty("max_rank_idx", maxDisplayRankIdx);
        d.addProperty("sort_bucket", normBucket);
        socket.send("lobby/join", d);
        // lobby/join carries min_rank_idx + max_rank_idx so it counts
        // as a freshly-sent range update for throttling purposes — a
        // user who joins then immediately tweaks the slider shouldn't
        // double-fire a redundant update_range inside the cool-down
        // window. The clock reset also covers the auto-rejoin path.
        lastRangeUpdateAtMs = currentTimeMillis();
        pendingRangeMin = minDisplayRankIdx;
        pendingRangeMax = maxDisplayRankIdx;
    }

    @Override
    public void updateRankRange(int minRankIdx, int maxRankIdx)
    {
        // Always record the latest values so a trailing-edge send
        // (scheduled below) picks up the most-recent state regardless
        // of how many intermediate calls land inside the cool-down.
        pendingRangeMin = minRankIdx;
        pendingRangeMax = maxRankIdx;
        long now = currentTimeMillis();
        long since = now - lastRangeUpdateAtMs;
        if (since >= RANGE_UPDATE_MIN_INTERVAL_MS)
        {
            sendRangeUpdateNow(minRankIdx, maxRankIdx, now);
            return;
        }
        // Inside the cool-down window — coalesce. Schedule a single
        // trailing-edge fire at the end of the window (idempotent
        // via {@link #pendingRangeSendScheduled}) so a drag with N
        // commits collapses to two sends total: the leading edge and
        // one trailing edge with the final value.
        if (scheduler == null) return;
        if (pendingRangeSendScheduled) return;
        pendingRangeSendScheduled = true;
        long delayMs = Math.max(0L, RANGE_UPDATE_MIN_INTERVAL_MS - since);
        scheduler.schedule(this::flushPendingRangeUpdate, delayMs, TimeUnit.MILLISECONDS);
    }

    /** Trailing-edge fire scheduled by {@link #updateRankRange}. Reads
     *  the latest pending values + sends them, then clears the
     *  scheduled flag so the next leading-edge can re-arm. Idempotent
     *  if no values changed since the leading edge — still sends so
     *  the server has the user's authoritative-at-end-of-drag value
     *  (cheap; one extra frame per drag burst). */
    private void flushPendingRangeUpdate()
    {
        try
        {
            int min = pendingRangeMin;
            int max = pendingRangeMax;
            sendRangeUpdateNow(min, max, currentTimeMillis());
        }
        finally
        {
            pendingRangeSendScheduled = false;
        }
    }

    private void sendRangeUpdateNow(int minRankIdx, int maxRankIdx, long nowMs)
    {
        lastRangeUpdateAtMs = nowMs;
        JsonObject d = new JsonObject();
        d.addProperty("min_rank_idx", minRankIdx);
        d.addProperty("max_rank_idx", maxRankIdx);
        socket.send("lobby/update_range", d);
        // Also keep lastJoinArgs in sync so a reconnect-replay
        // re-issues lobby/join with the freshest range — otherwise
        // a socket drop after a drag-without-rejoin would silently
        // restore the user's previous range on the server.
        JoinArgs prev = lastJoinArgs;
        if (prev != null)
        {
            lastJoinArgs = new JoinArgs(prev.region, prev.styles, prev.builds,
                minRankIdx, maxRankIdx, prev.sortBucket);
        }
    }

    /** Indirection over {@link System#currentTimeMillis()} so tests
     *  can pin the clock without freezing the JVM's. Override by
     *  package-private subclass in tests. */
    long currentTimeMillis()
    {
        return System.currentTimeMillis();
    }

    @Override
    public void leaveLobby(boolean preserveReplayState)
    {
        // Two distinct call sites with different semantics:
        //   - "Reset Options" / plugin shutdown -> preserveReplayState=false:
        //     the user genuinely wants to leave; nuking lastJoinArgs
        //     ensures a future reconnect doesn't silently re-join them.
        //   - LOGIN_SCREEN transition -> preserveReplayState=true:
        //     the socket is closing because the user dropped to the
        //     login screen, but they're about to log back in. The
        //     server-side row must be removed (so peers stop seeing a
        //     dead invite target — $disconnect doesn't cascade to
        //     leave_lobby today) but the next $connect's onOpen needs
        //     to find lastJoinArgs populated so replayJoinOnReconnect
        //     re-issues lobby/join automatically.
        if (!preserveReplayState) lastJoinArgs = null;
        socket.send("lobby/leave", new JsonObject());
    }

    @Override
    public void sendInvite(LobbyMember opponent, Style style, BuildType build, String location)
    {
        if (opponent == null || style == null || build == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("to_player_id", opponent.playerId);
        d.addProperty("style", style.name().toLowerCase());
        d.addProperty("build", build.name().toLowerCase());
        // Wire-protocol boundary: convert the picker's display string
        // ("Arena" / "Wildy" / "FFA Portal" / "Wilderness" /
        // "Clan Wars", or null for Veng/DMM) into the canonical wire
        // enum the backend's ALLOWED_LOCATIONS_BY_STYLE expects
        // ("arena" / "wildy" / "ffa" / "wilderness" / "clan_wars" /
        // "none"). Without this the server rejects NH→FFA Portal,
        // Multi→Clan Wars, Veng, and DMM with INVALID_LOCATION
        // before the row is even minted (operator report 2026-05-25).
        d.addProperty("location",
            LobbyLocationCodec.toCanonical(style, location));
        socket.send("lobby/invite", d);
    }

    @Override
    public void cancelInvite(LobbyMember opponent)
    {
        if (opponent == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("to_player_id", opponent.playerId);
        socket.send("lobby/cancel_invite", d);
    }

    @Override
    public void acceptInvite(IncomingInvite invite)
    {
        if (invite == null || invite.inviteId == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("invite_id", invite.inviteId);
        socket.send("lobby/accept", d);
    }

    @Override
    public void declineInvite(IncomingInvite invite)
    {
        if (invite == null || invite.inviteId == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("invite_id", invite.inviteId);
        socket.send("lobby/decline", d);
    }

    @Override
    public void confirmFight()
    {
        // The panel works against a "one fight at a time" model — there's
        // no concept of overlapping confirm windows in the UI — so the
        // service caches the most recently proposed session id and uses
        // it here. The server-side state machine enforces the same rule:
        // joining a fight removes you from the lobby, so overlapping
        // sessions for one user are impossible.
        String sid = currentFightSessionId;
        if (sid == null)
        {
            log.debug("confirmFight() with no active fight session - dropping");
            return;
        }
        JsonObject d = new JsonObject();
        d.addProperty("fight_session_id", sid);
        boolean sent = socket.send("lobby/confirm", d);
        if (sent)
        {
            // Successful send wins over any stale buffer entry — if the
            // user double-clicked Confirm during a brief reconnect,
            // only the surviving send carries forward.
            pendingConfirmFightSessionId = null;
        }
        else
        {
            // Socket was closed at send time (the WebSocketManager
            // backoff ladder runs 1-2-4-8 s; if Confirm is clicked
            // during that window the frame is silently dropped today,
            // which surfaced as the "30-second confirm window expired"
            // QA report). Buffer the session id so the connect
            // listener can flush it on the next onOpen — bounded by
            // the server's 30-s confirm window via
            // handleSessionExpired clearing the buffer.
            pendingConfirmFightSessionId = sid;
            log.debug("confirmFight() buffered (socket closed) sid={}", sid);
        }
    }

    /** Connect-listener callback: drains any {@link
     *  #pendingConfirmFightSessionId} buffered while the socket was
     *  closed. Runs on OkHttp's dispatcher thread alongside
     *  {@link #replayJoinOnReconnect()}; safe because the buffer is
     *  volatile and the failure mode (re-buffer + retry on next open)
     *  is idempotent. */
    private void flushPendingConfirm()
    {
        String sid = pendingConfirmFightSessionId;
        if (sid == null) return;
        // Drop the buffer first to avoid re-entry if the send below
        // races a fresh confirmFight() call (e.g. user clicked Confirm
        // again during the flush). The buffer is repopulated below if
        // the send fails — single-writer semantics.
        pendingConfirmFightSessionId = null;
        JsonObject d = new JsonObject();
        d.addProperty("fight_session_id", sid);
        if (socket.send("lobby/confirm", d))
        {
            log.debug("WebSocketLobbyService: flushed buffered confirm sid={}", sid);
        }
        else
        {
            // The socket closed again between onOpen firing and our
            // send. Re-buffer so the next open retries. Bounded by
            // the 30-s server confirm window — handleSessionExpired
            // clears the buffer once the server gives up.
            pendingConfirmFightSessionId = sid;
            log.debug("WebSocketLobbyService: re-buffered confirm sid={} (socket closed mid-flush)", sid);
        }
    }

    @Override
    public void block(LobbyMember member)
    {
        if (member == null || member.playerId == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("blocked_player_id", member.playerId);
        socket.send("lobby/block", d);
    }

    @Override
    public void unblock(LobbyMember member)
    {
        if (member == null || member.playerId == null) return;
        JsonObject d = new JsonObject();
        d.addProperty("blocked_player_id", member.playerId);
        socket.send("lobby/unblock", d);
    }

    @Override
    public void blockById(String playerId)
    {
        if (playerId == null) return;
        String trimmed = playerId.trim();
        if (trimmed.isEmpty()) return;
        JsonObject d = new JsonObject();
        d.addProperty("blocked_player_id", trimmed);
        socket.send("lobby/block", d);
    }

    @Override
    public void unblockById(String playerId)
    {
        if (playerId == null) return;
        String trimmed = playerId.trim();
        if (trimmed.isEmpty()) return;
        JsonObject d = new JsonObject();
        d.addProperty("blocked_player_id", trimmed);
        socket.send("lobby/unblock", d);
    }

    /** Pass-through to {@link WebSocketManager#isConnected()}. The
     *  panel's reconnect banner reads this to decide whether to show
     *  the countdown — the wire state is the single source of truth
     *  for "are we online", not anything cached in this service. */
    @Override
    public boolean isConnected()
    {
        return socket.isConnected();
    }

    /** Pass-through to {@link WebSocketManager#getNextReconnectAttemptEpochMs()}.
     *  Drives the 1Hz countdown on the panel's reconnect banner.
     *  Returning {@code 0} suppresses the banner; any non-zero value
     *  is interpreted as "retry scheduled at that wall-clock time". */
    @Override
    public long getNextReconnectAttemptEpochMs()
    {
        return socket.getNextReconnectAttemptEpochMs();
    }

    // ---------------------------------------------------------------
    // Inbound: server -> panel (all dispatched on EDT)
    // ---------------------------------------------------------------

    /** Most recently proposed fight session id; used by
     *  {@link #confirmFight()} since the panel's API doesn't take an
     *  explicit id. Set on {@code lobby/fight_proposed}, cleared on
     *  {@code lobby/match_found} / {@code lobby/session_expired}. */
    private volatile String currentFightSessionId;

    private void handleJoinedEcho(JsonObject data)
    {
        log.debug("WebSocketLobbyService: lobby/joined echo received");
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(l::onJoinedEcho);
    }

    private void handleRoster(JsonObject data)
    {
        // Leave-cascade fast-path: server tells us its filtered view
        // is stale and a fresh lobby/join will regenerate it.
        boolean stale = data.has("stale") && data.get("stale").getAsBoolean();
        JsonElement membersEl = data.get("members");
        if (stale || membersEl == null || membersEl.isJsonNull())
        {
            log.debug("WebSocketLobbyService: lobby/roster stale or null members - re-sending lobby/join");
            replayJoinOnReconnect();
            return;
        }
        JsonArray members = membersEl.getAsJsonArray();
        List<LobbyMember> roster = new ArrayList<>(members.size());
        Map<String, LobbyMember> nextCache = new HashMap<>();
        for (JsonElement el : members)
        {
            if (!el.isJsonObject()) continue;
            LobbyMember m = parseMember(el.getAsJsonObject());
            if (m == null) continue;
            roster.add(m);
            nextCache.put(m.playerId, m);
        }
        // Replace cache wholesale — server's snapshot is authoritative
        // for *presence*. Rank resolution happens in the enrichment
        // pass below; until shards resolve, each member's rank index
        // is -1 (the "unknown" sentinel) and the panel renders the
        // row with a "Waiting" chip in the rank slot.
        rosterByPlayerId.clear();
        rosterByPlayerId.putAll(nextCache);
        long version = rosterVersion.incrementAndGet();
        // Diagnostic dump of the wire-level roster — what the server
        // actually filtered + pushed to *this* viewer. The "I can see
        // myself and another player but they can't see me" class of
        // bug is always one of: (a) the other player isn't in MY
        // roster.members at all (server filtered them out — block,
        // rank-range, region mismatch, smurf-guard); (b) they're in
        // mine but I'm not in theirs (asymmetric block); (c) we're
        // both in but our slider rejects each other client-side.
        // Logging the full members list here makes (a) and (b)
        // trivially diagnosable.
        if (log.isDebugEnabled())
        {
            log.debug("WebSocketLobbyService: lobby/roster received raw_count={} parsed_count={}",
                members.size(), roster.size());
            for (LobbyMember m : roster)
            {
                log.debug("WebSocketLobbyService:   roster row playerId={} name={} region={} styles={} builds={} isMod={}",
                    m.playerId, m.name, m.region, m.styles, m.builds, m.isMod);
            }
        }
        LobbyEventListener l = listener;
        if (l != null)
        {
            // Defensive copy: enrichment may rebuild and mutate the
            // backing list while the panel renders the initial pass.
            List<LobbyMember> initial = new ArrayList<>(roster);
            SwingUtilities.invokeLater(() -> l.onRosterSnapshot(initial));
        }
        enrichRosterWithShardRanks(roster, version);
    }

    /** Resolves each lobby member's rank from the CDN-published
     *  leaderboard shard files (NOT the server's roster push — see
     *  {@link #pvpDataService}'s field doc for rationale). Fires a
     *  second {@link LobbyEventListener#onRosterSnapshot} once every
     *  per-member shard lookup has settled, with new
     *  {@link LobbyMember} instances carrying the resolved
     *  {@code rank_idx} in both the {@code currentRankIdx} and
     *  {@code peakRankIdx} fields (peak isn't separately published in
     *  shards; the lobby uses current rank for both per
     *  {@code BACKEND_HANDOFF_LOBBY.md} Q5).
     *
     *  <p>Stale-callback guard: each enrichment pass is tagged with a
     *  monotonic version; a later roster push bumps the version and
     *  earlier pass's completion is silently dropped instead of
     *  pushing a stale snapshot back to the panel.
     *
     *  <p>Bucket: uses the user's last-known sort bucket from
     *  {@link #lastJoinArgs} (the bucket they picked at the gate).
     *  Falls back to "overall" if not yet joined. */
    private void enrichRosterWithShardRanks(List<LobbyMember> roster, long version)
    {
        if (roster.isEmpty())
        {
            log.debug("WebSocketLobbyService: enrich skipped - empty roster (version={})", version);
            return;
        }
        JoinArgs args = lastJoinArgs;
        String bucket = (args == null || args.sortBucket == null || args.sortBucket.isEmpty())
            ? "overall"
            : args.sortBucket;
        // Resolved rank index per player_id. Populated synchronously
        // from {@link #resolvedRankCache} for warm rows, asynchronously
        // from shard futures for cold rows. The allOf() callback
        // reads it once at the end so there's no read/write race.
        Map<String, Integer> resolved = new ConcurrentHashMap<>();
        List<CompletableFuture<?>> futures = new ArrayList<>(roster.size());
        int cacheHits = 0;
        long nowMs = System.currentTimeMillis();
        for (LobbyMember m : roster)
        {
            if (m == null || m.name == null || m.name.isEmpty()) continue;
            final String pid = m.playerId;
            final String mname = m.name;
            final String cacheKey = rankCacheKey(mname, bucket);
            ResolvedRankEntry cached = resolvedRankCache.get(cacheKey);
            if (cached != null && cached.isFresh(nowMs))
            {
                // Cache hit — skip the shard call entirely. The
                // underlying shard JSON is itself cached in
                // PvPDataService for the same TTL, but a hit there
                // still costs a CompletableFuture + map-walk per
                // member per roster push. With back-to-back pushes
                // (common during a join/leave cascade) and 60+
                // members, that orchestration is the bottleneck the
                // user surfaced as "shard lookups way too frequent".
                resolved.put(pid, cached.rankIdx);
                cacheHits++;
                continue;
            }
            // bypassCache=true: roster enrichment is one of the two
            // explicit-freshness paths defined by the 2026-05-24
            // backend handoff (DynamoDB-stream-driven incremental
            // shard writer, ≈30 s propagation). The local
            // resolvedRankCache (1-h TTL) above already prevents
            // per-push duplicate fetches; we only land here on a
            // first-time-seen member or after retryUnresolvedRanks
            // evicted a "Waiting" row — both cases want the
            // freshest shard the writer has produced, not a 60-min
            // stale PvPDataService positive-cache entry.
            CompletableFuture<ShardRank> lookup = pvpDataService.getShardRankByName(mname, bucket, true);
            if (lookup == null) continue;
            futures.add(lookup.thenCompose(sr ->
            {
                String tier = (sr != null) ? sr.tier : null;
                if (tier != null)
                {
                    recordEnrichedRank(pid, mname, bucket, tier, "shard", resolved, cacheKey);
                    return CompletableFuture.<Void>completedFuture(null);
                }
                // Shard miss — one /user fetch per (name, bucket), deduped
                // in PvPDataService. Whitelist membership is not consulted.
                return pvpDataService.getRankFromProfileForLobby(mname, bucket).thenAccept(profileSr ->
                {
                    if (profileSr != null && profileSr.tier != null)
                    {
                        recordEnrichedRank(pid, mname, bucket, profileSr.tier, "profile_api",
                            resolved, cacheKey);
                    }
                    else
                    {
                        log.debug("WebSocketLobbyService:   rank lookup name={} bucket={} -> null (shard + /user)",
                            mname, bucket);
                    }
                });
            }));
        }
        log.debug("WebSocketLobbyService: enrich kicking off bucket={} members={} version={} cacheHits={} cacheMisses={}",
            bucket, roster.size(), version, cacheHits, futures.size());
        if (futures.isEmpty())
        {
            // Every member served from the resolved-rank cache —
            // skip the future orchestration entirely and publish the
            // enriched snapshot directly. Without this branch the
            // panel would never receive a refreshed roster when
            // every row is warm-cached (the prior implementation
            // returned early here, which only worked because the old
            // code ALWAYS dispatched a future per member).
            if (cacheHits > 0)
            {
                publishEnrichedSnapshot(roster, resolved, version, bucket);
            }
            else
            {
                log.debug("WebSocketLobbyService: enrich skipped - no lookups queued (version={})", version);
            }
            return;
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).whenComplete((v, ex) ->
            publishEnrichedSnapshot(roster, resolved, version, bucket));
    }

    /** Cache key for {@link #resolvedRankCache}: canonical name +
     *  bucket. Matches the canonicalisation used by
     *  {@link PvPDataService#getShardRankByName(String, String)} so
     *  the two caches agree on lookup keys (lowercased, multi-space
     *  collapsed to single-space). */
    private static String rankCacheKey(String name, String bucket)
    {
        String canon = name.trim().replaceAll("\\s+", " ").toLowerCase();
        String bk = (bucket == null || bucket.isEmpty()) ? "overall" : bucket.toLowerCase();
        return canon + ":" + bk;
    }

    private void recordEnrichedRank(String pid, String mname, String bucket, String tier,
                                  String source, Map<String, Integer> resolved,
                                  String cacheKey)
    {
        int idx = RankUtils.rankIndexForTier(tier);
        log.debug("WebSocketLobbyService:   rank lookup name={} bucket={} -> tier={} rankIdx={} source={}",
            mname, bucket, tier, idx, source);
        if (idx >= 0)
        {
            resolved.put(pid, idx);
            resolvedRankCache.put(cacheKey,
                new ResolvedRankEntry(idx, System.currentTimeMillis()));
        }
    }

    /** Single exit point for an enrichment pass: applies the
     *  stale-version guard, rebuilds the roster with the resolved
     *  rank indices folded in, re-publishes
     *  {@link #rosterByPlayerId}, and fires
     *  {@link LobbyEventListener#onRosterSnapshot} on the EDT.
     *
     *  <p>Extracted to a helper so the all-cache-hit fast path
     *  (no futures dispatched) and the slow path (allOf().whenComplete)
     *  share the same fan-out semantics — without this duplication
     *  the cache-only path would silently skip rebuilding
     *  {@code rosterByPlayerId} and the next flat-payload push that
     *  reads the cache would see stale -1 ranks. */
    private void publishEnrichedSnapshot(List<LobbyMember> roster,
                                         Map<String, Integer> resolved,
                                         long version,
                                         String bucket)
    {
        if (rosterVersion.get() != version)
        {
            log.debug("WebSocketLobbyService: enrich version={} superseded - dropping", version);
            return;
        }
        log.debug("WebSocketLobbyService: enrich version={} settled, resolved={}/{} members",
            version, resolved.size(), roster.size());
        List<LobbyMember> enriched = new ArrayList<>(roster.size());
        Map<String, LobbyMember> nextCache = new HashMap<>(roster.size() * 2);
        for (LobbyMember m : roster)
        {
            if (m == null) continue;
            Integer idx = resolved.get(m.playerId);
            int rankIdx = (idx != null) ? idx : -1;
            LobbyMember updated = new LobbyMember(
                m.playerId, m.name, m.styles, m.builds,
                /* currentRankIdx */ rankIdx,
                /* peakRankIdx */ rankIdx,
                m.region, m.isMod,
                /* isSuspended */ m.isSuspended,
                /* minRankIdx */ m.minRankIdx,
                /* maxRankIdx */ m.maxRankIdx);
            enriched.add(updated);
            nextCache.put(updated.playerId, updated);
        }
        // Re-publish the cache with the rank-enriched copies so
        // any subsequent flat-payload push (e.g. invite_received
        // mid-enrichment) sees the resolved rank rather than -1.
        // Guard against a racing handleRoster having already
        // bumped the version (and thus the cache contents) — the
        // version check above + the put-back here is best-effort.
        rosterByPlayerId.clear();
        rosterByPlayerId.putAll(nextCache);
        LobbyEventListener l = listener;
        if (l == null) return;
        if (log.isDebugEnabled())
        {
            StringBuilder sb = new StringBuilder();
            for (LobbyMember m : enriched)
            {
                if (sb.length() > 0) sb.append(", ");
                sb.append(m.name).append("=").append(m.peakRankIdx);
            }
            log.debug("WebSocketLobbyService: enrich version={} firing enriched snapshot [{}]",
                version, sb);
        }
        SwingUtilities.invokeLater(() -> l.onRosterSnapshot(enriched));
    }

    /** Periodic retry pass for roster members whose initial shard
     *  enrichment didn't resolve a rank ({@code peakRankIdx == -1},
     *  the "Waiting" sentinel). Clears the per-player negative-cache
     *  entry in {@link PvPDataService} for each unresolved member,
     *  then re-runs the full enrichment pass — the shard generator
     *  may have published the missing player since the last attempt
     *  (e.g. they just had their first match and the writer caught
     *  up between our roster snapshot and now).
     *
     *  <p>Runs on the {@link #scheduler} thread; the enrichment pass
     *  it triggers handles its own EDT marshalling. Cheap no-op when
     *  the roster is empty or every member is already resolved. */
    private void retryUnresolvedRanks()
    {
        try
        {
            if (rosterByPlayerId.isEmpty()) return;
            List<LobbyMember> unresolved = new ArrayList<>();
            for (LobbyMember m : rosterByPlayerId.values())
            {
                if (m == null) continue;
                if (m.peakRankIdx >= 0) continue;
                if (m.name == null || m.name.isEmpty()) continue;
                unresolved.add(m);
                pvpDataService.clearShardNegativeCache(m.name);
                // No resolvedRankCache eviction here — we don't cache
                // unresolved rows in the first place, so there's
                // nothing to remove. The shard generator catching up
                // will populate the entry on the next enrichment.
            }
            if (unresolved.isEmpty()) return;
            // Bump the version BEFORE re-enriching so the new pass
            // supersedes any in-flight enrichment from the prior
            // roster push — the stale-pass guard in
            // enrichRosterWithShardRanks drops the older result and
            // only the fresh shard data lands on the panel. We
            // re-enrich the full roster (not just unresolved rows)
            // so the next onRosterSnapshot is a complete snapshot
            // and the panel's diff renderer doesn't see partial state.
            long version = rosterVersion.incrementAndGet();
            List<LobbyMember> full = new ArrayList<>(rosterByPlayerId.values());
            log.debug("WebSocketLobbyService: retryUnresolvedRanks bumping to version={} unresolved={}/{}",
                version, unresolved.size(), full.size());
            enrichRosterWithShardRanks(full, version);
        }
        catch (Exception e)
        {
            log.debug("WebSocketLobbyService: retryUnresolvedRanks threw", e);
        }
    }

    /** Explicit "the user just looked this player up" refresh hook
     *  used by the dashboard's Player Lookup tab. When the user
     *  clicks through to a player profile, {@code PvPDataService}
     *  populates its {@code userStatsCache} with fresh data —
     *  feeding that back into the lobby's rank enrichment lets us
     *  unstick a stale "Waiting" chip without the user noticing the
     *  rank cache only ever updates from shard pulls.
     *
     *  <p>Clears the negative-cache for the player so the next shard
     *  attempt isn't short-circuited, then re-runs the enrichment
     *  pass over the whole roster. No-op if the player isn't in our
     *  cached roster (left the lobby, never joined, etc.). EDT-safe;
     *  any caller may invoke. */
    public void refreshRankForPlayer(String playerName)
    {
        if (playerName == null) return;
        String trimmed = playerName.trim();
        if (trimmed.isEmpty()) return;
        pvpDataService.clearShardNegativeCache(trimmed);
        // Also evict the local resolved-rank cache for this player
        // across all buckets so the next enrichment pass forces a
        // fresh shard pull. Without this, an explicit Player Lookup
        // refresh would still serve the stale cached rank index
        // until the 1-h TTL elapsed.
        String canon = trimmed.replaceAll("\\s+", " ").toLowerCase();
        String keyPrefix = canon + ":";
        resolvedRankCache.keySet().removeIf(k -> k.startsWith(keyPrefix));
        if (rosterByPlayerId.isEmpty()) return;
        long version = rosterVersion.incrementAndGet();
        List<LobbyMember> full = new ArrayList<>(rosterByPlayerId.values());
        log.debug("WebSocketLobbyService: refreshRankForPlayer name={} bumping to version={} roster={}",
            trimmed, version, full.size());
        enrichRosterWithShardRanks(full, version);
    }

    private void handleBlockListSnapshot(JsonObject data)
    {
        // Backend pushes data={"blocked": [{player_id, name}, ...]} per
        // get_block_list (backend/core/lobby.py). Older builds emitted a
        // flat string array under "blocked_player_ids" — accept either
        // shape so a partial deploy doesn't drop blocks silently.
        Set<String> ids = new HashSet<>();
        if (data != null && data.has("blocked") && data.get("blocked").isJsonArray())
        {
            for (JsonElement el : data.getAsJsonArray("blocked"))
            {
                if (el == null || el.isJsonNull()) continue;
                if (el.isJsonObject())
                {
                    String pid = optString(el.getAsJsonObject(), "player_id");
                    if (!pid.isEmpty()) ids.add(pid);
                }
                else if (el.isJsonPrimitive() && el.getAsJsonPrimitive().isString())
                {
                    String pid = el.getAsString();
                    if (!pid.isEmpty()) ids.add(pid);
                }
            }
        }
        if (ids.isEmpty())
        {
            ids.addAll(parseStringArray(data, "blocked_player_ids"));
        }
        blockedPlayerIds.clear();
        blockedPlayerIds.addAll(ids);
        LobbyEventListener l = listener;
        if (l == null) return;
        Set<String> snapshot = Collections.unmodifiableSet(new HashSet<>(blockedPlayerIds));
        SwingUtilities.invokeLater(() -> l.onBlockListSnapshot(snapshot));
    }

    private void handleBlockAdded(JsonObject data)
    {
        String pid = optString(data, "blocked_player_id");
        if (pid.isEmpty()) return;
        blockedPlayerIds.add(pid);
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onBlockAdded(pid));
    }

    private void handleBlockRemoved(JsonObject data)
    {
        String pid = optString(data, "blocked_player_id");
        if (pid.isEmpty()) return;
        blockedPlayerIds.remove(pid);
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onBlockRemoved(pid));
    }

    private void handleInviteReceived(JsonObject data)
    {
        String inviteId = optString(data, "invite_id");
        String fromPlayerId = optString(data, "from_player_id");
        log.debug("WebSocketLobbyService: handleInviteReceived ENTRY inviteId={} fromPlayerId={}",
            inviteId, fromPlayerId);
        if (inviteId.isEmpty() || fromPlayerId.isEmpty())
        {
            log.debug("WebSocketLobbyService: handleInviteReceived DROP - missing inviteId or fromPlayerId"
                    + " (inviteId='{}' fromPlayerId='{}')",
                inviteId, fromPlayerId);
            return;
        }
        // Defence-in-depth: server already cancels invites between
        // blocked pairs (BACKEND_HANDOFF_LOBBY.md §lobby/block) but a
        // partial deploy or a block-vs-invite race could still let a
        // frame slip through. Drop here so the panel + the
        // LobbyInviteNotificationOverlay both stay clean — single
        // chokepoint, no need to re-check downstream.
        if (blockedPlayerIds.contains(fromPlayerId))
        {
            log.debug("WebSocketLobbyService: handleInviteReceived DROP - blocked sender player_id={}",
                fromPlayerId);
            return;
        }
        String rawStyle = optString(data, "style");
        String rawBuild = optString(data, "build");
        Style style = parseStyle(rawStyle);
        BuildType build = parseBuild(rawBuild);
        if (style == null || build == null)
        {
            log.debug("WebSocketLobbyService: handleInviteReceived DROP - unparseable style/build"
                    + " (rawStyle='{}' rawBuild='{}' parsedStyle={} parsedBuild={})",
                rawStyle, rawBuild, style, build);
            return;
        }
        // Inbound wire-protocol boundary: convert the canonical wire
        // string ("ffa" / "clan_wars" / "none") into the picker
        // display string ("FFA Portal" / "Clan Wars" / "") so the
        // panel's render paths (inviteLocationLabel, formatStyleBuildPlace,
        // meetAtPlace) keep showing display-cased text without churn.
        String location = LobbyLocationCodec.toDisplay(optString(data, "location"));
        long expiresAt = optLong(data, "expires_at_epoch_ms");

        LobbyMember sender = rosterByPlayerId.get(fromPlayerId);
        if (sender == null)
        {
            // Reconstruct a synthetic sender from the flat fields when
            // the roster cache doesn't have a row yet. Prefer the
            // display-cased `from_name`; fall back to `sender_name`
            // and finally to the canonical id itself.
            String displayName = optString(data, "from_name");
            if (displayName.isEmpty()) displayName = optString(data, "sender_name");
            if (displayName.isEmpty()) displayName = fromPlayerId;
            sender = new LobbyMember(
                fromPlayerId,
                displayName,
                parseStyleSet(data, "sender_styles"),
                parseBuildSet(data, "sender_builds"),
                /* currentRankIdx */ -1,
                /* peakRankIdx */ -1,
                optString(data, "sender_region"),
                /* isMod */ false
            );
        }
        IncomingInvite invite = new IncomingInvite(inviteId, sender, style, build, location, expiresAt);
        LobbyEventListener l = listener;
        if (l == null)
        {
            log.debug("WebSocketLobbyService: handleInviteReceived DROP - no listener wired"
                    + " (panel hasn't called setListener yet); inviteId={} fromPlayerId={}",
                inviteId, fromPlayerId);
            return;
        }
        log.debug("WebSocketLobbyService: handleInviteReceived DISPATCH to listener inviteId={}"
                + " fromPlayerId={} senderRankIdx={} style={} build={}",
            inviteId, fromPlayerId, sender.currentRankIdx, style, build);
        SwingUtilities.invokeLater(() -> l.onIncomingInvite(invite));
    }

    /** Routes {@code lobby/invite_cancelled} to either
     *  {@link LobbyEventListener#onIncomingInviteDeclined} (when the
     *  receiver declined) or {@link LobbyEventListener#onIncomingInviteCancelled}
     *  (sender cancel, block-cascade, leave-cascade, TTL expiry). */
    private void handleInviteCancelled(JsonObject data)
    {
        String inviteId = optString(data, "invite_id");
        if (inviteId.isEmpty()) return;
        LobbyEventListener l = listener;
        if (l == null) return;
        if ("declined".equals(optString(data, "reason")))
        {
            String declinedByName = optString(data, "declined_by_name");
            SwingUtilities.invokeLater(() -> l.onIncomingInviteDeclined(inviteId, declinedByName));
        }
        else
        {
            SwingUtilities.invokeLater(() -> l.onIncomingInviteCancelled(inviteId));
        }
    }

    private void handleFightProposed(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        // A new fight is being proposed — any confirm buffered against
        // a *previous* (now-defunct) session is stale. Drop it so a
        // belated flush doesn't try to confirm a session the server
        // has already torn down.
        if (pendingConfirmFightSessionId != null
            && !pendingConfirmFightSessionId.equals(sid))
        {
            pendingConfirmFightSessionId = null;
        }
        currentFightSessionId = sid;
        Style style = parseStyle(optString(data, "style"));
        BuildType build = parseBuild(optString(data, "build"));
        if (style == null || build == null) return;
        // Inbound wire-protocol boundary — see handleInviteReceived.
        String location = LobbyLocationCodec.toDisplay(optString(data, "location"));
        // Canonical wire field per BACKEND_HANDOFF_LOBBY.md §FightSession
        // is `confirm_expires_at_epoch_ms`. The plugin previously read
        // the wrong key (`expires_at_epoch_ms`, the IncomingInvite
        // field), which silently defaulted the deadline to 0L and made
        // the panel's 1-Hz fight tick exit the Confirm-Fight card on
        // its very first tick — the user saw the popup vanish before
        // they could click anything (QA bug 2026-05-25). Read the
        // canonical key first; fall back to the legacy name so a
        // partial backend deploy doesn't strand every fight; and if
        // BOTH are missing/zero, synthesise a sane 30s window keyed to
        // the local clock so the user still gets a usable popup.
        //
        // NOTE: the panel no longer trusts this absolute deadline for
        // the confirm countdown — MatchmakingLobbyPanel.LocalFightState
        // runs a fixed 30 s window off a monotonic clock so a wrong /
        // skewed client wall clock can't cut the window short. This
        // value is retained only as the server's advisory deadline.
        long expiresAt = optLong(data, "confirm_expires_at_epoch_ms");
        if (expiresAt <= 0L) expiresAt = optLong(data, "expires_at_epoch_ms");
        if (expiresAt <= 0L)
        {
            long synth = System.currentTimeMillis() + 30_000L;
            log.warn("WebSocketLobbyService.handleFightProposed: missing confirm_expires_at_epoch_ms (and legacy expires_at_epoch_ms) on lobby/fight_proposed sid={} - synthesising local-clock deadline now+30s={} so the Confirm-Fight card doesn't insta-exit",
                sid, synth);
            expiresAt = synth;
        }
        LobbyMember opponent = resolveOpponent(data);
        if (opponent == null) return;
        FightSession session = new FightSession(sid, opponent, style, build, location, expiresAt);
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onFightProposed(session));
    }

    private void handleFightConfirmedByPeer(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onFightConfirmedByPeer(sid));
    }

    private void handleMatchFound(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        Style style = parseStyle(optString(data, "style"));
        BuildType build = parseBuild(optString(data, "build"));
        if (style == null || build == null) return;
        // Inbound wire-protocol boundary — see handleInviteReceived.
        String location = LobbyLocationCodec.toDisplay(optString(data, "location"));
        String world = optString(data, "world");
        String meetingPlace = optString(data, "meeting_place");
        LobbyMember opponent = resolveOpponent(data);
        if (opponent == null) return;
        // Server has already deleted both LobbyMembers rows + the
        // session at this point — the lobby state is consumed, clear
        // our local session-id cache. Also drop any buffered confirm
        // for this session: the match landed, so a late flush would
        // be a no-op at best, an error/lobby at worst.
        currentFightSessionId = null;
        if (sid.equals(pendingConfirmFightSessionId)) pendingConfirmFightSessionId = null;
        MatchInfo match = new MatchInfo(sid, opponent, style, build, location, world, meetingPlace);
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onMatchFound(match));
    }

    private void handleSessionExpired(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        if (sid.equals(currentFightSessionId)) currentFightSessionId = null;
        // 30-s confirm window elapsed — any buffered confirm against
        // this session is moot, drop it so a future reconnect doesn't
        // ship a confirm for a session that no longer exists.
        if (sid.equals(pendingConfirmFightSessionId)) pendingConfirmFightSessionId = null;
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onFightSessionExpired(sid));
    }

    /** {@code lobby/displaced}: a different account linked to the same
     *  canonical identity (a logged-in alt) connected and the server
     *  removed THIS account's lobby membership — only one linked account
     *  may occupy the lobby at a time (backend {@code evict_alt_lobby_rows}
     *  at $connect). Two responsibilities:
     *  <ol>
     *    <li>Disarm the reconnect-replay by nulling {@link #lastJoinArgs}.
     *    Otherwise, if the server also force-closed this socket, the
     *    {@code WebSocketManager} reconnect would replay {@code lobby/join}
     *    and bounce the alt straight back out — a join/displace ping-pong
     *    between the two linked clients. The user must deliberately
     *    re-enter via Go-to-lobby on this account.</li>
     *    <li>Surface it to the panel via
     *    {@link LobbyEventListener#onDisplacedByAlt} so the UI drops back
     *    to the gate with an explanatory notice.</li>
     *  </ol>
     *  {@code active_name} (optional) is the display name of the account
     *  that is now the active lobby occupant. */
    private void handleDisplaced(JsonObject data)
    {
        String activeName = optString(data, "active_name");
        log.info("WebSocketLobbyService: lobby/displaced - this account was removed from the"
            + " lobby because a linked alt connected (active_name={}); disarming reconnect-replay",
            activeName);
        // Break the join/displace ping-pong: a reconnect must not re-join.
        lastJoinArgs = null;
        currentFightSessionId = null;
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onDisplacedByAlt(activeName));
    }

    private void handleError(JsonObject data)
    {
        String code = optString(data, "code");
        String message = optString(data, "message");
        // Surfaced at WARN because error/lobby pushes are exceptional
        // by definition — the user is going to ask why their fight
        // button didn't work, and the answer is almost always in this
        // single log line (RANK_OUT_OF_RANGE, BLOCKED, SMURF_GUARD…).
        log.warn("WebSocketLobbyService: error/lobby code={} message={}", code, message);
        LobbyEventListener l = listener;
        if (l == null) return;
        SwingUtilities.invokeLater(() -> l.onError(code, message));
    }

    // ---------------------------------------------------------------
    // Reconnect re-join
    // ---------------------------------------------------------------

    /** Re-sends the cached {@code lobby/join} if one was ever made.
     *  Triggered by both {@code WebSocketManager.onOpen} and the
     *  leave-cascade fast-path in {@link #handleRoster}. Safe to call
     *  with no cached args (no-op). */
    private void replayJoinOnReconnect()
    {
        JoinArgs j = lastJoinArgs;
        if (j == null) return;
        joinLobby(j.region, j.styles, j.builds, j.minDisplayRankIdx, j.maxDisplayRankIdx, j.sortBucket);
    }

    // ---------------------------------------------------------------
    // Parsing helpers
    // ---------------------------------------------------------------

    /** Returns the opponent {@link LobbyMember} for a
     *  {@code fight_proposed} / {@code match_found} push.
     *  When one of player_a / player_b is in the roster cache that
     *  row is the opponent; otherwise builds a minimal member from
     *  player_a's id + name on the wire. */
    private LobbyMember resolveOpponent(JsonObject data)
    {
        String a = optString(data, "player_a_player_id");
        String b = optString(data, "player_b_player_id");
        if (a.isEmpty() || b.isEmpty()) return null;
        LobbyMember aRow = rosterByPlayerId.get(a);
        LobbyMember bRow = rosterByPlayerId.get(b);
        if (aRow != null && bRow == null) return aRow;
        if (bRow != null && aRow == null) return bRow;
        if (aRow != null) return aRow;
        return new LobbyMember(a, optString(data, "player_a_name"),
            EnumSet.noneOf(Style.class), EnumSet.noneOf(BuildType.class),
            -1, -1, "", false);
    }

    private LobbyMember parseMember(JsonObject m)
    {
        String name = optString(m, "name");
        String playerId = optString(m, "player_id");
        if (playerId.isEmpty() && !name.isEmpty())
        {
            // Belt-and-braces: roster rows should always carry
            // player_id post scrub, but derive from display name so
            // a partial backend deploy doesn't drop every row.
            playerId = name.trim().toLowerCase();
        }
        if (playerId.isEmpty()) return null;
        Set<Style> styles = parseStyleSet(m, "styles");
        Set<BuildType> builds = parseBuildSet(m, "builds");
        // Rank is NOT sourced from the server's roster push — the
        // plugin treats {@code OSRS-LobbyMembers} as pure presence
        // data and resolves each player's rank client-side from the
        // CDN-published leaderboard shards (see
        // {@link #enrichRosterWithShardRanks}). Initialise both
        // fields to the "unknown" sentinel (-1) so the panel renders
        // a "Waiting" chip until the shard pass completes; the
        // {@code rank_idx} / {@code peak_rank_idx} fields on the
        // wire are intentionally ignored even if the server includes
        // them (a partial deploy that still emits stale rank info
        // would otherwise mis-render rows as "Bronze 3" the moment
        // the field defaults to 0).
        int currentRankIdx = -1;
        int peakRankIdx = -1;
        String region = optString(m, "region");
        boolean isMod = m.has("is_mod") && m.get("is_mod").isJsonPrimitive()
            && m.get("is_mod").getAsJsonPrimitive().isBoolean()
            && m.get("is_mod").getAsBoolean();
        // Operator matchmaking-suspend stamp — same strict-boolean-primitive
        // contract as is_mod: a string "true" / numeric 1 must NOT coerce, so
        // a malformed/spoofed wire value can't suspend a member. Absent field
        // defaults to false (pre-deploy backend).
        boolean isSuspended = m.has("is_suspended") && m.get("is_suspended").isJsonPrimitive()
            && m.get("is_suspended").getAsJsonPrimitive().isBoolean()
            && m.get("is_suspended").getAsBoolean();
        // The member's own accept-invite slider bounds drive the
        // out-of-their-range greyout. Both fields default to
        // {@link LobbyMember#UNKNOWN_RANK_IDX} when the server omits
        // them so the panel falls back to "show the row normally"
        // rather than greying every row on a pre-deploy backend.
        int minRankIdx = optRankIdx(m, "min_rank_idx");
        int maxRankIdx = optRankIdx(m, "max_rank_idx");
        return new LobbyMember(playerId, name, styles, builds, currentRankIdx, peakRankIdx,
            region, isMod, isSuspended, minRankIdx, maxRankIdx);
    }

    /** Reads a rank-index field off a roster-row JSON object. Returns
     *  {@link LobbyMember#UNKNOWN_RANK_IDX} when the field is missing,
     *  null, non-numeric, or stamped with the server's own
     *  "no value" sentinel (negative). The plugin treats either bound
     *  being unknown as "range unknown" (see
     *  {@link LobbyMember#minRankIdx}) so a partial payload never
     *  greys every row. */
    private static int optRankIdx(JsonObject o, String key)
    {
        if (o == null || !o.has(key) || o.get(key).isJsonNull()) return LobbyMember.UNKNOWN_RANK_IDX;
        JsonElement el = o.get(key);
        if (!el.isJsonPrimitive() || !el.getAsJsonPrimitive().isNumber()) return LobbyMember.UNKNOWN_RANK_IDX;
        int v = el.getAsInt();
        return v < 0 ? LobbyMember.UNKNOWN_RANK_IDX : v;
    }

    private static String optString(JsonObject o, String key)
    {
        if (o == null || !o.has(key) || o.get(key).isJsonNull()) return "";
        JsonElement el = o.get(key);
        if (!el.isJsonPrimitive()) return "";
        return el.getAsString();
    }

    private static long optLong(JsonObject o, String key)
    {
        if (o == null || !o.has(key) || o.get(key).isJsonNull()) return 0L;
        JsonElement el = o.get(key);
        if (!el.isJsonPrimitive() || !el.getAsJsonPrimitive().isNumber()) return 0L;
        return el.getAsLong();
    }

    private static Set<String> parseStringArray(JsonObject o, String key)
    {
        Set<String> out = new HashSet<>();
        if (o == null || !o.has(key) || !o.get(key).isJsonArray()) return out;
        for (JsonElement el : o.getAsJsonArray(key))
        {
            if (el == null || el.isJsonNull() || !el.isJsonPrimitive()) continue;
            String s = el.getAsString();
            if (!s.isEmpty()) out.add(s);
        }
        return out;
    }

    private static Set<Style> parseStyleSet(JsonObject o, String key)
    {
        EnumSet<Style> out = EnumSet.noneOf(Style.class);
        for (String s : parseStringArray(o, key))
        {
            Style st = parseStyle(s);
            if (st != null) out.add(st);
        }
        return out;
    }

    private static Set<BuildType> parseBuildSet(JsonObject o, String key)
    {
        EnumSet<BuildType> out = EnumSet.noneOf(BuildType.class);
        for (String s : parseStringArray(o, key))
        {
            BuildType b = parseBuild(s);
            if (b != null) out.add(b);
        }
        return out;
    }

    private static Style parseStyle(String s)
    {
        if (s == null || s.isEmpty()) return null;
        try { return Style.valueOf(s.toUpperCase()); }
        catch (IllegalArgumentException e) { return null; }
    }

    private static BuildType parseBuild(String s)
    {
        if (s == null || s.isEmpty()) return null;
        try { return BuildType.valueOf(s.toUpperCase()); }
        catch (IllegalArgumentException e) { return null; }
    }

    private static List<String> stylesToWire(Set<Style> styles)
    {
        if (styles == null || styles.isEmpty()) return Collections.emptyList();
        List<String> out = new ArrayList<>(styles.size());
        for (Style s : styles) out.add(s.name().toLowerCase());
        return out;
    }

    private static List<String> buildsToWire(Set<BuildType> builds)
    {
        if (builds == null || builds.isEmpty()) return Collections.emptyList();
        List<String> out = new ArrayList<>(builds.size());
        for (BuildType b : builds) out.add(b.name().toLowerCase());
        return out;
    }

    private static JsonArray toJsonArray(List<String> in)
    {
        JsonArray arr = new JsonArray();
        for (String s : in) arr.add(s);
        return arr;
    }

    /** Cached join args used by the reconnect-replay path. Immutable. */
    private static final class JoinArgs
    {
        final String region;
        final Set<Style> styles;
        final Set<BuildType> builds;
        final int minDisplayRankIdx;
        final int maxDisplayRankIdx;
        final String sortBucket;

        JoinArgs(String region, Set<Style> styles, Set<BuildType> builds,
                 int minDisplayRankIdx, int maxDisplayRankIdx, String sortBucket)
        {
            this.region = region;
            this.styles = styles == null ? EnumSet.noneOf(Style.class) : EnumSet.copyOf(styles);
            this.builds = builds == null ? EnumSet.noneOf(BuildType.class) : EnumSet.copyOf(builds);
            this.minDisplayRankIdx = minDisplayRankIdx;
            this.maxDisplayRankIdx = maxDisplayRankIdx;
            this.sortBucket = sortBucket == null ? "overall" : sortBucket;
        }
    }
}

package com.pvp.leaderboard.lobby;

/**
 * Fight styles the lobby supports. Matches the server's
 * {@code ALLOWED_STYLES = {nh,veng,multi,dmm}} validation set.
 *
 * <p>Declaration order is the on-screen order used by the pre-lobby
 * gate's style-toggle row and the per-row chip strip — keep it stable
 * so the UI doesn't reflow on enum reordering. {@code EnumSet}
 * iteration also follows declaration order, so any CSV rendering of
 * "selected styles" reads NH-first / DMM-last by default.
 *
 * <p>Field {@link #label} is intentionally {@code public final} (not
 * encapsulated) — these are tight-knit value types, the existing
 * rendering code accesses {@code style.label} directly, and switching
 * to a getter would buy nothing but verbosity at call sites.
 */
public enum Style
{
    NH("NH"),
    VENG("Veng"),
    MULTI("Multi"),
    DMM("DMM");

    public final String label;

    Style(String label)
    {
        this.label = label;
    }
}

package com.pvp.leaderboard.lobby;

/**
 * Account-build types a player can advertise / fight as. Multi-select at
 * the gate (≥1 required) and rendered as cyan chips on each roster row.
 * This enum is the wire format on both sides — the server stores the
 * player's advertised builds, and the sender picks one of the opponent's
 * advertised builds when issuing an invite.
 *
 * <p><b>Declaration order is load-bearing.</b> Determines on-screen order
 * for the gate's toggle column AND the per-row chip strip (Main → Zerker
 * → Pure). {@code EnumSet} iteration follows declaration order, so the
 * current-style bar's build CSV always renders Main-first.
 */
public enum BuildType
{
    MAIN("Main"),
    ZERKER("Zerker"),
    PURE("Pure");

    public final String label;

    BuildType(String label)
    {
        this.label = label;
    }
}

package com.pvp.leaderboard.lobby;

/**
 * A pending mutual-confirm fight session. Created when either side enters
 * the 30-s mutual-confirm phase (sender's invite was accepted, OR receiver
 * clicked Accept Fight). Pushed by the server via
 * {@code lobby/fight_proposed} to <b>both</b> sides; both must confirm via
 * {@code lobby/confirm} within {@link #confirmExpiresAtEpochMs} or the
 * session ends with both players returned to the lobby (no penalty).
 *
 * <p>This type is the immutable bundle of context for the session. The
 * panel tracks {@code iConfirmed} / {@code peerConfirmed} as <b>local</b>
 * UI state separate from this — those flags are derived from the server's
 * push events ({@link LobbyEventListener#onFightConfirmedByPeer},
 * {@link LobbyEventListener#onMatchFound}) and from the local user clicking
 * the confirm button. Timer ownership lives in the service implementation,
 * keeping this type a pure data carrier.
 */
public final class FightSession
{
    public final String fightSessionId;
    public final LobbyMember opponent;
    public final Style style;
    public final BuildType build;
    public final String location;
    public final long confirmExpiresAtEpochMs;

    public FightSession(String fightSessionId, LobbyMember opponent, Style style, BuildType build,
                        String location, long confirmExpiresAtEpochMs)
    {
        this.fightSessionId = fightSessionId;
        this.opponent = opponent;
        this.style = style;
        this.build = build;
        this.location = location;
        this.confirmExpiresAtEpochMs = confirmExpiresAtEpochMs;
    }
}

package com.pvp.leaderboard.lobby;

import java.util.Set;

/**
 * The seam between {@code MatchmakingLobbyPanel} and the lobby transport.
 * The production implementation is {@code WebSocketLobbyService}, which
 * dispatches {@code lobby/*} commands over the plugin's WebSocket
 * connection. {@link NoOpLobbyService} is the inert fallback used when no
 * service is injected.
 *
 * <p>All methods are <b>fire-and-forget</b> from the panel's perspective —
 * outcomes (success, errors, opponent reactions) arrive asynchronously via
 * the registered {@link LobbyEventListener}. The panel never reads state
 * directly off this object; it only sends commands and renders events.
 * This mirrors the "server is source of truth; client only renders" rule
 * that the matchmaking protocol is built on.
 *
 * <p>Implementations must marshal all listener callbacks onto the EDT
 * (Swing's event-dispatch thread); the production service does this via
 * {@code SwingUtilities.invokeLater}.
 */
public interface LobbyService
{
    /** Registers the single listener the service pushes events to. Replaces
     *  any previously-set listener. Pass {@code null} to clear. Must be set
     *  <b>before</b> calling {@link #start()} or {@link #joinLobby} — events
     *  fired before a listener is registered are dropped silently. */
    void setListener(LobbyEventListener listener);

    /** Begins background work (socket connect, scheduled retries, etc.).
     *  Idempotent — calling twice is a no-op. The panel calls this once
     *  on construction. */
    void start();

    /** Stops all background work and releases resources. Idempotent. The
     *  panel calls this when the user leaves the matchmaking sub-tab. */
    void stop();

    /** Asks the server to add the local user to the lobby or update their
     *  advertised preferences. Calling again with different preferences is
     *  treated as an update — the server is responsible for idempotency.
     *
     *  <p>{@code sortBucket} drives the per-row {@code rank_idx} +
     *  {@code peak_rank_idx} the server emits on every {@code lobby/roster}
     *  push for this viewer. Pass the canonical bucket key for the style
     *  the user has prioritised in their picks ({@code "nh" / "veng" /
     *  "multi" / "dmm"} or {@code "overall"} as a catch-all when no style
     *  is selected). The slider matchmaking gate filters on the
     *  {@code rank_idx} the server returns for this bucket, so it must
     *  reflect the user's primary advertised style or the slider gates
     *  the wrong rank.
     *
     *  <p>When the user toggles styles inside the lobby, callers should
     *  re-invoke this method with an updated {@code sortBucket} so the
     *  next roster push carries fresh per-bucket ranks. */
    void joinLobby(String region, Set<Style> styles, Set<BuildType> builds,
                   int minDisplayRankIdx, int maxDisplayRankIdx, String sortBucket);

    /** Pushes a slider-bound change to the server so other clients can
     *  grey the local user's row when the viewer is outside the
     *  newly-set range. The plugin throttles outbound frames so this
     *  method is safe to call on every {@code RangeSlider} commit —
     *  the implementation guarantees no more than one
     *  {@code lobby/update_range} cmd fires per
     *  {@code RANGE_UPDATE_MIN_INTERVAL_MS} (5 s) per client, with the
     *  latest values coalesced into a single trailing-edge send when
     *  the user drags rapidly.
     *
     *  <p>Default implementation is a no-op so {@link NoOpLobbyService}
     *  and any future stubs don't have to override. Wire encoding when
     *  overridden:
     *
     *  <pre>{ "cmd": "lobby/update_range",
     *    "data": { "min_rank_idx": &lt;int&gt;, "max_rank_idx": &lt;int&gt; } }</pre> */
    default void updateRankRange(int minRankIdx, int maxRankIdx) { /* no-op */ }

    /** Minimum interval (ms) between consecutive
     *  {@code lobby/update_range} sends per client. Plugin-side
     *  throttle pinned at 5 s by the 2026-05-26 design decision so a
     *  user dragging the slider can't flood the server. The server
     *  treats anything below this cadence as a no-op (defence-in-
     *  depth) but the canonical enforcement is here on the client. */
    long RANGE_UPDATE_MIN_INTERVAL_MS = 5_000L;

    /** Asks the server to remove the local user from the lobby. Outstanding
     *  outgoing invites and active fight sessions are cancelled server-side.
     *
     *  <p>Equivalent to {@link #leaveLobby(boolean) leaveLobby(false)} — a
     *  permanent leave that clears the cached join args so a subsequent
     *  reconnect does not silently re-join the user. */
    default void leaveLobby() { leaveLobby(false); }

    /** Asks the server to remove the local user from the lobby.
     *
     *  <p>When {@code preserveReplayState} is {@code true}, the service
     *  keeps the last {@code joinLobby(...)} args around so that the
     *  next socket {@code onOpen} re-issues them automatically. This is
     *  the path the plugin uses for transient {@code LOGIN_SCREEN}
     *  disconnects: the server-side row must be removed (so peers stop
     *  seeing a dead invite target) but the user is going to log back
     *  in moments later and should be auto-re-joined.
     *
     *  <p>When {@code preserveReplayState} is {@code false}, the cached
     *  args are cleared and the user remains out of the lobby across
     *  reconnects until something explicitly calls {@link #joinLobby}
     *  again. This is the path for "Reset Options" and plugin
     *  shutdown. */
    void leaveLobby(boolean preserveReplayState);

    /** Sends an invite to {@code opponent} with the picked {@code style},
     *  {@code build} (which of the opponent's advertised builds you want to
     *  fight), and {@code location} (sub-location string, e.g. "Arena",
     *  "Wildy", "FFA Portal", "Wilderness", "Clan Wars", or "" if the style
     *  has no sub-location). */
    void sendInvite(LobbyMember opponent, Style style, BuildType build, String location);

    /** Cancels a pending outgoing invite to {@code opponent}. No-op if there
     *  is no outstanding invite for that opponent. */
    void cancelInvite(LobbyMember opponent);

    /** Accepts an incoming invite. Server transitions to the 30-s
     *  mutual-confirm phase and pushes {@link LobbyEventListener#onFightProposed}
     *  to both players. */
    void acceptInvite(IncomingInvite invite);

    /** Declines an incoming invite. No follow-up event is pushed to the
     *  recipient (the server removes the invite silently). */
    void declineInvite(IncomingInvite invite);

    /** Confirms the local user's side of the currently-active fight session.
     *  If the peer has already confirmed, the server transitions to
     *  {@link LobbyEventListener#onMatchFound}; otherwise the peer sees
     *  {@link LobbyEventListener#onFightConfirmedByPeer}. */
    void confirmFight();

    /** Adds {@code member} to the local user's block list. Subsequent
     *  invites between the two are dropped server-side; mutual hide policy
     *  applies. */
    void block(LobbyMember member);

    /** Removes {@code member} from the local user's block list. Idempotent. */
    void unblock(LobbyMember member);

    /** Same as {@link #block(LobbyMember)} for callers that hold only
     *  a player id (e.g. the Player-Lookup-tab Block button on
     *  {@code DashboardPanel}, which has no full {@link LobbyMember}).
     *  The wire encoding is identical: {@code lobby/block} with
     *  {@code blocked_player_id=<id>}. Null/empty/blank ids are
     *  silently dropped — defence-in-depth against a UI bug shipping
     *  a malformed frame to the server (which auto-bans on
     *  malformed input). Default impl is a no-op so the
     *  {@link NoOpLobbyService} test stub doesn't have to override. */
    default void blockById(String playerId) { /* no-op default */ }

    /** Same as {@link #unblock(LobbyMember)} for callers that hold
     *  only a player id. Wire encoding is identical to
     *  {@link #unblock(LobbyMember)}. Idempotent; null/empty/blank
     *  ids are silently dropped. */
    default void unblockById(String playerId) { /* no-op default */ }

    /** {@code true} when the underlying transport (WebSocket in
     *  production) is in the open state. Drives the lobby panel's
     *  reconnect banner so the user gets visible feedback when the
     *  socket has dropped and the manager is in the slow-retry
     *  window. Default {@code true} keeps the no-op service from
     *  showing the banner on construction. */
    default boolean isConnected() { return true; }

    /** Epoch ms when the underlying transport is scheduled to make
     *  its next reconnect attempt, or {@code 0} if no retry is
     *  pending (either because the socket is connected, or because
     *  the manager has no active intent — e.g. pre-login).
     *
     *  <p>Used by the panel's 1Hz banner ticker to render the
     *  "XX seconds remaining until next reconnect attempt" countdown.
     *  Default {@code 0} keeps the no-op service from feeding the
     *  panel a bogus countdown. */
    default long getNextReconnectAttemptEpochMs() { return 0L; }

    /** Hint that the user has just opened a Player Lookup for
     *  {@code playerName} (or otherwise triggered a fresh {@code /user}
     *  profile pull). Implementations should clear any negative shard
     *  caches keyed on this player and re-run lobby rank enrichment
     *  so a "Waiting" chip caused by a transient shard miss flips to
     *  the resolved rank without waiting for the next periodic
     *  retry. No-op for transports without a rank cache. */
    default void refreshRankForPlayer(String playerName) { /* no-op */ }
}

package com.pvp.leaderboard.lobby;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Localized message lookup for {@code error/lobby} envelope codes. The
 * server sends a debug {@code message} field too but it's English-only
 * and subject to change without notice — the plugin must never display
 * the raw {@code message} directly, only the localized one from here.
 *
 * <p>Unknown codes fall back to a generic "Something went wrong" so a
 * server that introduces a new error code without a plugin release
 * doesn't surface a raw enum to the user.
 */
public final class LobbyErrorMessages
{
    /** Generic fallback for codes the plugin's version of the map
     *  doesn't recognise. Intentionally vague — we don't know what
     *  happened, only that something failed. */
    public static final String UNKNOWN_FALLBACK = "Something went wrong. Try again in a moment.";

    /** Stable code → user-facing string map. Keep in sync with the
     *  server-side error enum every time a new code is added. */
    private static final Map<String, String> MESSAGES;
    static
    {
        Map<String, String> m = new HashMap<>();
        // ---- Join validation ----
        m.put("UNKNOWN_REGION",
            "That region isn't supported. Pick one from the dropdown and try again.");
        m.put("INVALID_STYLE",
            "One of your selected styles isn't supported. Reset options and try again.");
        m.put("INVALID_BUILD",
            "Your build pick isn't supported. Reset options and try again.");
        m.put("INVALID_LOCATION",
            "That fight location isn't supported. Pick a different one.");
        m.put("INVALID_DISPLAY_RANK",
            "Your rank range is invalid. Adjust the rank slider and try again.");
        m.put("SMURF_GUARD",
            "You need 20 kills or deaths in this style before you can queue for it. "
            + "Play casual PvP to build up your match count.");

        // ---- Invite / accept / confirm ----
        m.put("PEER_NOT_IN_LOBBY",
            "That player just left the lobby. Pick someone else.");
        m.put("RANK_OUT_OF_RANGE",
            "That player is outside your rank range. Widen your rank slider or pick someone else.");
        m.put("BLOCKED",
            "You can't fight this player — one of you has blocked the other.");
        m.put("DUPLICATE_INVITE",
            "You already have an outstanding invite to that player. Wait for the timer to expire "
            + "or cancel it from the lobby.");
        m.put("INVITE_EXPIRED",
            "That invite expired before you could accept it.");
        m.put("MATCHMAKING_SUSPENDED",
            "That player is suspended from matchmaking right now.");
        m.put("FIGHT_SESSION_EXPIRED",
            "The 30-second confirm window expired. Send a new invite to retry.");
        m.put("SELF_INVITE",
            "You can't fight your own account.");

        // ---- Protocol / transport ----
        m.put("INVALID_MESSAGE",
            "The plugin sent a message the server didn't understand. This is a plugin bug — please report it.");
        m.put("UNKNOWN_COMMAND",
            "The plugin sent a command the server doesn't support. The server may be older than your plugin "
            + "build — try again later.");

        MESSAGES = Collections.unmodifiableMap(m);
    }

    /** Look up the localized message for {@code code}, or
     *  {@link #UNKNOWN_FALLBACK} if the code is unrecognised / null /
     *  empty. Never returns {@code null}. */
    public static String forCode(String code)
    {
        if (code == null || code.isEmpty()) return UNKNOWN_FALLBACK;
        String msg = MESSAGES.get(code);
        return msg != null ? msg : UNKNOWN_FALLBACK;
    }

    /** Returns {@code true} if {@code code} is one the plugin knows about
     *  — useful for tests that want to assert wire-side codes have
     *  matching client-side translations (i.e. that we don't ship a
     *  build whose error UX is half-localized). */
    public static boolean isKnown(String code)
    {
        return code != null && MESSAGES.containsKey(code);
    }

    private LobbyErrorMessages() { /* static-only */ }
}

package com.pvp.leaderboard.lobby;

/**
 * An invite the local user has sent but the opponent hasn't accepted yet.
 * Returned indirectly via {@link LobbyService#sendInvite} for the panel's
 * {@code [Invited M:SS]} chip state on the sender's row.
 *
 * <p>{@link #expiresAtEpochMs} is the absolute wall-clock instant the invite
 * lapses (10 min from server-stamped {@code createdAtEpochMs} matching the
 * server's {@code LOBBY_INVITE_TTL_SEC=600}). When it elapses, the panel
 * removes the chip and re-enables {@code [Fight]} on the opponent's row.
 *
 * <p>Pure immutable data carrier — timer ownership lives in the service
 * implementation, not on this type.
 */
public final class OutgoingInvite
{
    public final String inviteId;
    public final LobbyMember opponent;
    public final Style style;
    public final BuildType build;
    public final String location;
    public final long createdAtEpochMs;
    public final long expiresAtEpochMs;

    public OutgoingInvite(String inviteId, LobbyMember opponent, Style style, BuildType build,
                          String location, long createdAtEpochMs, long expiresAtEpochMs)
    {
        this.inviteId = inviteId;
        this.opponent = opponent;
        this.style = style;
        this.build = build;
        this.location = location;
        this.createdAtEpochMs = createdAtEpochMs;
        this.expiresAtEpochMs = expiresAtEpochMs;
    }
}

package com.pvp.leaderboard.lobby;

/**
 * An invite the local user has received. Pushed by the server via
 * {@code lobby/invite_received}; the panel pins one card per active invite
 * at the top of the lobby with Accept / Decline buttons + a TTL countdown.
 *
 * <p>{@link #expiresAtEpochMs} is the server-stamped wall-clock instant
 * the invite expires (10 min from {@code created_at}). The panel
 * computes the visible countdown locally against this absolute deadline
 * so client clock drift doesn't shift the visible expiry.
 *
 * <p>The {@link #build} field carries the sender's pick of which of
 * <i>your</i> advertised builds they want to fight.
 */
public final class IncomingInvite
{
    public final String inviteId;
    public final LobbyMember sender;
    public final Style style;
    public final BuildType build;
    public final String location;
    public final long expiresAtEpochMs;

    public IncomingInvite(String inviteId, LobbyMember sender, Style style, BuildType build,
                          String location, long expiresAtEpochMs)
    {
        this.inviteId = inviteId;
        this.sender = sender;
        this.style = style;
        this.build = build;
        this.location = location;
        this.expiresAtEpochMs = expiresAtEpochMs;
    }
}

package com.pvp.leaderboard.lobby;

import java.util.Set;

/**
 * Fallback {@link LobbyService} used when {@link
 * com.pvp.leaderboard.ui.DashboardPanel} is constructed without an
 * injected service (e.g. in unit tests that don't wire matchmaking).
 *
 * <p>Every command is a silent no-op and no event is ever pushed back
 * to the registered {@link LobbyEventListener}, so the panel renders
 * an empty roster (no rows, no incoming-invite cards, 0 players online)
 * and every gate / fight / invite UI affordance does nothing when
 * clicked. Production wiring supplies {@code WebSocketLobbyService}
 * instead.
 */
public final class NoOpLobbyService implements LobbyService
{
    /** Cached listener so callers can still set + replace it without NPE;
     *  never invoked. */
    @SuppressWarnings("unused")
    private LobbyEventListener listener;

    @Override public void setListener(LobbyEventListener listener) { this.listener = listener; }
    @Override public void start() { /* nothing to start */ }
    @Override public void stop() { /* nothing to stop */ }

    @Override public void joinLobby(String region, Set<Style> styles, Set<BuildType> builds,
                                    int minDisplayRankIdx, int maxDisplayRankIdx,
                                    String sortBucket) { /* no-op */ }
    @Override public void leaveLobby(boolean preserveReplayState) { /* no-op */ }
    @Override public void sendInvite(LobbyMember opponent, Style style, BuildType build, String location) { /* no-op */ }
    @Override public void cancelInvite(LobbyMember opponent) { /* no-op */ }
    @Override public void acceptInvite(IncomingInvite invite) { /* no-op */ }
    @Override public void declineInvite(IncomingInvite invite) { /* no-op */ }
    @Override public void confirmFight() { /* no-op */ }
    @Override public void block(LobbyMember member) { /* no-op */ }
    @Override public void unblock(LobbyMember member) { /* no-op */ }
}

package com.pvp.leaderboard.lobby;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Wire-protocol codec for the lobby's {@code location} field.
 *
 * <p>The {@link MatchmakingLobbyPanel}'s sub-location pickers
 * surface display strings — {@code "Arena"} / {@code "Wildy"} /
 * {@code "FFA Portal"} for NH and {@code "Wilderness"} /
 * {@code "Clan Wars"} for Multi — while the backend's
 * {@code ALLOWED_LOCATIONS_BY_STYLE} validator
 * (in {@code backend/core/lobby.py}) expects a tight canonical enum
 * {@code {arena, wildy, ffa, wilderness, clan_wars, none}} on the
 * wire. Without translation the picker would send {@code "FFA Portal"}
 * and the server would reject the invite with {@code INVALID_LOCATION}
 * before the row was even minted (operator report 2026-05-25 — exact
 * symptom on the screenshot of the {@code "That fight location isn't
 * supported. Pick a different one."} toast).
 *
 * <p>This codec is the single point of conversion at the wire
 * boundary in {@link WebSocketLobbyService}. The {@link
 * MatchmakingLobbyPanel}'s in-memory {@link OutgoingInvite} /
 * {@link IncomingInvite} / {@link FightSession} continue to carry
 * <strong>display</strong> strings so the existing UI render paths
 * ({@code inviteLocationLabel}, {@code formatStyleBuildPlace},
 * {@code meetAtPlace}) read cleanly without churn.
 *
 * <p><strong>Symmetry with the backend.</strong> The backend has a
 * <em>lenient</em> validator layer (commit
 * {@code p2-lobby-location-display-aliases}, 2026-05-25) that also
 * accepts the plugin's display strings as aliases — kept as
 * defense-in-depth + back-compat for older plugin builds. With this
 * codec live, the wire is canonical end-to-end and the backend's
 * lenient layer is a no-op for new clients.
 *
 * <p><strong>Veng / DMM convention.</strong> Those styles have no
 * sub-location picker — the panel passes {@code null} or
 * {@code ""} when constructing invites. The backend's canonical
 * sentinel for "world-only, no sub-location" is the literal string
 * {@code "none"}. {@link #toCanonical} maps both
 * {@code (VENG, null)} and {@code (DMM, "")} (and every combination
 * thereof) to {@code "none"}; {@link #toDisplay} maps {@code "none"}
 * back to {@code ""} so the panel's render path falls through to
 * {@code inviteLocationLabel}'s "PvP World" / "DMM World"
 * per-style default.
 */
public final class LobbyLocationCodec
{
    /** (style, lowercased-display) → canonical wire string. */
    private static final Map<String, String> DISPLAY_TO_CANONICAL;

    /** canonical wire string → display string for the panel. */
    private static final Map<String, String> CANONICAL_TO_DISPLAY;

    static
    {
        Map<String, String> d2c = new HashMap<>();
        // NH picker — the strings come from MatchmakingLobbyPanel.NH_LOCATIONS.
        d2c.put(key(Style.NH, "arena"),       "arena");
        d2c.put(key(Style.NH, "wildy"),       "wildy");
        d2c.put(key(Style.NH, "ffa portal"),  "ffa");
        d2c.put(key(Style.NH, "ffa"),         "ffa");
        // Multi picker — from MatchmakingLobbyPanel.MULTI_LOCATIONS.
        d2c.put(key(Style.MULTI, "wilderness"),  "wilderness");
        d2c.put(key(Style.MULTI, "clan wars"),   "clan_wars");
        d2c.put(key(Style.MULTI, "clan_wars"),   "clan_wars");
        // Veng / DMM — null/empty/literal "none" all collapse to canonical "none".
        d2c.put(key(Style.VENG, ""),     "none");
        d2c.put(key(Style.VENG, "none"), "none");
        d2c.put(key(Style.DMM,  ""),     "none");
        d2c.put(key(Style.DMM,  "none"), "none");
        DISPLAY_TO_CANONICAL = Collections.unmodifiableMap(d2c);

        Map<String, String> c2d = new HashMap<>();
        c2d.put("arena",      "Arena");
        c2d.put("wildy",      "Wildy");
        c2d.put("ffa",        "FFA Portal");
        c2d.put("wilderness", "Wilderness");
        c2d.put("clan_wars",  "Clan Wars");
        // "none" is the world-only sentinel — render as empty so the
        // panel's existing inviteLocationLabel(...) chooses the
        // "PvP World" / "DMM World" per-style default.
        c2d.put("none",       "");
        CANONICAL_TO_DISPLAY = Collections.unmodifiableMap(c2d);
    }

    private LobbyLocationCodec()
    {
        // Utility class.
    }

    /**
     * Converts a picker-side display string into the canonical wire
     * string the server's {@code ALLOWED_LOCATIONS_BY_STYLE} expects.
     *
     * <p>Unknown strings are lowercased and returned verbatim — the
     * server then issues {@code INVALID_LOCATION} which surfaces as
     * the {@code LobbyErrorMessages.INVALID_LOCATION} toast in the
     * panel. This is intentional: the codec is whitelist-only on the
     * canonicalisation side, NOT on the rejection side.
     *
     * <p>{@code style == null} is a programming error (caller bug);
     * we return {@code ""} rather than NPE so the wire-side framing
     * still produces a JSON payload the server can reject cleanly.
     */
    public static String toCanonical(Style style, String displayOrNull)
    {
        if (style == null)
        {
            return "";
        }
        String d = displayOrNull == null ? "" : displayOrNull.trim().toLowerCase();
        String hit = DISPLAY_TO_CANONICAL.get(key(style, d));
        return hit != null ? hit : d;
    }

    /**
     * Converts a server-canonical wire string back into the
     * picker-side display string the panel renders.
     *
     * <p>{@code null} / empty / unrecognised inputs pass through
     * (empty stays empty; unrecognised renders verbatim so it
     * surfaces in CloudWatch-via-debug-logs rather than vanishing).
     */
    public static String toDisplay(String canonicalOrNull)
    {
        if (canonicalOrNull == null)
        {
            return "";
        }
        String hit = CANONICAL_TO_DISPLAY.get(canonicalOrNull);
        return hit != null ? hit : canonicalOrNull;
    }

    private static String key(Style style, String lowercasedDisplay)
    {
        return style.name() + "|" + lowercasedDisplay;
    }
}

package com.pvp.leaderboard.lobby;

/**
 * Terminal "Meet at" view payload pushed when both players have confirmed
 * the fight. Sent by the server via {@code lobby/match_found}.
 *
 * <p>{@link #world} is the world number the players should world-hop to
 * (e.g. {@code "W370"} for NA Arena), resolved server-side per the
 * style + location + both players' regions. The client renders this
 * verbatim — no client-side world-picking — so the world tables can be
 * updated server-side without a plugin release. {@link #meetingPlace}
 * is the in-game meeting spot per style+location (e.g. {@code "Arena"},
 * {@code "Ferox Enclave"}, {@code "Grand Exchange"}), also resolved
 * server-side.
 *
 * <p>Pure immutable data carrier. The panel renders this in its Meet-At
 * view (the terminal state of the fight flow).
 */
public final class MatchInfo
{
    public final String fightSessionId;
    public final LobbyMember opponent;
    public final Style style;
    public final BuildType build;
    public final String location;
    public final String world;
    public final String meetingPlace;

    public MatchInfo(String fightSessionId, LobbyMember opponent, Style style, BuildType build,
                     String location, String world, String meetingPlace)
    {
        this.fightSessionId = fightSessionId;
        this.opponent = opponent;
        this.style = style;
        this.build = build;
        this.location = location;
        this.world = world;
        this.meetingPlace = meetingPlace;
    }
}
